def _ring_derive_config(path, _probe_wall=None) -> tuple[Any, dict, dict, int, str] | None:
    """Derive the ZImage model_config from the safetensors header only (no
    payload), mirroring comfy.sd.load_diffusion_model_state_dict's config
    path.  Returns (config, meta_sd, header, n_layers, eff_prefix) or None.
    ``unet_prefix_from_state_dict`` returns the heuristic default "model."
    when no candidate prefix matches (the unprefixed ZImage case); the
    effective prefix is "" when the strip fell back to the meta sd."""
    try:
        import torch as _torch_rd
        _header = _c6_parse_safetensors_header(path)
        if _header is None:
            return None
        _meta_sd = _c6_build_meta_sd(_header)
        if not _meta_sd:
            return None
        _prefix_fn = _c6_comfy_fn("comfy.model_detection", "unet_prefix_from_state_dict")
        _strip_fn = _c6_comfy_fn("comfy.utils", "state_dict_prefix_replace")
        _calc_fn = _c6_comfy_fn("comfy.utils", "calculate_parameters")
        _wd_fn = _c6_comfy_fn("comfy.utils", "weight_dtype")
        _cfg_fn = _c6_comfy_fn("comfy.model_detection", "model_config_from_unet")
        if any(_fn is None for _fn in (_prefix_fn, _strip_fn, _calc_fn, _wd_fn, _cfg_fn)):
            return None
        _prefix = str(_prefix_fn(_meta_sd) or "")
        _stripped = _meta_sd
        if _prefix:
            try:
                _stripped = _strip_fn(dict(_meta_sd), {_prefix: ""}, filter_keys=True)
                if not _stripped:
                    _stripped = _meta_sd
            except Exception:
                _stripped = _meta_sd
        _eff_prefix = _prefix if _stripped is not _meta_sd else ""
        _metadata = _header.get("__metadata__")
        _config = _cfg_fn(_stripped, "", metadata=_metadata)
        if _config is None:
            return None
        _n_layers = int((getattr(_config, "unet_config", None) or {}).get("n_layers") or 0)
        _vp_t0 = time.monotonic_ns()
        _allow_fp16 = _c6_value_probe_allow_fp16(path, _header, _n_layers)
        if _probe_wall is not None:
            try:
                _probe_wall["value_probe_wall_ms"] = round(
                    (time.monotonic_ns() - _vp_t0) / 1_000_000, 4)
            except Exception:
                pass
        if _allow_fp16 is None:
            return None
        if _allow_fp16:
            _ext_fp16_fn = _c6_comfy_fn("comfy.model_management", "extended_fp16_support")
            _ext = False
            if _ext_fp16_fn is not None:
                try:
                    _ext = bool(_ext_fp16_fn())
                except Exception:
                    _ext = False
            _supported = list(getattr(_config, "supported_inference_dtypes", None) or [])
            if _ext and _torch_rd.float16 not in _supported:
                _bf = _supported.index(_torch_rd.bfloat16) if _torch_rd.bfloat16 in _supported else -1
                _supported.insert(_bf + 1 if _bf >= 0 else len(_supported), _torch_rd.float16)
                try:
                    _config.supported_inference_dtypes = _supported
                except Exception:
                    pass
            _uc = getattr(_config, "unet_config", None)
            if isinstance(_uc, dict):
                _uc["allow_fp16"] = True
        else:
            _uc = getattr(_config, "unet_config", None)
            if isinstance(_uc, dict):
                _uc["allow_fp16"] = False
        _unet_dtype_fn = _c6_comfy_fn("comfy.model_management", "unet_dtype")
        _manual_cast_fn = _c6_comfy_fn("comfy.model_management", "unet_manual_cast")
        _offload_fn = _c6_comfy_fn("comfy.model_management", "unet_offload_device")
        if _unet_dtype_fn is not None and _manual_cast_fn is not None:
            _params = _calc_fn(_stripped)
            _wd = _wd_fn(_stripped)
            _supported = list(getattr(_config, "supported_inference_dtypes", None) or [])
            _unet_dtype = _unet_dtype_fn(
                model_params=_params, supported_dtypes=_supported, weight_dtype=_wd)
            _load_device = None
            if _offload_fn is not None:
                try:
                    _load_device = _offload_fn()
                except Exception:
                    _load_device = None
            try:
                _manual_cast = _manual_cast_fn(_unet_dtype, _load_device, _supported)
            except Exception:
                _manual_cast = None
            _set = getattr(_config, "set_inference_dtype", None)
            if callable(_set):
                try:
                    _set(_unet_dtype, _manual_cast)
                except Exception:
                    pass
        return (_config, _stripped, _header, _n_layers, _eff_prefix)
    except Exception:
        return None


def _ring_resolve_unet_path(unet_name, lane) -> str | None:
    """Resolve the UNET file path for the pinned-ring pipeline.  ComfyUI's
    path module is the top-level ``folder_paths`` (``comfy.folder_paths``
    does not exist); prefer ``get_full_path_or_raise`` with a
    ``get_full_path`` fallback, then the lane trace's ``resolved_path``.
    Never raises; None when unresolvable."""
    _name = str(unet_name or "")
    if not _name:
        return None
    _fp = None
    try:
        import folder_paths as _fp_mod
        _fp = _fp_mod
    except Exception:
        _fp = None
    if _fp is not None:
        _or_raise = getattr(_fp, "get_full_path_or_raise", None)
        if _or_raise is not None:
            try:
                _p = _or_raise("diffusion_models", _name)
                if _p:
                    return str(_p)
            except Exception:
                pass
        _plain = getattr(_fp, "get_full_path", None)
        if _plain is not None:
            try:
                _p = _plain("diffusion_models", _name)
                if _p:
                    return str(_p)
            except Exception:
                pass
    try:
        _md = getattr(getattr(lane, "_trace", None), "_metadata", None) or {}
        _rp = _md.get("resolved_path") or ""
        if _rp:
            return str(_rp)
    except Exception:
        pass
    return None


def _ring_eligible(record, model_key, kwargs, lane) -> tuple[bool, str]:
    """Production pinned-ring eligibility gate (conditions 1-10; the caller
    has already checked the flag).  Derives the header config internally;
    any failure returns (False, named_reason)."""
    try:
        import torch as _torch_re
        _unet_name = str(kwargs.get("unet_name", "") or "")
        _path = _ring_resolve_unet_path(_unet_name, lane)
        if not _path:
            return (False, "path_unresolved")
        _derived = _ring_derive_config(_path)
        if _derived is None:
            return (False, "config_derivation_failed")
        _config, _meta_sd, _header, _n_layers, _prefix = _derived
        if type(_config).__name__ != "ZImage":
            return (False, "family_not_zimage")
        _allow = _c6_value_probe_allow_fp16(_path, _header, _n_layers)
        if _allow is None:
            return (False, "value_probe_unresolved")
        if not _fast_disk_high_vram():
            return (False, "not_high_vram")
        if _fast_disk_torch_future_enabled():
            return (False, "torch_future")
        _evidence = _fast_disk_model_config_evidence(_config)
        if _evidence.get("quant_config_present"):
            return (False, "quant_config_present")
        if _evidence.get("custom_operations_present"):
            return (False, "custom_operations_present")
        if _evidence.get("fp8_optimization"):
            return (False, "fp8_optimization")
        if _evidence.get("force_channels_last"):
            return (False, "force_channels_last")
        _req_wd = str(kwargs.get("weight_dtype", "default") or "default")
        if _req_wd != "default":
            return (False, "dtype_conversion_requested")
        _dtypes = set()
        for _k, _info in _header.items():
            if _k == "__metadata__":
                continue
            _dt = _info.get("dtype", "")
            if _dt:
                _dtypes.add(_dt)
        if len(_dtypes) != 1:
            return (False, "non_uniform_dtype")
        _sd_dt = _c6_safetensors_dtype_map().get(_dtypes.pop())
        if _sd_dt is None:
            return (False, "unsupported_dtype")
        _supported = list(getattr(_config, "supported_inference_dtypes", None) or [])
        if _sd_dt not in _supported:
            return (False, "unsupported_dtype")
        try:
            if not _torch_re.cuda.is_available():
                return (False, "cuda_unavailable")
        except Exception:
            return (False, "cuda_unavailable")
        try:
            _mgmt = _c6_comfy_fn("comfy.model_management", "get_torch_device")
            _target = _mgmt() if _mgmt is not None else None
        except Exception:
            _target = None
        if _target is None or str(getattr(_target, "type", "") or "").lower() != "cuda":
            return (False, "cuda_unavailable")
        try:
            _p = _torch_re.empty(1 * 1024 * 1024 // 2, dtype=_torch_re.float16, pin_memory=True)
            del _p
        except Exception:
            return (False, "pinned_unavailable")
        return (True, "")
    except Exception:
        return (False, "eligibility_error")


def _ring_wave_build(keys, bytes_map, target_bytes=_RING_WAVE_TARGET_BYTES,
                     max_bytes=_RING_MAX_WAVE_BYTES) -> list[list[str]] | None:
    """Pack header-order keys into waves: tensors larger than the target get
    their own wave; small tensors pack until the target.  A single tensor
    over max_bytes returns None (tensor_exceeds_wave_cap)."""
    _waves: list[list[str]] = []
    _cur: list[str] = []
    _cur_bytes = 0
    for _k in keys:
        _b = int(bytes_map.get(_k, 0))
        if _b > max_bytes:
            return None
        if _b > target_bytes:
            if _cur:
                _waves.append(_cur)
                _cur = []
                _cur_bytes = 0
            _waves.append([_k])
            continue
        if _cur and _cur_bytes + _b > target_bytes:
            _waves.append(_cur)
            _cur = []
            _cur_bytes = 0
        _cur.append(_k)
        _cur_bytes += _b
    if _cur:
        _waves.append(_cur)
    return _waves


def _ring_emit(status, reason, metrics, trace=None) -> None:
    """Lean production telemetry: one unet_pinned_ring_pipeline event
    (JSON-safe) plus one console line."""
    try:
        _m = _c6_json_safe(dict(metrics))
        _m["status"] = status
        _m["reason"] = reason or ""
        if trace is not None:
            trace.emit("unet_pinned_ring_pipeline", phase="restore", metadata=_m)
    except Exception as _exc:
        print(f"[v2.pinned_ring] emit_error={type(_exc).__name__}", flush=True)
    try:
        print(
            f"[v2.pinned_ring] status={status} reason={reason or ''} "
            f"waves={metrics.get('wave_count')} "
            f"total_wall_ms={metrics.get('total_pipeline_wall_ms')} "
            f"hidden_overlap_ms={metrics.get('hidden_overlap_ms')}",
            flush=True,
        )
    except Exception:
        pass


def _ring_run_waves(model, params, path, header, waves, lane, prefix="", target=None, torch_mod=None, buffers=None) -> tuple[dict, Any, list] | None:
    """Pinned-ring wave H2D runner: two flat typed pinned slots, one event
    pair per wave, incremental ``param.data`` binding.  Returns
    (metrics, file_ctx, wave_events) or None on failure.  Never synchronizes
    beyond the per-slot reuse waits (the single final sync is the caller's)."""
    import torch as _torch_rw
    _torch = torch_mod if torch_mod is not None else _torch_rw
    _pin_slots: list[Any] = [None, None]
    _pin_numelems: list[int] = [0, 0]
    _pin_dtypes: list[Any] = [None, None]
    _ev_pending: list[Any] = [None, None]
    _dests: dict[str, Any] = {}
    _open = None
    _metrics: dict[str, Any] = {
        "read_pagein_wall_ms": 0.0, "cpu_staging_wall_ms": 0.0,
        "h2d_host_issue_wall_ms": 0.0, "reuse_wait_total_ms": 0.0,
        "max_reuse_wait_ms": 0.0, "pinned_alloc_bytes": 0,
    }
    _wave_events: list[tuple[Any, Any, dict[str, Any]]] = []
    try:
        try:
            import safetensors as _st_ring
            _open = _st_ring.safe_open(path, framework="pt", device="cpu")
        except Exception as _exc:
            return (None, "safe_open:" + type(_exc).__name__)
        try:
            _open.__enter__()
        except AttributeError:
            pass
        for _w_idx, _wave_keys in enumerate(waves):
            _s = _w_idx % 2
            _wm: dict[str, Any] = {"keys": _wave_keys, "bytes": 0, "stage_ms": 0.0,
                                   "issue_ms": 0.0, "device_ms": None, "reuse_wait_ms": None}
            if _ev_pending[_s] is not None:
                _t0 = time.monotonic_ns()
                try:
                    _ev_pending[_s].synchronize()
                except Exception:
                    pass
                _t1 = time.monotonic_ns()
                _wait_ms = round((_t1 - _t0) / 1_000_000, 4)
                _wm["reuse_wait_ms"] = _wait_ms
                _metrics["reuse_wait_total_ms"] += _wait_ms
                _metrics["max_reuse_wait_ms"] = max(_metrics["max_reuse_wait_ms"], _wait_ms)
                _ev_pending[_s] = None
            # source read (pageable) into per-wave list; compute offsets
            _srcs: list[Any] = []
            _offsets: list[tuple[str, Any, int, int]] = []
            _wave_numelem = 0
            _wave_bytes = 0
            _dt = None
            _read_t0 = time.monotonic_ns()
            try:
                for _k in _wave_keys:
                    _full = (prefix + _k) if prefix and not _k.startswith(prefix) else _k
                    _t = _open.get_tensor(_full)
                    _srcs.append(_t)
                    _n = int(_t.numel())
                    _offsets.append((_k, _t, _wave_numelem, _wave_numelem + _n))
                    _wave_numelem += _n
                    _wave_bytes += int(_n) * int(_t.element_size())
                    _dt = _t.dtype
            except Exception as _exc:
                return (None, "read:" + type(_exc).__name__)
            _read_t1 = time.monotonic_ns()
            _wm["bytes"] = _wave_bytes
            _metrics["read_pagein_wall_ms"] += round((_read_t1 - _read_t0) / 1_000_000, 4)
            # ensure slot capacity (grow-to-largest, realloc replaces)
            if _pin_slots[_s] is None or _pin_numelems[_s] < _wave_numelem:
                _old = _pin_slots[_s]
                try:
                    _pin_slots[_s] = _torch.empty(_wave_numelem, dtype=_dt, pin_memory=True)
                    _pin_numelems[_s] = _wave_numelem
                    _pin_dtypes[_s] = _dt
                    _metrics["pinned_alloc_bytes"] += int(_wave_numelem) * int(_dt.itemsize)
                except Exception as _exc:
                    return (None, "pinned_alloc:" + type(_exc).__name__)
                finally:
                    if _old is not None:
                        try:
                            del _old
                        except Exception:
                            pass
            # STAGE (sync pageable -> pinned)
            _stage_t0 = time.monotonic_ns()
            try:
                for _k, _t, _off0, _off1 in _offsets:
                    _pin_slots[_s][_off0:_off1].view(list(_t.shape)).copy_(_t, non_blocking=False)
            except Exception as _exc:
                return (None, "stage_copy:" + type(_exc).__name__)
            _stage_t1 = time.monotonic_ns()
            _wm["stage_ms"] = round((_stage_t1 - _stage_t0) / 1_000_000, 4)
            _metrics["cpu_staging_wall_ms"] += _wm["stage_ms"]
            # DMA: per-key cuda dests, async enqueue then bind param.data
            _ev_start = _torch.cuda.Event(enable_timing=True)
            _ev_start.record()
            _issue_t0 = time.monotonic_ns()
            try:
                for _k, _t, _off0, _off1 in _offsets:
                    _dest = _torch.empty(list(_t.shape), dtype=_t.dtype, device=target)
                    _dests[_k] = _dest
                    _dest.copy_(_pin_slots[_s][_off0:_off1].view(list(_t.shape)), non_blocking=True)
                    _dst = params.get(_k)
                    if _dst is None and buffers is not None:
                        _dst = buffers.get(_k)
                    if _dst is not None:
                        _dst.data = _dest
            except Exception as _exc:
                return (None, "dma_bind:" + type(_exc).__name__)
            _issue_t1 = time.monotonic_ns()
            _ev_end = _torch.cuda.Event(enable_timing=True)
            _ev_end.record()
            _ev_pending[_s] = _ev_end
            _wm["issue_ms"] = round((_issue_t1 - _issue_t0) / 1_000_000, 4)
            _metrics["h2d_host_issue_wall_ms"] += _wm["issue_ms"]
            _wave_events.append((_ev_start, _ev_end, _wm))
            _srcs.clear()
        return (_metrics, _open, _wave_events)
    except Exception as _exc:
        return (None, "ring_run:" + type(_exc).__name__)
    finally:
        if _open is not None:
            try:
                _open.__exit__(None, None, None)
            except Exception:
                pass
        try:
            for _s in range(2):
                if _pin_slots[_s] is not None:
                    del _pin_slots[_s]
                    _pin_slots[_s] = None
        except Exception:
            pass
        try:
            _dests.clear()
        except Exception:
            pass
        try:
            _torch.cuda.empty_cache()
        except Exception:
            pass


def _ring_fail(metrics, trace, reason, t0_total) -> None:
    """Fallback helper: emit status=fallback with the named stage reason."""
    try:
        metrics.update({
            "status": "fallback", "reason": reason, "fallback_count": 1,
            "total_pipeline_wall_ms": round((time.monotonic_ns() - t0_total) / 1_000_000, 4),
        })
    except Exception:
        pass
    try:
        import torch as _torch_rf
        _torch_rf.cuda.empty_cache()
    except Exception:
        pass
    _ring_emit(metrics.get("status", "fallback"), metrics.get("reason", reason), metrics, trace)
    return None


def _ring_try_pipeline(bridge, model_key, kwargs, lane) -> tuple[Any, ...] | None:
    """Production pinned-ring UNET fast path.  Returns ``(patcher,)`` on
    success (flows through the unchanged _load_unet tail); None on
    ineligible/fallback (the caller then runs ``_invoke_original`` fresh)."""
    _lane = lane if lane is not None else _ACTIVE_LANE_TRACE.get()
    _trace = getattr(_lane, "_trace", None) if _lane is not None else None
    if _trace is None:
        _trace = _ACTIVE_REQUEST_TRACE.get()
    _t0_total = time.monotonic_ns()
    _metrics: dict[str, Any] = {
        "flag": _ring_flag_value(), "eligibility": "ok", "family": "ZImage", "reason": "",
        "header_config_wall_ms": None, "value_probe_wall_ms": None, "get_model_wall_ms": None,
        "param_count": 0, "tensor_count": 0, "total_bytes": 0, "wave_count": 0,
        "wave_target_bytes": _RING_WAVE_TARGET_BYTES, "max_wave_bytes": _RING_MAX_WAVE_BYTES,
        "actual_max_wave_bytes": 0, "actual_mean_wave_bytes": 0, "pinned_alloc_bytes": 0,
        "sd_unmapped_keys": [], "model_only_param_count": 0, "model_only_buffer_count": 0,
        "read_pagein_wall_ms": 0.0, "cpu_staging_wall_ms": 0.0, "h2d_device_wall_ms": 0.0,
        "h2d_host_issue_wall_ms": 0.0, "reuse_wait_total_ms": 0.0, "max_reuse_wait_ms": 0.0,
        "final_model_to_wall_ms": 0.0, "final_sync_wall_ms": 0.0,
        "total_pipeline_wall_ms": 0.0, "serial_equivalent_ms": 0.0, "hidden_overlap_ms": 0.0,
        "fallback_count": 0, "status": "ok",
    }
    _file_ctx = None
    _wave_events: list[tuple[Any, Any, dict[str, Any]]] = []
    _run_metrics: dict[str, Any] = {}
    try:
        import torch as _torch_tp
        _unet_name = str(kwargs.get("unet_name", "") or "")
        _path = _ring_resolve_unet_path(_unet_name, _lane)
        if not _path:
            return _ring_fail(_metrics, _trace, "stage:path_unresolved", _t0_total)
        # S2 eligibility (pre-construction, conditions 1-10)
        _ok, _reason = _ring_eligible(None, model_key, kwargs, _lane)
        if not _ok:
            _metrics.update({"eligibility": "ineligible", "reason": _reason, "status": "ineligible"})
            _ring_emit(_metrics.get("status"), _metrics.get("reason"), _metrics, _trace)
            return None
        # S1 config derivation (header only)
        _t_cfg = time.monotonic_ns()
        _probe_wall: dict[str, Any] = {}
        _derived = _ring_derive_config(_path, _probe_wall=_probe_wall)
        if _derived is None:
            return _ring_fail(_metrics, _trace, "stage:config_derivation_failed", _t0_total)
        _config, _meta_sd, _header, _n_layers, _prefix = _derived
        _metrics["header_config_wall_ms"] = round((time.monotonic_ns() - _t_cfg) / 1_000_000, 4)
        _metrics["value_probe_wall_ms"] = _probe_wall.get("value_probe_wall_ms")
        if type(_config).__name__ != "ZImage":
            _metrics.update({"family": type(_config).__name__, "eligibility": "ineligible",
                             "reason": "family_not_zimage", "status": "ineligible"})
            _ring_emit(_metrics.get("status"), _metrics.get("reason"), _metrics, _trace)
            return None
        # S3 construction (meta sd for signature parity; ZImage ignores payload)
        _t_gm = time.monotonic_ns()
        _model = _config.get_model(_meta_sd, "")
        _metrics["get_model_wall_ms"] = round((time.monotonic_ns() - _t_gm) / 1_000_000, 4)
        # S4 patcher (plain non-dynamic ModelPatcher, mirroring sd.py)
        _mgmt_fn = _c6_comfy_fn("comfy.model_management", "get_torch_device")
        _target = _mgmt_fn() if _mgmt_fn is not None else _torch_tp.device("cuda")
        _offload_fn = _c6_comfy_fn("comfy.model_management", "unet_offload_device")
        _offload = _offload_fn() if _offload_fn is not None else _torch_tp.device("cpu")
        _mp_cls = _c6_comfy_fn("comfy.model_patcher", "ModelPatcher")
        if _mp_cls is None:
            return _ring_fail(_metrics, _trace, "stage:patcher_unavailable", _t0_total)
        _patcher = _mp_cls(_model, load_device=_target, offload_device=_offload)
        # S5 key map + transform identity + uniform dtype.  The authoritative
        # bind (model_base.load_model_weights) strips the unet_prefix and
        # loads into the diffusion_model submodule with strict=False, so the
        # keys are UNPREFIXED and model-only params/buffers are allowed.
        _unet = getattr(_model, "diffusion_model", None) or _model
        _params = dict(_unet.named_parameters())
        _buffers = dict(_unet.named_buffers())
        _metrics["param_count"] = len(_params)
        try:
            _transformed = _config.process_unet_state_dict(dict(_meta_sd))
        except Exception:
            _transformed = None
        if not isinstance(_transformed, dict):
            return _ring_fail(_metrics, _trace, "stage:transform_not_independent", _t0_total)
        _sd_keys = set(_transformed.keys())
        if _sd_keys != set(_meta_sd.keys()):
            return _ring_fail(_metrics, _trace, "stage:transform_not_independent", _t0_total)
        _dest_key_set = set(_params.keys()) | set(_buffers.keys())
        _unmapped = sorted(_k for _k in _sd_keys if _k not in _dest_key_set)
        _metrics["sd_unmapped_keys"] = _unmapped[:20]
        if _unmapped:
            return _ring_fail(_metrics, _trace, "stage:key_param_mismatch", _t0_total)
        _metrics["model_only_param_count"] = sum(
            1 for _k in _params.keys() if _k not in _sd_keys)
        _metrics["model_only_buffer_count"] = sum(
            1 for _k in _buffers.keys() if _k not in _sd_keys)
        _dtypes = set()
        for _k, _info in _header.items():
            if _k == "__metadata__":
                continue
            if _info.get("dtype"):
                _dtypes.add(_info["dtype"])
        if len(_dtypes) != 1:
            return _ring_fail(_metrics, _trace, "stage:non_uniform_dtype", _t0_total)
        _sd_dt = _c6_safetensors_dtype_map().get(_dtypes.pop())
        if _sd_dt is None or _sd_dt not in list(getattr(_config, "supported_inference_dtypes", None) or []):
            return _ring_fail(_metrics, _trace, "stage:unsupported_dtype", _t0_total)
        _dest_dtypes = set()
        for _k in _sd_keys:
            _dst = _params.get(_k)
            if _dst is None:
                _dst = _buffers.get(_k)
            if _dst is None:
                continue
            _dest_dtypes.add(_dst.dtype)
        if not _dest_dtypes or len(_dest_dtypes) != 1 or _sd_dt not in _dest_dtypes:
            return _ring_fail(_metrics, _trace, "stage:dtype_mismatch", _t0_total)
        # S6 waves (header/read order preserved by the stripped meta-sd order)
        _meta_bytes = {k: int(v.numel()) * int(v.element_size()) for k, v in _meta_sd.items()}
        _waves = _ring_wave_build(list(_meta_sd.keys()), _meta_bytes)
        if _waves is None:
            return _ring_fail(_metrics, _trace, "stage:tensor_exceeds_wave_cap", _t0_total)
        _metrics["tensor_count"] = len(_meta_sd)
        _metrics["total_bytes"] = int(sum(_meta_bytes.values()))
        _metrics["wave_count"] = len(_waves)
        _wave_bytes_list = [int(sum(_meta_bytes[k] for k in _w)) for _w in _waves]
        _metrics["actual_max_wave_bytes"] = max(_wave_bytes_list) if _wave_bytes_list else 0
        _metrics["actual_mean_wave_bytes"] = (
            int(sum(_wave_bytes_list) / len(_wave_bytes_list)) if _wave_bytes_list else 0)
        # S7 ring run
        _run_result = _ring_run_waves(_model, _params, _path, _header, _waves, _lane,
                                      prefix=_prefix, target=_target, buffers=_buffers)
        if _run_result is None or _run_result[0] is None:
            _ring_detail = ""
            if isinstance(_run_result, tuple) and len(_run_result) > 1:
                _ring_detail = ":" + str(_run_result[1])
            return _ring_fail(_metrics, _trace, "stage:ring_run" + _ring_detail, _t0_total)
        _run_metrics, _file_ctx, _wave_events = _run_result
        # S8 final model.to (must NOT duplicate the parameter transfer): every
        # sd-mapped param must already be on cuda (ring bind complete); model-only
        # leftovers may stay cpu and are moved by model.to (strict=False parity)
        _unbound_cpu = [k for k in _sd_keys
                        if k in _params and str(_params[k].device).startswith("cpu")]
        if _unbound_cpu:
            return _ring_fail(_metrics, _trace, "stage:ring_bind_incomplete", _t0_total)
        _t_to = time.monotonic_ns()
        try:
            _model.to(_target)
        except Exception:
            return _ring_fail(_metrics, _trace, "stage:final_model_to", _t0_total)
        _metrics["final_model_to_wall_ms"] = round((time.monotonic_ns() - _t_to) / 1_000_000, 4)
        if _metrics["final_model_to_wall_ms"] > 500.0:
            return _ring_fail(_metrics, _trace, "stage:final_to_duplicates_transfer", _t0_total)
        # S9 exactly ONE final synchronize
        _t_sync = time.monotonic_ns()
        try:
            _torch_tp.cuda.synchronize()
        except Exception:
            return _ring_fail(_metrics, _trace, "stage:final_sync", _t0_total)
        _metrics["final_sync_wall_ms"] = round((time.monotonic_ns() - _t_sync) / 1_000_000, 4)
        # wave device elapsed (realized by the final sync)
        _h2d_dev = 0.0
        for _ev_s, _ev_e, _wm in _wave_events:
            try:
                _ms = float(_ev_s.elapsed_time(_ev_e))
            except Exception:
                _ms = None
            _wm["device_ms"] = round(_ms, 4) if _ms is not None else None
            if _ms is not None:
                _h2d_dev += _ms
        _metrics["h2d_device_wall_ms"] = round(_h2d_dev, 4)
        # close the file context after the final sync
        if _file_ctx is not None:
            try:
                _file_ctx.__exit__(None, None, None)
            except Exception:
                pass
            _file_ctx = None
        # S10 totals + emit
        _metrics["pinned_alloc_bytes"] = int(_run_metrics.get("pinned_alloc_bytes", 0))
        _metrics["read_pagein_wall_ms"] = round(float(_run_metrics.get("read_pagein_wall_ms", 0.0)), 4)
        _metrics["cpu_staging_wall_ms"] = round(float(_run_metrics.get("cpu_staging_wall_ms", 0.0)), 4)
        _metrics["h2d_host_issue_wall_ms"] = round(float(_run_metrics.get("h2d_host_issue_wall_ms", 0.0)), 4)
        _metrics["reuse_wait_total_ms"] = round(float(_run_metrics.get("reuse_wait_total_ms", 0.0)), 4)
        _metrics["max_reuse_wait_ms"] = round(float(_run_metrics.get("max_reuse_wait_ms", 0.0)), 4)
        _metrics["total_pipeline_wall_ms"] = round((time.monotonic_ns() - _t0_total) / 1_000_000, 4)
        _metrics["serial_equivalent_ms"] = round(
            (float(_metrics["read_pagein_wall_ms"] or 0)
             + float(_metrics["cpu_staging_wall_ms"] or 0)
             + float(_metrics["h2d_device_wall_ms"] or 0)
             + float(_metrics["get_model_wall_ms"] or 0)
             + float(_metrics["final_model_to_wall_ms"] or 0)
             + float(_metrics["final_sync_wall_ms"] or 0)), 4)
        _metrics["hidden_overlap_ms"] = round(
            max(0.0, float(_metrics["serial_equivalent_ms"]) - float(_metrics["total_pipeline_wall_ms"])), 4)
        _metrics["status"] = "ok"
        _metrics["reason"] = ""
        _ring_emit("ok", "", _metrics, _trace)
        return (_patcher,)
    except Exception as _exc:
        return _ring_fail(_metrics, _trace, f"stage:{type(_exc).__name__}", _t0_total)


# ── V2 A/B experiments (Experiment 1 unet_transfer / Experiment 2
# vae_overlap) ─────────────────────────────────────────────────────────
# Accessors come from ``comfymodal_runtime.v2_experiments`` (the unified
# experiment registry).  Imported defensively: if the module is ever absent
# every accessor falls back to its default so the runtime stays
# byte-for-byte on the baseline arm (default OFF).
try:
    from .v2_experiments import (
        emit_experiment_selection,
        experiment_line,
        resolve_experiment,
        unet_pinned_staging_enabled,
        unet_staging_chunk_mb,
        vae_early_start_ms,
        vae_expected_sampling_ms,
    )
except Exception:  # pragma: no cover - experiments must never break the runtime
    emit_experiment_selection = lambda *a, **k: None  # type: ignore[assignment]
    experiment_line = lambda *a, **k: ""  # type: ignore[assignment]
    resolve_experiment = lambda *a, **k: None  # type: ignore[assignment]
    unet_pinned_staging_enabled = lambda: False  # type: ignore[assignment]
    unet_staging_chunk_mb = lambda: 512  # type: ignore[assignment]
    vae_early_start_ms = lambda: 0  # type: ignore[assignment]
    vae_expected_sampling_ms = lambda: 4900  # type: ignore[assignment]

# ── Page-fault delta tracking for model-path instrumentation ─────
# Uses resource.getrusage (RUSAGE_SELF) to measure major/minor page
# faults around actual first access to restored CLIP/UNET CPU state.
# Deliberately wraps the OUTERMOST invocation of each operation so
# inner nested calls do not double-count.

_PAGEFAULT_TRACKING: bool = observability_gate(
    "COMFYMODAL_V2_PAGEFAULT_TRACKING", "pagefault_tracking", default=True,
)


def sync_observability_gates() -> None:
    """Re-resolve import-time observability gates from the current env.

    ``_PAGEFAULT_TRACKING`` and ``_DIAGNOSTIC_FLAG`` are frozen at import time.
    When ``run_plan_stream`` applies a request env-profile override the
    effective observability mode changes; recompute the module-level gates so
    they agree with call-time ``observability_allows`` checks for that request.
    Recomputing an unchanged env yields identical values (no behavior change).
    """
    global _PAGEFAULT_TRACKING, _DIAGNOSTIC_FLAG
    _PAGEFAULT_TRACKING = observability_gate(
        "COMFYMODAL_V2_PAGEFAULT_TRACKING", "pagefault_tracking", default=True,
    )
    _DIAGNOSTIC_FLAG = observability_gate(
        "COMFYMODAL_V2_DEEP_MODEL_DIAG", "deep_model_diagnostics",
    )


def _is_tensor_channels_last(value: Any) -> bool:
    try:
        import torch
        return bool(
            getattr(value, "ndim", 0) == 4
            and value.is_contiguous(memory_format=torch.channels_last)
        )
    except Exception:
        return False


def _vae_decode_boundary_metadata(
    active: Any,
    vae: Any,
    *,
    trace: RuntimeTrace | None = None,
) -> dict[str, Any]:
    """Assemble the policy + bounded-prefetch metadata block for decode start/end.

    Reads the VAE's applied policy marker and, when present, the active
    bridge's bounded CPU prefetch metrics.  Always returns a plain dict with
    stable keys; never raises.
    """
    result: dict[str, Any] = {
        "vae_object_id": str(id(vae)) if vae is not None else "",
        "vae_policy_version": 0,
        "vae_weight_dtype": "",
        "vae_compute_dtype": "",
        "vae_memory_format": "",
        "vae_prefetch_mode": "",
        "c5_impl_version": C5_IMPL_VERSION,
        "torch_version": "",
        "cuda_version": "",
        "arch_identifier": "",
    }
    if vae is not None:
        policy = getattr(vae, "_comfy_modal_vae_policy", {})
        if isinstance(policy, Mapping):
            for key in ("vae_policy_version", "vae_weight_dtype", "vae_compute_dtype",
                        "vae_memory_format", "vae_prefetch_mode", "c5_impl_version"):
                value = policy.get(key)
                if value not in (None, ""):
                    result[key] = value
        if not result["vae_prefetch_mode"]:
            result["vae_prefetch_mode"] = vae_prefetch_mode()
    _runtime = capture_c5_runtime_metadata()
    result["torch_version"] = _runtime.get("torch_version", "")
    result["cuda_version"] = _runtime.get("cuda_version", "")
    result["arch_identifier"] = _runtime.get("arch_identifier", "")
    prefetch: dict[str, Any] = {}
    try:
        if active is not None:
            prefetch = dict(getattr(active, "_vae_prefetch_state", {}) or {})
    except Exception:
        prefetch = {}
    result.update({
        "prefetch_status": prefetch.get("status", ""),
        "prefetch_start_ms": prefetch.get("result", {}).get("start_ms") if isinstance(prefetch.get("result"), Mapping) else None,
        "prefetch_end_ms": prefetch.get("result", {}).get("end_ms") if isinstance(prefetch.get("result"), Mapping) else None,
        "prefetch_wall_ms": prefetch.get("result", {}).get("wall_ms") if isinstance(prefetch.get("result"), Mapping) else None,
        "prefetch_process_cpu_ms": prefetch.get("result", {}).get("process_cpu_ms") if isinstance(prefetch.get("result"), Mapping) else None,
        "prefetch_effective_cores": prefetch.get("result", {}).get("effective_cores") if isinstance(prefetch.get("result"), Mapping) else None,
        "prefetch_bytes": prefetch.get("result", {}).get("bytes") if isinstance(prefetch.get("result"), Mapping) else None,
        "prefetch_page_count": prefetch.get("result", {}).get("page_count") if isinstance(prefetch.get("result"), Mapping) else None,
        "ready_before_sampling_end": bool(prefetch.get("ready_before_sampling_end", False)),
        "overlap_with_sampling_ms": prefetch.get("overlap_with_sampling_ms", 0.0),
        "prefetch_error": prefetch.get("reason", "") or (prefetch.get("result", {}).get("error") if isinstance(prefetch.get("result"), Mapping) else ""),
    })
    return result


@dataclass
class _PageFaultSnapshot:
    """Snapshot of process page-fault counters at a given moment.

    Reads ``resource.getrusage`` first (Linux).  When that is unavailable
    (or zeroed under gVisor runsc), falls back to ``/proc/self/stat``
    fields 10 (minflt) and 12 (majflt).  When BOTH sources are unavailable
    the snapshot is marked ``unavailable=True`` — it never fakes zero
    deltas (a zero here is indistinguishable from "never measured").
    """
    major: int = 0
    minor: int = 0
    unavailable: bool = False

    @classmethod
    def now(cls) -> "_PageFaultSnapshot":
        try:
            import resource as _r
            ru = _r.getrusage(_r.RUSAGE_SELF)
            return cls(major=ru.ru_majflt, minor=ru.ru_minflt)
        except Exception:
            pass
        # Fallback: /proc/self/stat.  ``comm`` (field 2) may contain spaces
        # or parentheses, so strip it via rfind(')'): the remainder starts
        # at field 3 (state), making field 10 (minflt) index 7 and field 12
        # (majflt) index 9 of that remainder.
        try:
            with open("/proc/self/stat", "r", encoding="utf-8", errors="replace") as _pf_stat_f:
                _pf_stat_line = _pf_stat_f.read()
            _pf_stat_fields = _pf_stat_line[_pf_stat_line.rfind(")") + 2:].split()
            if len(_pf_stat_fields) >= 10:
                return cls(major=int(_pf_stat_fields[9]), minor=int(_pf_stat_fields[7]))
        except Exception:
            pass
        return cls(unavailable=True)


def _pagefault_delta(before: _PageFaultSnapshot, after: _PageFaultSnapshot) -> dict[str, int | None]:
    """Return major/minor fault deltas from two snapshots.

    Returns ``None`` (JSON null) for BOTH counters when either snapshot
    could not be read — never fake zeros.
    """
    if before.unavailable or after.unavailable:
        return {"major_faults": None, "minor_faults": None}
    return {
        "major_faults": max(0, after.major - before.major),
        "minor_faults": max(0, after.minor - before.minor),
    }


# ── V2 prefill overlap: wait-for-UNET policy ─────────────────────
# Default behaviour (recommended): prefill waits for CLIP only and
# begins encoding without blocking on UNET.  The UNET restore runs
# in parallel and its GPU commit is serialised through the mutation
# lane — safe because ``load_models_gpu`` acquires the lane before
# touching GPU memory.
#
# Set to ``1`` / ``true`` / ``yes`` to restore the old barrier that
# waits for UNET *before* CLIP, putting 5.7-6.3s Qwen-encode on the
# critical path (useful for debugging or regression isolation).
_V2_PREFILL_WAIT_FOR_UNET: bool = env_flag("COMFYMODAL_V2_PREFILL_WAIT_FOR_UNET")


# ── Canonical lane vocabulary ─────────────────────────────────────────

_LANE_TO_CANONICAL: dict[str, str] = {
    "unet": "UNET",
    "clip": "CLIP",
    "vae": "VAE",
    "prefill": "prefill",
    "execution_prefill": "prefill",
}
"""Maps internal ``_submit`` lane names to canonical identifiers."""

# ── V2 restore correlation identity ──────────────────────────────────
_LATEST_RESTORED_INSTANCE_ID: str = ""
_LATEST_RESTORE_SESSION_ID: str = ""
"""Module-level latest restored_instance_id.  Set by restore() after
snapshot restoration; read by background worker and graph-entry paths."""

_LATEST_RESTORE_RETURN_MARKER: dict[str, Any] | None = None
"""Set immediately before ``restore()`` returns with wall/monotonic time,
both restore IDs, MODAL_TASK_ID, and PID.  Read by ``run_plan_stream`` method
entry for method-entry-gap computation."""

_DIAGNOSTIC_FLAG: bool = observability_gate(
    "COMFYMODAL_V2_DEEP_MODEL_DIAG", "deep_model_diagnostics",
)
"""Controls deep diagnostics (proc/pagefault/open/mmap/safetensors detail).
``False`` by default — when disabled, only lightweight identity, restore
total, CLIP read/ready, background submitted/ready, graph demand/wait,
and method gaps are reported."""

# ── Slow model-read threshold ─────────────────────────────────────────
# When a CLIP load_torch_file or background-UNET active read exceeds this
# wall-time threshold (ms), a detailed ``[v2.slow_model_read]`` diagnostic
# line is emitted with counter deltas, /proc/meminfo, and cgroup stats.
# Invalid/negative/non-finite values fall back safely to 3000.


def _parse_slow_read_threshold() -> float:
    """Parse COMFYMODAL_V2_SLOW_READ_THRESHOLD_MS with safe fallback to 3000."""
    try:
        _val = os.environ.get("COMFYMODAL_V2_SLOW_READ_THRESHOLD_MS", "3000")
        _parsed = float(_val)
        if _parsed >= 0 and math.isfinite(_parsed):
            return _parsed
    except Exception:
        pass
    return 3000.0


_SLOW_READ_THRESHOLD_MS: float = _parse_slow_read_threshold()

# ── Activation diagnostics state ────────────────────────────────────
# Three-function API: begin_activation_diagnostics(request_id) creates a
# state dict, get_activation_diagnostics() returns it, end_activation_diagnostics(token)
# clears it.  Keys: request_id, clip_encode_calls (list), gpu_load_calls (list),
# model_patcher_calls (list), first_forward (dict), residency (dict).
# No tensors/models/paths.

_ACTIVATION_DIAGNOSTIC_STATE: ContextVar[dict[str, Any] | None] = ContextVar(
    "comfymodal_activation_diagnostic_state", default=None
)
_ACTIVATION_RECEIPT_MAX = 64


def begin_activation_diagnostics(
    request_id: str,
    *,
    cpu_snapshot_active: bool | None = None,
    execution_prefill_scheduled: bool | None = None,
) -> "contextvars.Token":
    """Create and set a fresh activation-diagnostic state dict.
    Returns the ContextVar token for end_activation_diagnostics()."""
    state: dict[str, Any] = {
        "request_id": request_id,
        "observability_mode": observability_mode(),
        "clip_encode_calls": [],
        "gpu_load_calls": [],
        "model_patcher_calls": [],
        "first_forward": {},
        "residency": {},
        "activation_receipts": [],
    }
    if cpu_snapshot_active is not None:
        state["cpu_snapshot_active"] = bool(cpu_snapshot_active)
    if execution_prefill_scheduled is not None:
        state["execution_prefill_scheduled"] = bool(execution_prefill_scheduled)
    return _ACTIVATION_DIAGNOSTIC_STATE.set(state)


def get_activation_diagnostics() -> dict[str, Any] | None:
    """Return the current activation-diagnostic state dict or None."""
    return _ACTIVATION_DIAGNOSTIC_STATE.get()


def record_activation_receipt(
    stage: str,
    *,
    status: str,
    role: str = "",
    started_ns: int | None = None,
    completed_ns: int | None = None,
    metadata: Mapping[str, Any] | None = None,
    explicit_state: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Record one bounded, JSON-safe request-scoped activation receipt."""
    if observability_mode() == "off":
        return None
    state = explicit_state if explicit_state is not None else _ACTIVATION_DIAGNOSTIC_STATE.get()
    if state is None:
        return None
    receipt: dict[str, Any] = {
        "stage": str(stage),
        "status": str(status),
        "role": str(role),
        "request_id": str(state.get("request_id", "")),
    }
    if isinstance(started_ns, int):
        receipt["started_monotonic_ns"] = started_ns
    if isinstance(completed_ns, int):
        receipt["completed_monotonic_ns"] = completed_ns
    if isinstance(started_ns, int) and isinstance(completed_ns, int) and completed_ns >= started_ns:
        receipt["wall_ms"] = round((completed_ns - started_ns) / 1_000_000, 3)
    if metadata:
        for key, value in metadata.items():
            if isinstance(value, (str, int, float, bool)) or value is None:
                receipt[str(key)] = value
    receipts = state.setdefault("activation_receipts", [])
    receipts.append(receipt)
    if len(receipts) > _ACTIVATION_RECEIPT_MAX:
        del receipts[:-_ACTIVATION_RECEIPT_MAX]
    return receipt


def end_activation_diagnostics(token: "contextvars.Token") -> dict[str, Any]:
    """Reset the ContextVar and return the final state dict (empty dict fallback)."""
    try:
        state = _ACTIVATION_DIAGNOSTIC_STATE.get()
        return state if state is not None else {}
    finally:
        _ACTIVATION_DIAGNOSTIC_STATE.reset(token)


def _record_clip_encode(
    caller: str, clip: Any, text: str, callback: Callable[[], Any],
    *,
    _explicit_state: dict[str, Any] | None = None,
) -> Any:
    """Record a CLIP encode call into activation diagnostics.

    Invokes *callback* in try and records metadata in finally.
    Emits ``clip_encode_diagnostic`` trace event.
    When *_explicit_state* is provided (e.g. from a worker thread where
    ContextVars do not propagate), records into that dict instead of the
    ContextVar state.
    """
    start_wall = time.monotonic_ns()
    start_thread = time.thread_time_ns() if hasattr(time, "thread_time_ns") else 0
    start_process = time.process_time_ns() if hasattr(time, "process_time_ns") else 0
    try:
        result = callback()
        return result
    finally:
        end_wall = time.monotonic_ns()
        end_thread = time.thread_time_ns() if hasattr(time, "thread_time_ns") else 0
        end_process = time.process_time_ns() if hasattr(time, "process_time_ns") else 0
        record = {
            "caller": caller,
            "clip_object_id": str(id(clip)),
            "text_hash": stable_hash(str(text))[:16],
            "text_length": len(str(text)),
            "start_monotonic_ns": start_wall,
            "end_monotonic_ns": end_wall,
            "wall_ms": round((end_wall - start_wall) / 1_000_000, 3),
            "thread_cpu_ms": round((end_thread - start_thread) / 1_000_000, 3),
            "process_cpu_ms": round((end_process - start_process) / 1_000_000, 3),
        }
        _detailed_activation = observability_allows("detailed_activation")
        if _explicit_state is not None:
            if _detailed_activation:
                _explicit_state.setdefault("clip_encode_calls", []).append(record)
                _explicit_state["clip_encode_instrumentation_attached"] = True
            try:
                record_activation_receipt(
                    "clip_encode",
                    status="completed",
                    role="CLIP",
                    started_ns=start_wall,
                    completed_ns=end_wall,
                    metadata={"caller": caller, "text_length": len(str(text))},
                    explicit_state=_explicit_state,
                )
            except Exception:
                # Diagnostic accounting must never mask the CLIP encode result
                # or an in-flight exception on this critical-path finally.
                pass
        else:
            state = _ACTIVATION_DIAGNOSTIC_STATE.get()
            if state is not None:
                if _detailed_activation:
                    state["clip_encode_calls"].append(record)
                    state["clip_encode_instrumentation_attached"] = True
                try:
                    record_activation_receipt(
                        "clip_encode",
                        status="completed",
                        role="CLIP",
                        started_ns=start_wall,
                        completed_ns=end_wall,
                        metadata={"caller": caller, "text_length": len(str(text))},
                    )
                except Exception:
                    # Diagnostic accounting must never mask the CLIP encode
                    # result or an in-flight exception on this critical path.
                    pass
        request_trace = _ACTIVE_REQUEST_TRACE.get()
        if request_trace is not None and _detailed_activation:
            request_trace.emit("clip_encode_diagnostic", phase="execution", metadata=dict(record))


def _emit_clean_lane_forced_miss_evidence(
    trace: RuntimeTrace | None,
    *,
    clip: Any,
    text: str,
    request_id: str = "",
    reason: str,
) -> None:
    """Certify the real clean-lane CLIP request as a non-persistent miss.

    CLEAN_LANE's forced-miss path may bypass the normal cache lookup seam
    (including when the singleton is disabled or unavailable).  This helper
    is called immediately before the graph/worker performs the actual encode.
    It records no invented timing or key identity and never touches the cache
    service.
    """
    if not clean_lane.enabled():
        return
    _request_id = str(request_id or (trace.request_id if trace is not None else ""))
    metadata: dict[str, Any] = {
        "hit": False,
        "hit_count": 0,
        "miss_count": 1,
        "entry_count": 1,
        "request_id": _request_id or "absent",
        "clip_object_id": str(id(clip)),
        "text_hash": stable_hash(str(text))[:16],
        "text_length": len(str(text)),
        "real_encode_request": True,
        "lookup_status": "bypassed",
        "reason": str(reason),
        "persistence": "disabled",
    }
    try:
        if trace is not None:
            trace.emit(
                "clip_conditioning_cache_lookup",
                phase="execution",
                metadata=dict(metadata),
            )
        log_conditioning_cache_decision(
            "miss_not_stored",
            request_id=_request_id or "absent",
            hit=False,
            hit_count=0,
            miss_count=1,
            entries=1,
            encode_calls=1,
            persisted=0,
            persistence="disabled",
            real_encode_request=True,
            reason=str(reason),
        )
        if trace is not None:
            trace.emit(
                "clip_conditioning_cache_decision",
                phase="execution",
                metadata={
                    "decision": "miss_not_stored",
                    "request_id": _request_id or "absent",
                    "hit": False,
                    "hit_count": 0,
                    "miss_count": 1,
                    "entry_count": 1,
                    "encode_calls": 1,
                    "persisted_count": 0,
                    "persistence": "disabled",
                    "real_encode_request": True,
                    "reason": str(reason),
                },
            )
    except Exception:
        # Proof telemetry must never change the encode/fallback behavior.
        pass


# ── CLIP execution-prefill phase attribution (Phase B diagnostics) ───
# One per-request reconciliation record partitions the prefill worker
# lifetime into non-overlapping stages:
#
#   prefill_total_ms = queue_ms + readiness_ms + encode_ms + completion_ms
#                      + unattributed_ms
#
# ``unattributed_ms`` is the COMPUTED accounting error (never hidden): the
# difference between the measured total and the sum of the measured child
# stages.  A boundary that was never recorded is reported truthfully as
# ``None`` (never silently zeroed) and flips ``reconciliation_status`` to
# ``"incomplete"``.

# ── Event names for the prefill lifecycle (single source of truth) ────
_EVENT_SUBMISSION = "execution_prefill_scheduled"
_EVENT_WORKER_START = "execution_prefill_submitted"
_EVENT_READINESS_START = "execution_prefill_readiness_start"
_EVENT_READINESS_END = "execution_prefill_readiness_end"
_EVENT_ENCODE_START = "execution_prefill_encode_start"
_EVENT_ENCODE_END = "execution_prefill_encode_end"
_EVENT_COMPLETED = "execution_prefill_completed"
_EVENT_FAILED = "execution_prefill_failed"
_EVENT_GRAPH_WAIT_START = "graph_prefill_wait_start"
_EVENT_GRAPH_WAIT_END = "graph_prefill_wait_end"
_EVENT_RECONCILIATION = "clip_prefill_reconciliation"

# ── Event names for synchronous native page-readiness (Phase B candidate) ──
# stage=clip_prefill: emitted between the CLIP readiness wait and the encode
# loop when COMFYMODAL_V2_PAGE_READINESS_MODE=willneed.  stage=unet_activation:
# emitted immediately before the first request-scoped graph load_models_gpu call.
_EVENT_PAGE_READINESS_START = "execution_prefill_page_readiness_start"
_EVENT_PAGE_READINESS_END = "execution_prefill_page_readiness_end"
_EVENT_UNET_PAGE_READINESS = "unet_activation_page_readiness"


def _capture_torch_thread_counts() -> dict[str, Any]:
    """Best-effort torch intraop/interop thread counts (lazy import).

    Returns ``torch_available`` plus intraop/interop counts (None when
    torch is absent or the accessor is unavailable).  Never raises.
    """
    result: dict[str, Any] = {
        "torch_available": False,
        "torch_intraop_threads": None,
        "torch_interop_threads": None,
    }
    try:
        import torch
        result["torch_available"] = True
        result["torch_intraop_threads"] = int(torch.get_num_threads())
        result["torch_interop_threads"] = int(torch.get_num_interop_threads())
    except Exception:
        pass
    return result


def _capture_native_thread_count() -> int | None:
    """Native thread count: ``/proc/self/status Threads:`` on Linux, else
    ``len(threading.enumerate())``.  Never raises."""
    if platform.system() == "Linux":
        try:
            with open("/proc/self/status") as _f:
                for _line in _f:
                    if _line.startswith("Threads:"):
                        return int(_line.split()[1])
        except Exception:
            pass
    try:
        return len(threading.enumerate())
    except Exception:
        return None


def _capture_phase_counters() -> dict[str, Any]:
    """One phase snapshot for prefill attribution.

    Returns a flat JSON-safe dict.  Wall / thread / process clocks and the
    native tid are always present; ``rusage`` (RUSAGE_THREAD, Linux),
    ``io`` (per-tid ``/proc/self/task/<tid>/io``, Linux), ``torch``, and
    ``native_thread_count`` are attempted natively and reported truthfully
    as ``None`` when unavailable.
    """
    return {
        "mono_ns": time.monotonic_ns(),
        "thread_time_ns": time.thread_time_ns() if hasattr(time, "thread_time_ns") else None,
        "process_time_ns": time.process_time_ns() if hasattr(time, "process_time_ns") else None,
        "native_tid": _capture_tid(),
        "native_thread_count": _capture_native_thread_count(),
        "rusage": _capture_rusage_thread_snapshot(),
        "io": _capture_proc_tid_io_snapshot(),
        "torch": _capture_torch_thread_counts(),
    }


def _phase_counter_deltas(
    before: dict[str, Any] | None,
    after: dict[str, Any] | None,
) -> dict[str, Any]:
    """Compute deltas between two ``_capture_phase_counters()`` snapshots.

    Wall and process CPU deltas are valid whenever both snapshots exist.
    Thread-bounded deltas (thread CPU, RUSAGE_THREAD minor/major faults and
    voluntary/involuntary context switches, per-tid io) are only valid when
    the native thread id matches; otherwise they are reported as ``None``
    (truthful, never fabricated).
    """
    if not before or not after:
        return {}
    result: dict[str, Any] = {}
    _same_tid = (
        isinstance(before.get("native_tid"), int)
        and before.get("native_tid") == after.get("native_tid")
    )

    b_mono = before.get("mono_ns")
    a_mono = after.get("mono_ns")
    if isinstance(b_mono, int) and isinstance(a_mono, int):
        result["wall_ms"] = round(max(0, a_mono - b_mono) / 1_000_000, 3)

    b_tt = before.get("thread_time_ns")
    a_tt = after.get("thread_time_ns")
    if _same_tid and isinstance(b_tt, int) and isinstance(a_tt, int):
        result["thread_cpu_ms"] = round(max(0, a_tt - b_tt) / 1_000_000, 3)
    else:
        result["thread_cpu_ms"] = None

    b_pt = before.get("process_time_ns")
    a_pt = after.get("process_time_ns")
    if isinstance(b_pt, int) and isinstance(a_pt, int):
        result["process_cpu_ms"] = round(max(0, a_pt - b_pt) / 1_000_000, 3)
    else:
        result["process_cpu_ms"] = None

    if _same_tid:
        _ru = _compute_rusage_deltas(before.get("rusage"), after.get("rusage"))
        result["minor_faults"] = _ru.get("minflt") if _ru else None
        result["major_faults"] = _ru.get("majflt") if _ru else None
        result["voluntary_context_switches"] = _ru.get("nvcsw") if _ru else None
        result["involuntary_context_switches"] = _ru.get("nivcsw") if _ru else None
        _io = _compute_io_deltas(before.get("io"), after.get("io"))
        result["io_read_bytes"] = _io.get("read_bytes") if _io else None
        result["io_write_bytes"] = _io.get("write_bytes") if _io else None
    else:
        result["minor_faults"] = None
        result["major_faults"] = None
        result["voluntary_context_switches"] = None
        result["involuntary_context_switches"] = None
        result["io_read_bytes"] = None
        result["io_write_bytes"] = None
    return result


def _phase_counter_deltas_from_events(
    before_meta: Mapping[str, Any] | None,
    after_meta: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Compute phase deltas from two event-metadata dicts carrying
    ``counters`` snapshots (as captured by ``_capture_phase_counters()``)."""
    b = (before_meta or {}).get("counters")
    a = (after_meta or {}).get("counters")
    if not isinstance(b, Mapping) or not isinstance(a, Mapping):
        return {}
    return _phase_counter_deltas(dict(b), dict(a))


def _first_event_mono_ns(trace: Any, name: str) -> int | None:
    """Return the monotonic_ns of the first event named *name*, or None."""
    for event in trace.events:
        if event.name == name:
            return event.monotonic_ns
    return None


def _first_event_meta(trace: Any, name: str) -> dict[str, Any] | None:
    """Return the metadata of the first event named *name*, or None."""
    for event in trace.events:
        if event.name == name:
            return dict(event.metadata)
    return None


def _terminal_prefill_event(trace: Any) -> tuple[str, int, dict[str, Any]] | None:
    """Return ``(name, monotonic_ns, metadata)`` of the last terminal prefill
    event (``execution_prefill_completed`` / ``execution_prefill_failed``), or
    None when neither is present.  Latest-by-monotonic wins."""
    best_name: str | None = None
    best_ns = -1
    best_meta: dict[str, Any] = {}
    for event in trace.events:
        if event.name in (_EVENT_COMPLETED, _EVENT_FAILED) and event.monotonic_ns >= best_ns:
            best_name = event.name
            best_ns = event.monotonic_ns
            best_meta = dict(event.metadata)
    if best_name is None:
        return None
    return best_name, best_ns, best_meta


def _bounded_delta_ms(start_ns: int | None, end_ns: int | None) -> float | None:
    """Non-negative ms between two monotonic boundaries, or None when either
    boundary is absent.  Reversed boundaries yield None (never fabricated)."""
    if start_ns is None or end_ns is None:
        return None
    delta = end_ns - start_ns
    if delta < 0:
        return None
    return round(delta / 1_000_000, 3)


def build_clip_prefill_reconciliation(
    trace: Any,
    *,
    outcome: str = "unknown",
    request_id: str = "",
    tolerance_ms: float = 50.0,
) -> dict[str, Any]:
    """Build the per-request CLIP execution-prefill reconciliation record.

    Reads the prefill lifecycle events already emitted on *trace* and
    partitions the worker lifetime into non-overlapping stages:

      queue_ms        submission → worker start       (cross-thread, wall only)
      readiness_ms    readiness_start → readiness_end (model/future readiness)
      page_readiness_ms  page_readiness_start → end  (synchronous native page
                      readiness candidate; only when mode=willneed)
      encode_ms       encode_start → encode_end       (CLIP encode loop)
      completion_ms   encode_end → terminal           (store + finalization)

    ``unattributed_ms = prefill_total_ms - (queue + readiness +
    page_readiness + encode + completion)`` is the COMPUTED accounting
    error — reported explicitly, never hidden.  Missing boundaries are
    ``None`` (truthful) and flip the status to ``"incomplete"``.  When the
    page-readiness candidate is disabled (mode off), ``page_readiness_ms``
    is ``None`` and ``page_readiness_applied`` is False; the stage is then
    excluded from the completeness check so default production runs still
    reconcile as before.  *outcome* describes how the graph consumed the
    result: ``consumed`` / ``fallback_error`` / ``fallback_unavailable``.
    """
    sub_ns = _first_event_mono_ns(trace, _EVENT_SUBMISSION)
    ws_ns = _first_event_mono_ns(trace, _EVENT_WORKER_START)
    rs_ns = _first_event_mono_ns(trace, _EVENT_READINESS_START)
    re_ns = _first_event_mono_ns(trace, _EVENT_READINESS_END)
    prs_ns = _first_event_mono_ns(trace, _EVENT_PAGE_READINESS_START)
    pre_ns = _first_event_mono_ns(trace, _EVENT_PAGE_READINESS_END)
    es_ns = _first_event_mono_ns(trace, _EVENT_ENCODE_START)
    ee_ns = _first_event_mono_ns(trace, _EVENT_ENCODE_END)
    gws_ns = _first_event_mono_ns(trace, _EVENT_GRAPH_WAIT_START)
    gwe_ns = _first_event_mono_ns(trace, _EVENT_GRAPH_WAIT_END)
    terminal = _terminal_prefill_event(trace)

    prefill_total_ms = _bounded_delta_ms(sub_ns, terminal[1] if terminal else None)
    queue_ms = _bounded_delta_ms(sub_ns, ws_ns)
    readiness_ms = _bounded_delta_ms(rs_ns, re_ns)
    page_readiness_applied = prs_ns is not None and pre_ns is not None
    page_readiness_ms = _bounded_delta_ms(prs_ns, pre_ns)
    encode_ms = _bounded_delta_ms(es_ns, ee_ns)
    completion_ms = _bounded_delta_ms(ee_ns, terminal[1] if terminal else None)
    request_wait_ms = _bounded_delta_ms(gws_ns, gwe_ns)

    if page_readiness_applied:
        child_fields = (
            queue_ms, readiness_ms, page_readiness_ms, encode_ms, completion_ms,
        )
    else:
        child_fields = (queue_ms, readiness_ms, encode_ms, completion_ms)
    measured_children_ms: float | None = None
    if all(isinstance(v, (int, float)) for v in child_fields):
        measured_children_ms = round(sum(float(v) for v in child_fields), 3)

    unattributed_ms: float | None = None
    if isinstance(prefill_total_ms, (int, float)) and isinstance(measured_children_ms, (int, float)):
        unattributed_ms = round(prefill_total_ms - measured_children_ms, 3)

    # ── Reconciliation status ─────────────────────────────────────────
    _completeness_fields = [prefill_total_ms, queue_ms, readiness_ms, encode_ms, completion_ms]
    if page_readiness_applied:
        _completeness_fields.append(page_readiness_ms)
    status = "incomplete"
    if all(v is not None for v in _completeness_fields) and isinstance(unattributed_ms, (int, float)):
        if unattributed_ms < -tolerance_ms:
            status = "overlap"
        elif unattributed_ms > tolerance_ms:
            status = "unmeasured_gap"
        else:
            status = "complete"

    # ── Per-phase counter detail (worker thread, truthful None) ───────
    rs_meta = _first_event_meta(trace, _EVENT_READINESS_START)
    re_meta = _first_event_meta(trace, _EVENT_READINESS_END)
    pr_meta = _first_event_meta(trace, _EVENT_PAGE_READINESS_END)
    es_meta = _first_event_meta(trace, _EVENT_ENCODE_START)
    ee_meta = _first_event_meta(trace, _EVENT_ENCODE_END)
    ws_meta = _first_event_meta(trace, _EVENT_WORKER_START)

    readiness = _phase_counter_deltas_from_events(rs_meta, re_meta)
    encode = _phase_counter_deltas_from_events(es_meta, ee_meta)

    page_readiness: dict[str, Any] = {}
    if isinstance(pr_meta, Mapping):
        page_readiness = {
            "mode": pr_meta.get("mode"),
            "status": pr_meta.get("status"),
            "wall_ms": pr_meta.get("wall_ms"),
            "storage_count": pr_meta.get("storage_count"),
            "range_count": pr_meta.get("range_count"),
            "total_bytes": pr_meta.get("total_bytes"),
            "total_pages": pr_meta.get("total_pages"),
            "advised_pages": pr_meta.get("advised_pages"),
            "advised_bytes": pr_meta.get("advised_bytes"),
            "advised_percent": pr_meta.get("advised_percent"),
            "major_faults": pr_meta.get("major_faults"),
            "minor_faults": pr_meta.get("minor_faults"),
            "error_reason": pr_meta.get("error_reason", ""),
        }

    worker_counters: dict[str, Any] = {}
    if isinstance(ws_meta, Mapping):
        _wc = ws_meta.get("counters")
        if isinstance(_wc, Mapping):
            worker_counters = dict(_wc)

    return {
        "request_id": request_id,
        "outcome": outcome,
        "prefill_total_ms": prefill_total_ms,
        "queue_ms": queue_ms,
        "readiness_ms": readiness_ms,
        "page_readiness_ms": page_readiness_ms,
        "page_readiness_applied": page_readiness_applied,
        "encode_ms": encode_ms,
        "completion_ms": completion_ms,
        "request_wait_ms": request_wait_ms,
        "measured_children_ms": measured_children_ms,
        "unattributed_ms": unattributed_ms,
        "reconciliation_status": status,
        "encoded_count": terminal[2].get("encoded_count") if terminal else None,
        "terminal_event": terminal[0] if terminal else None,
        "worker_native_tid": worker_counters.get("native_tid"),
        "worker_native_thread_count": worker_counters.get("native_thread_count"),
        "torch_available": bool((worker_counters.get("torch") or {}).get("torch_available")),
        "torch_intraop_threads": (worker_counters.get("torch") or {}).get("torch_intraop_threads"),
        "torch_interop_threads": (worker_counters.get("torch") or {}).get("torch_interop_threads"),
        "readiness": readiness,
        "encode": encode,
        "page_readiness": page_readiness,
    }


def emit_clip_prefill_reconciliation(
    trace: RuntimeTrace | None,
    *,
    outcome: str,
    request_id: str = "",
) -> dict[str, Any] | None:
    """Emit exactly one ``clip_prefill_reconciliation`` record on *trace*.

    Returns the emitted record dict, or None when *trace* is None.
    """
    if trace is None:
        return None
    record = build_clip_prefill_reconciliation(
        trace, outcome=outcome, request_id=request_id or str(trace.request_id),
    )
    trace.emit(_EVENT_RECONCILIATION, phase="execution", metadata=record)
    return record


# ── Synchronous native page-readiness (Phase B candidate) ──────────────
# Gated by COMFYMODAL_V2_PAGE_READINESS_MODE=willneed (off by default).
# Both helpers are synchronous (never hidden in a future), never schedule
# additional work, never re-encode, and never touch CUDA or mutate models.
# The UNET activation is guarded per-request so a request can never invoke
# the readiness helper twice for the same UNET activation; the guard is
# cleared in existing request cleanup (modal_app request finally block).

# Bounded per-request guard.  An insertion-ordered dict (not a set) so the
# OLDEST claims are evicted first when the bound is reached — the guard can
# never grow without bound even for request ids that bypass the existing
# modal_app request finally-block cleanup.  Membership checks, claim-once
# semantics and normal request cleanup behave exactly as before (clear
# remains the primary cleanup path; the bound is only a safety net).
_UNET_PAGE_READINESS_DONE: dict[str, bool] = {}
_UNET_PAGE_READINESS_LOCK: RLock = RLock()
_UNET_PAGE_READINESS_DONE_MAX = 1024


def _unet_page_readiness_begin(request_id: str) -> bool:
    """Atomically claim the first graph UNET activation for *request_id*.

    Returns True only for the first claim per request; every subsequent
    claim for the same request returns False (a request can never invoke
    the readiness helper twice for the same UNET activation).  Empty
    request ids are never claimed.  The guard map is bounded: when the
    bound is reached the oldest claim is evicted first, so request ids
    that bypass normal request cleanup cannot leak forever."""
    if not request_id:
        return False
    with _UNET_PAGE_READINESS_LOCK:
        if request_id in _UNET_PAGE_READINESS_DONE:
            return False
        _UNET_PAGE_READINESS_DONE[request_id] = True
        if len(_UNET_PAGE_READINESS_DONE) > _UNET_PAGE_READINESS_DONE_MAX:
            _excess = len(_UNET_PAGE_READINESS_DONE) - _UNET_PAGE_READINESS_DONE_MAX
            for _stale in list(_UNET_PAGE_READINESS_DONE.keys())[:_excess]:
                del _UNET_PAGE_READINESS_DONE[_stale]
        return True


def _unet_page_readiness_clear(request_id: str) -> None:
    """Release the per-request UNET page-readiness guard (request cleanup)."""
    if not request_id:
        return
    with _UNET_PAGE_READINESS_LOCK:
        _UNET_PAGE_READINESS_DONE.pop(request_id, None)


def _unet_page_readiness_is_done(request_id: str) -> bool:
    """True when the readiness guard is currently claimed for *request_id*."""
    if not request_id:
        return False
    with _UNET_PAGE_READINESS_LOCK:
        return _UNET_PAGE_READINESS_DONE.get(request_id, False)


# Bounded per-request pre-touch guard.  Mirrors the page-readiness guard but
# is only armed when COMFYMODAL_V2_UNET_PRETOUCH is enabled.  The bound (not
# modal_app cleanup) is the safety net so a diagnostic-only pre-touch can never
# leak without bound even when a request bypasses the existing cleanup.
_UNET_PRETOUCH_DONE: dict[str, bool] = {}
_UNET_PRETOUCH_LOCK: RLock = RLock()
_UNET_PRETOUCH_DONE_MAX = 1024


def _unet_pretouch_begin(request_id: str) -> bool:
    """Atomically claim the first graph UNET pre-touch for *request_id*.

    Returns True only for the first claim per request; every subsequent claim
    for the same request returns False.  Empty request ids are never claimed.
    Bounded: oldest claims are evicted first when the bound is reached."""
    if not request_id:
        return False
    with _UNET_PRETOUCH_LOCK:
        if request_id in _UNET_PRETOUCH_DONE:
            return False
        _UNET_PRETOUCH_DONE[request_id] = True
        if len(_UNET_PRETOUCH_DONE) > _UNET_PRETOUCH_DONE_MAX:
            _excess = len(_UNET_PRETOUCH_DONE) - _UNET_PRETOUCH_DONE_MAX
            for _stale in list(_UNET_PRETOUCH_DONE.keys())[:_excess]:
                del _UNET_PRETOUCH_DONE[_stale]
        return True


def _first_registered_unet_model(models: list[Any]) -> Any | None:
    """Return the first model in *models* that is a registered retained UNET.

    Uses ``resolve_diffusion_model`` + the weak registry lookup so the exact
    retained UNET is targeted (CacheDiT wrappers wrapping the SAME diffusion
    model are still accepted).  Never raises.
    """
    try:
        from .unet_forward_probe import _lookup_entry, resolve_diffusion_model
        for model in models:
            _, dm = resolve_diffusion_model(model)
            if dm is not None and _lookup_entry(dm) is not None:
                return model
    except Exception:
        pass
    return None


# Attached CPU-storage attributes.  The early-activation worker builds the
# unique CPU registry on the retained CPU snapshot BEFORE any transfer and
# attaches it to the UNET object so it survives once the model is CUDA-resident.
_CPU_STORAGE_REGISTRY_ATTR = "_comfy_modal_cpu_storage_registry"
_CPU_PRETOUCH_ATTR = "_comfy_modal_cpu_pretouch_record"


def _model_is_cpu_resident(model: Any) -> bool:
    """True when *model*'s first parameter is on CPU (pre-transfer)."""
    try:
        for _p in model.parameters():
            _dev = getattr(_p, "device", None)
            _dt = getattr(_dev, "type", None)
            _dev_str = str(_dt() if callable(_dt) else (_dev or "")).lower()
            if _dev_str == "cuda":
                return False
            return True
    except Exception:
        pass
    return False


def _build_unet_cpu_registry(unet: Any) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    """Build/attach the CPU UNET storage registry and optional pre-touch.

    Called on the retained CPU snapshot BEFORE any transfer (early-activation
    worker).  When variance diagnostics are on, builds the unique CPU registry
    and attaches it to *unet* so it survives the transfer; when the pre-touch
    gate is also on, runs the real-read/checksum traversal and attaches it.
    Returns ``(registry_record, pretouch_record)``; both ``None`` when all
    relevant gates are off (no behavior change).  Never raises — an unsupported
    entry is reported, never fatal.
    """
    if not variance_diagnostics_enabled() and not unet_pretouch_enabled():
        return None, None
    _registry: dict[str, Any] | None = None
    _pretouch: dict[str, Any] | None = None
    try:
        if variance_diagnostics_enabled():
            _registry = registry_accounting(unet)
            try:
                setattr(unet, _CPU_STORAGE_REGISTRY_ATTR, _registry)
            except Exception:
                pass
        if unet_pretouch_enabled():
            _pretouch = pretouch_unet_storage(unet)
            try:
                setattr(unet, _CPU_PRETOUCH_ATTR, _pretouch)
            except Exception:
                pass
    except Exception:
        pass
    return _registry, _pretouch


def _resolve_unet_cpu_registry_from_model(unet: Any) -> tuple[dict[str, Any] | None, str]:
    """Resolve the CPU UNET registry on a single resolved UNET object.

    Prefers a worker-attached registry (built on the retained CPU snapshot
    pre-transfer).  Falls back to building fresh only if *unet* is still
    CPU-resident.  If *unet* is already CUDA and no attached registry exists,
    returns ``(None, "post_transfer_unavailable")`` — it never rebuilds on the
    CUDA model (which would report every parameter as unsupported device:cuda).
    """
    if unet is None:
        return None, "no_registered_unet"
    try:
        _attached = getattr(unet, _CPU_STORAGE_REGISTRY_ATTR, None)
        if isinstance(_attached, Mapping):
            return dict(_attached), "worker_attached"
    except Exception:
        pass
    if _model_is_cpu_resident(unet):
        try:
            return registry_accounting(unet), "fresh_cpu"
        except Exception:
            return None, "registry_build_failed"
    return None, "post_transfer_unavailable"


def _resolve_unet_cpu_registry(models: list[Any]) -> tuple[dict[str, Any] | None, str]:
    """Resolve the CPU UNET registry for the graph activation aggregate.

    Prefers a registry attached by the early-activation worker (built on the
    retained CPU snapshot pre-transfer).  Falls back to building fresh only if
    the resolved registered UNET is still CPU-resident (late mode).  If the
    model is already CUDA and no attached registry exists, returns
    ``(None, "post_transfer_unavailable")`` — it never rebuilds on the CUDA
    model (which would report every parameter as unsupported device:cuda).
    """
    try:
        _unet = _first_registered_unet_model(models)
    except Exception:
        _unet = None
    return _resolve_unet_cpu_registry_from_model(_unet)


def _resolve_unet_cpu_pretouch_from_model(unet: Any) -> dict[str, Any] | None:
    """Return a worker-attached CPU pretouch record on a single resolved UNET."""
    if unet is None:
        return None
    try:
        _p = getattr(unet, _CPU_PRETOUCH_ATTR, None)
        if isinstance(_p, Mapping):
            return dict(_p)
    except Exception:
        pass
    return None


def _resolve_unet_cpu_pretouch(models: list[Any]) -> dict[str, Any] | None:
    """Return a worker-attached CPU pretouch record, if present."""
    try:
        _unet = _first_registered_unet_model(models)
    except Exception:
        _unet = None
    return _resolve_unet_cpu_pretouch_from_model(_unet)


def _run_clip_page_readiness(
    clip: Any,
    *,
    trace: RuntimeTrace | None,
    request_id: str,
) -> dict[str, Any] | None:
    """Synchronous native page-readiness for the exact retained CLIP object.

    Called in ``_execution_prefill`` after the CLIP future/readiness wait and
    immediately before the encode loop.  Gated by
    ``COMFYMODAL_V2_PAGE_READINESS_MODE=willneed``; returns None when
    off (no-op, no events emitted).  Emits structured start/end events with
    ``stage=clip_prefill`` and the full readiness evidence (mode, status,
    wall_ms, storage/range/page counts, native fault counters, error
    reason).  Never schedules another future or duplicates the encode.
    ``status=ok`` means the madvise(MADV_WILLNEED) advisory was accepted —
    NOT that the physical pages are resident.
    """
    if page_readiness_mode() != "willneed":
        return None
    if clip is None:
        if trace is not None:
            trace.emit(
                _EVENT_PAGE_READINESS_START, phase="execution",
                metadata={"mode": "willneed", "stage": "clip_prefill",
                          "status": "skip", "reason": "no_clip"},
            )
        return None
    if trace is not None:
        trace.emit(
            _EVENT_PAGE_READINESS_START, phase="execution",
            metadata={"mode": "willneed", "stage": "clip_prefill",
                      "request_id": request_id,
                      "counters": _capture_phase_counters()},
        )
    try:
        result = advise_storage_pages_willneed(clip)
    except Exception as exc:
        result = {
            "status": "error", "mode": "willneed",
            "error_reason": f"{type(exc).__name__}: {str(exc)[:200]}",
        }
    if trace is not None:
        meta: dict[str, Any] = dict(result)
        meta["stage"] = "clip_prefill"
        meta["request_id"] = request_id
        meta["mode"] = "willneed"
        meta["counters"] = _capture_phase_counters()
        trace.emit(_EVENT_PAGE_READINESS_END, phase="execution", metadata=meta)
    return result


def _run_unet_page_readiness(
    unet: Any,
    *,
    trace: RuntimeTrace | None,
    request_id: str,
) -> dict[str, Any] | None:
    """Synchronous native page-readiness for the retained UNET activation.

    Called immediately before the existing original ``load_models_gpu`` call
    for the FIRST request-scoped graph UNET activation only (registered
    retained UNET, request trace, no active model lane).  Never run for
    restore-time background lanes or non-UNET/CLIP calls.  Emits
    ``stage=unet_activation`` readiness evidence.  ``status=ok`` means the
    madvise(MADV_WILLNEED) advisory was accepted — NOT that the physical
    pages are resident.
    """
    if page_readiness_mode() != "willneed":
        return None
    if unet is None:
        return None
    try:
        result = advise_storage_pages_willneed(unet)
    except Exception as exc:
        result = {
            "status": "error", "mode": "willneed",
            "error_reason": f"{type(exc).__name__}: {str(exc)[:200]}",
        }
    if trace is not None:
        meta = dict(result)
        meta["stage"] = "unet_activation"
        meta["request_id"] = request_id
        meta["mode"] = "willneed"
        trace.emit(_EVENT_UNET_PAGE_READINESS, phase="execution", metadata=meta)
    return result


