# ── Sampler stall watchdog (one-shot, non-destructive) ─────────────────────
# Reads request-time boundaries only (first UNET forward, first completed
# sampler step).  Never blocks, cancels, or mutates sampler execution, and
# never disables CacheDiT.  Each request arms one daemon thread that emits a
# ``[v2.sampler_stall_watchdog]`` diagnostic ONLY when a threshold is missed
# (timeout); normal completion and cancel are silent.  ``cancel()`` finishes
# it on normal completion so nothing keeps the event loop alive.
#
# Exact deadlines (both measured from watchdog arm / sampling start):
#   - 5s  waiting for the first UNET forward
#   - 15s waiting for the first completed sampler step (NOT 5s + 15s)

_SAMPLER_STALL_WATCHDOGS: dict[str, "_SamplerStallWatchdog"] = {}
_SAMPLER_STALL_WATCHDOG_LOCK: RLock = RLock()

# Bounded one-shot stage deadlines: 5s for the first UNET forward, 15s for
# the first completed sampler step (from arm / sampling start).
_SAMPLER_STALL_FIRST_FORWARD_TIMEOUT_S: float = 5.0
_SAMPLER_STALL_FIRST_STEP_TIMEOUT_S: float = 15.0


class _SamplerStallWatchdog:
    """One-shot per-request stall watchdog for first UNET forward + first step.

    ``mark_*`` methods are callable from any thread (forward hooks, sampler
    wrapper).  The daemon thread emits ``[v2.sampler_stall_watchdog]`` only
    when a threshold is missed (status=timeout) and exits; ``cancel()`` wakes
    it promptly on normal completion and is silent.  Non-destructive: no
    sampler/model mutation.
    """

    def __init__(
        self,
        *,
        request_id: str,
        restored_instance_id: str = "",
        sampler_node_id: str = "",
        sampler_class: str = "",
        patcher_object_id: str = "",
        diffusion_model_object_id: str = "",
        unet_object_id: str = "",
    ) -> None:
        self.request_id = request_id
        self.restored_instance_id = restored_instance_id
        self.sampler_node_id = sampler_node_id
        self.sampler_class = sampler_class
        self.patcher_object_id = patcher_object_id
        self.diffusion_model_object_id = diffusion_model_object_id
        self.unet_object_id = unet_object_id
        self._unet_forward_event = Event()
        self._sampler_step_event = Event()
        self._forward_seen = False
        self._step_seen = False
        self._done = False
        self._thread: Thread | None = None
        self._start_mono_ns = time.monotonic_ns()
        self._forward_latency_ms: float | None = None
        self._step_latency_ms: float | None = None

    def _ctx(self) -> str:
        return (
            f"request_id={self.request_id} "
            f"restored_instance_id={self.restored_instance_id or 'absent'} "
            f"sampler_node_id={self.sampler_node_id or 'absent'} "
            f"sampler_class={self.sampler_class or 'absent'} "
            f"patcher_object_id={self.patcher_object_id or 'absent'} "
            f"diffusion_model_object_id={self.diffusion_model_object_id or 'absent'} "
            f"unet_object_id={self.unet_object_id or 'absent'}"
        )

    def update_sampler_identity(
        self,
        *,
        sampler_node_id: str = "",
        sampler_class: str = "",
        patcher_object_id: str = "",
        diffusion_model_object_id: str = "",
    ) -> None:
        """Enrich the watchdog with sampler/node/patcher identity once known
        (typically at sampling_start).  Empty values are ignored."""
        if sampler_node_id:
            self.sampler_node_id = str(sampler_node_id)
        if sampler_class:
            self.sampler_class = str(sampler_class)
        if patcher_object_id:
            self.patcher_object_id = str(patcher_object_id)
        if diffusion_model_object_id:
            self.diffusion_model_object_id = str(diffusion_model_object_id)

    def start(self) -> None:
        if self._thread is not None:
            return
        print(
            f"[v2.sampler_stall_watchdog] stage=armed "
            f"{self._ctx()} "
            f"first_forward_timeout_s={_SAMPLER_STALL_FIRST_FORWARD_TIMEOUT_S} "
            f"first_step_timeout_s={_SAMPLER_STALL_FIRST_STEP_TIMEOUT_S}",
            flush=True,
        )
        self._thread = Thread(
            target=self._run,
            name=f"comfymodal-stall-watchdog-{self.request_id[:16]}",
            daemon=True,
        )
        self._thread.start()

    def mark_first_unet_forward(self) -> None:
        if self._forward_seen:
            return
        self._forward_seen = True
        self._forward_latency_ms = round(
            (time.monotonic_ns() - self._start_mono_ns) / 1_000_000, 3
        )
        self._unet_forward_event.set()

    def mark_first_sampler_step(self) -> None:
        if self._step_seen:
            return
        self._step_seen = True
        self._step_latency_ms = round(
            (time.monotonic_ns() - self._start_mono_ns) / 1_000_000, 3
        )
        self._sampler_step_event.set()

    def cancel(self) -> None:
        """Finish the watchdog on normal completion.  Wakes the daemon thread
        immediately; joins briefly.  Never blocks the caller for long."""
        self._unet_forward_event.set()
        self._sampler_step_event.set()
        self._done = True
        thread = self._thread
        if thread is not None and thread is not threading.current_thread():
            thread.join(timeout=1.0)

    def _run(self) -> None:
        try:
            # First UNET forward: wait up to exactly 5s from arm.
            got_forward = self._unet_forward_event.wait(
                timeout=_SAMPLER_STALL_FIRST_FORWARD_TIMEOUT_S
            )
            if not got_forward:
                # Threshold missed -> emit exactly one diagnostic record.
                print(
                    f"[v2.sampler_stall_watchdog] stage=first_unet_forward "
                    f"status=timeout {self._ctx()} "
                    f"timeout_s={_SAMPLER_STALL_FIRST_FORWARD_TIMEOUT_S}",
                    flush=True,
                )
            # First completed sampler step: the deadline is exactly 15s from
            # watchdog arm / sampling start — NOT cumulative 5s + 15s.  The
            # remaining budget is recomputed from arm time, so a slow forward
            # stage cannot extend the step deadline.
            _elapsed_s = (time.monotonic_ns() - self._start_mono_ns) / 1_000_000_000.0
            _step_timeout = max(
                0.0, _SAMPLER_STALL_FIRST_STEP_TIMEOUT_S - _elapsed_s
            )
            got_step = self._sampler_step_event.wait(timeout=_step_timeout)
            if not got_step:
                print(
                    f"[v2.sampler_stall_watchdog] stage=first_sampler_step "
                    f"status=timeout {self._ctx()} "
                    f"timeout_s={_SAMPLER_STALL_FIRST_STEP_TIMEOUT_S}",
                    flush=True,
                )
            # Normal completion and cancel are SILENT: no status=ok or
            # status=cancelled records — only missed thresholds diagnose.
        finally:
            with _SAMPLER_STALL_WATCHDOG_LOCK:
                _SAMPLER_STALL_WATCHDOGS.pop(self.request_id, None)


def start_sampler_stall_watchdog(
    *,
    request_id: str,
    restored_instance_id: str = "",
    sampler_node_id: str = "",
    sampler_class: str = "",
    patcher_object_id: str = "",
    diffusion_model_object_id: str = "",
    unet_object_id: str = "",
) -> bool:
    """Arm the one-shot stall watchdog for *request_id*.

    Idempotent per request_id: a second call for the same request returns
    False without arming a duplicate.  Returns True when a new watchdog was
    armed.  Never raises; always spawns a daemon thread that self-terminates.
    """
    try:
        with _SAMPLER_STALL_WATCHDOG_LOCK:
            existing = _SAMPLER_STALL_WATCHDOGS.get(request_id)
            if existing is not None:
                return False
            watchdog = _SamplerStallWatchdog(
                request_id=request_id,
                restored_instance_id=restored_instance_id,
                sampler_node_id=sampler_node_id,
                sampler_class=sampler_class,
                patcher_object_id=patcher_object_id,
                diffusion_model_object_id=diffusion_model_object_id,
                unet_object_id=unet_object_id,
            )
            _SAMPLER_STALL_WATCHDOGS[request_id] = watchdog
        watchdog.start()
        return True
    except Exception:
        return False


def update_sampler_stall_watchdog_identity(
    request_id: str,
    *,
    sampler_node_id: str = "",
    sampler_class: str = "",
    patcher_object_id: str = "",
    diffusion_model_object_id: str = "",
) -> None:
    """Enrich an armed watchdog with sampler/node/patcher identity."""
    with _SAMPLER_STALL_WATCHDOG_LOCK:
        watchdog = _SAMPLER_STALL_WATCHDOGS.get(request_id)
    if watchdog is not None:
        watchdog.update_sampler_identity(
            sampler_node_id=sampler_node_id,
            sampler_class=sampler_class,
            patcher_object_id=patcher_object_id,
            diffusion_model_object_id=diffusion_model_object_id,
        )


def mark_first_unet_forward(request_id: str) -> None:
    """Called by the UNET forward probe on the first CUDA forward."""
    with _SAMPLER_STALL_WATCHDOG_LOCK:
        watchdog = _SAMPLER_STALL_WATCHDOGS.get(request_id)
    if watchdog is not None:
        watchdog.mark_first_unet_forward()


def mark_first_sampler_step(request_id: str) -> None:
    """Called by the SAMPLER_SAMPLE wrapper on the first completed step."""
    with _SAMPLER_STALL_WATCHDOG_LOCK:
        watchdog = _SAMPLER_STALL_WATCHDOGS.get(request_id)
    if watchdog is not None:
        watchdog.mark_first_sampler_step()
    # R42: Golden envelope — sampler proven; VAE QD4 may arm now.
    try:
        from . import golden_runtime_bridge as _grb

        _gctx = _grb.current()
        if _gctx is not None:
            _gctx.on_first_sampler_step()
    except Exception:
        pass


def cancel_sampler_stall_watchdog(request_id: str) -> None:
    """Cancel (finish) the watchdog on normal completion.

    Removes the request from the registry and wakes the daemon thread so it
    exits promptly.  Non-blocking to the caller (brief bounded join)."""
    with _SAMPLER_STALL_WATCHDOG_LOCK:
        watchdog = _SAMPLER_STALL_WATCHDOGS.pop(request_id, None)
    if watchdog is not None:
        watchdog.cancel()


# ── Retained UNET object-identity chain ─────────────────────────────────────
# Per-request registry of the exact retained UNET object id at each lifecycle
# stage: snapshot -> bridge -> activation -> cachedit -> sampler.  The LOGICAL
# identity is the resolved diffusion-model object, so ComfyUI's dynamic
# ModelPatcher delegates (re-attach / CacheDiT wrapper re-patches) that wrap
# the SAME diffusion model are still accepted.  A different resolved diffusion
# object (or a missing one on either side) fails closed.

_SNAPSHOT_UNET_CHAIN: dict[str, dict[str, int]] = {}
_SNAPSHOT_UNET_CHAIN_LOCK: RLock = RLock()


def _resolve_logical_unet_identity(unet: Any) -> tuple[int, Any]:
    """Resolve *unet* to ``(patcher_object_id, diffusion_model)``.

    The diffusion model is the stable logical identity across ModelPatcher
    delegates and CacheDiT wrapper/re-attach.  Never raises; falls back to a
    ``(object_id, None)`` pair when the object cannot be resolved.
    """
    obj_id = int(id(unet)) if unet is not None else 0
    dm = None
    if unet is not None:
        try:
            from .unet_forward_probe import resolve_diffusion_model
            _, dm = resolve_diffusion_model(unet)
        except Exception:
            dm = None
    return obj_id, dm


def record_retained_unet_identity(stage: str, unet: Any, request_id: str = "") -> int:
    """Record ``id(unet)`` at *stage* for *request_id*.

    Emits ``[v2.unet_identity_chain]``.  Returns the recorded object id
    (0 when *unet* is None).  Never stores a record under an empty
    request_id — the empty key is never left behind and cleanup always
    removes the actual request key.  Never raises.
    """
    obj_id = int(id(unet)) if unet is not None else 0
    try:
        with _SNAPSHOT_UNET_CHAIN_LOCK:
            if request_id:
                chain = _SNAPSHOT_UNET_CHAIN.setdefault(request_id, {})
                chain[stage] = obj_id
        print(
            f"[v2.unet_identity_chain] stage={stage} "
            f"request_id={request_id or 'absent'} unet_object_id={obj_id}",
            flush=True,
        )
    except Exception:
        pass
    return obj_id


def clear_retained_unet_identity_chain(request_id: str) -> None:
    """Drop the identity chain for *request_id* (end of request).

    An empty request_id is a no-op — it never clears unrelated keys."""
    if not request_id:
        return
    try:
        with _SNAPSHOT_UNET_CHAIN_LOCK:
            _SNAPSHOT_UNET_CHAIN.pop(request_id, "")
    except Exception:
        pass


def verify_retained_unet_identity(
    *,
    stage_a: str,
    unet_a: Any,
    stage_b: str,
    unet_b: Any,
    request_id: str = "",
) -> tuple[bool, str]:
    """Verify the exact LOGICAL retained UNET identity between two stages.

    The logical identity is the resolved diffusion-model object, so
    ModelPatcher delegates and CacheDiT wrapper/re-attach that wrap the SAME
    diffusion model are accepted.  Returns ``(True, "ok")`` when both sides
    resolve to the same non-None diffusion model.  Emits
    ``[v2.unet_identity_chain]`` (patcher + diffusion ids on both sides) and
    raises RuntimeError on any mismatch or missing object — the sampler must
    never receive a different UNET than the one validated, retargeted,
    published, and (optionally) CacheDiT-patched.
    """
    obj_id_a, dm_a = _resolve_logical_unet_identity(unet_a)
    obj_id_b, dm_b = _resolve_logical_unet_identity(unet_b)
    id_a = int(id(dm_a)) if dm_a is not None else 0
    id_b = int(id(dm_b)) if dm_b is not None else 0
    ok = id_a != 0 and id_b != 0 and id_a == id_b
    reason = "ok"
    if not ok:
        if id_a == 0 or id_b == 0:
            reason = "unet_missing"
        else:
            reason = f"identity_mismatch:{id_a}!={id_b}"
    print(
        f"[v2.unet_identity_chain] check=stage_pair stage_a={stage_a} stage_b={stage_b} "
        f"request_id={request_id or 'absent'} "
        f"patcher_a_object_id={obj_id_a} diffusion_a_object_id={id_a} "
        f"patcher_b_object_id={obj_id_b} diffusion_b_object_id={id_b} "
        f"ok={int(ok)} reason={reason}",
        flush=True,
    )
    if not ok:
        raise RuntimeError(
            f"Retained UNET identity mismatch between {stage_a} and {stage_b}: {reason}"
        )
    return (True, "ok")


# ── Production CPU-snapshot request marker ─────────────────────────────────
# Per-request marker set only when a production request binds the CPU
# snapshot WITHOUT the diagnostic UNET bypass.  Used by the sampler wrapper
# to gate fail-closed CPU-residency enforcement to the exact retained
# snapshot/bridge object being sampled.  Normal, CPU-only, dynamic/offload,
# meta/unknown, and bypass paths never set it, so they stay diagnostic-only.

_PRODUCTION_CPU_SNAPSHOT_REQUESTS: set[str] = set()
_PRODUCTION_CPU_SNAPSHOT_REQUESTS_LOCK: RLock = RLock()


def mark_production_cpu_snapshot_request(request_id: str) -> None:
    """Mark *request_id* as bound to the production CPU-snapshot path."""
    if not request_id:
        return
    with _PRODUCTION_CPU_SNAPSHOT_REQUESTS_LOCK:
        _PRODUCTION_CPU_SNAPSHOT_REQUESTS.add(request_id)


def unmark_production_cpu_snapshot_request(request_id: str) -> None:
    """Clear the production CPU-snapshot marker for *request_id*."""
    if not request_id:
        return
    with _PRODUCTION_CPU_SNAPSHOT_REQUESTS_LOCK:
        _PRODUCTION_CPU_SNAPSHOT_REQUESTS.discard(request_id)


def is_production_cpu_snapshot_request(request_id: str) -> bool:
    """True when *request_id* is marked as the production CPU-snapshot path."""
    if not request_id:
        return False
    with _PRODUCTION_CPU_SNAPSHOT_REQUESTS_LOCK:
        return request_id in _PRODUCTION_CPU_SNAPSHOT_REQUESTS


# ── UNET activation boundary diagnostics ───────────────────────────────────
# Authoritative [v2.unet_activation] lines: requested / started / completed /
# failed.  Identifies the retained UNET by object id + model-key identity;
# no tensor contents.


def emit_unet_activation_diagnostic(
    *,
    stage: str,
    request_id: str = "",
    restored_instance_id: str = "",
    unet_object_id: str = "",
    unet_identity: str = "",
    status: str = "",
    reason: str = "",
) -> None:
    """Emit one authoritative ``[v2.unet_activation]`` boundary line."""
    print(
        f"[v2.unet_activation] stage={stage} "
        f"request_id={request_id or 'absent'} "
        f"restored_instance_id={restored_instance_id or 'absent'} "
        f"unet_object_id={unet_object_id or 'absent'} "
        f"unet_identity={unet_identity or 'absent'} "
        f"status={status or 'absent'} "
        f"reason={reason or 'ok'}",
        flush=True,
    )


def _resolve_model_role_for_boundary(model: Any) -> str:
    """Classify a model patcher as UNET / CLIP / VAE / other for boundary
    diagnostics.  Never raises; falls back to the type name."""
    try:
        from .unet_forward_probe import resolve_diffusion_model
        _, dm = resolve_diffusion_model(model)
        if dm is not None:
            return "UNET"
        type_name = type(model).__name__.lower()
        if "clip" in type_name:
            return "CLIP"
        if "vae" in type_name:
            return "VAE"
        return type_name or "other"
    except Exception:
        return "other"

# ── UNET effective-dtype resolver (shared by snapshot and normal paths) ──
# Resolution strategy depends on context:
#
#   1. Normal (GPU) load path — uses the real CUDA hardware via ComfyUI's
#      model_management.unet_dtype() auto-detection.  The "default" string
#      is passed through to UNETLoader.load_unet which leaves model_options
#      empty, letting ComfyUI probe the real GPU.  This works because CUDA
#      is available.
#
#   2. CPU snapshot construction path — there is NO GPU available (Modal's
#      CPU snapshot builder).  CUDA APIs cannot be called.  The effective
#      dtype must be resolved from the *configured* target GPU(s) via the
#      target-GPU policy in gpu_catalog.gpu_supports_bf16().
#
# The resolve_unet_effective_dtype() function accepts an optional
# *target_gpus* parameter.  When provided (snapshot path), it uses
# the pure static lookup.  When absent (normal path), it falls back
# to the real GPU probe path.
#
# DO NOT cache a false CUDA capability result from the CPU snapshot builder.
# DO NOT call torch.cuda.* APIs from code that runs during snapshot
# construction.

# ── CPU-snapshot native-BF16 compute policy ─────────────────────────────
# Contextmanager that temporarily patches comfy.model_management.unet_manual_cast
# during snapshot UNET construction on CPU so native BF16 compute is used.
# Without this patch, unet_manual_cast gets CPU as inference_device and falls
# through to torch.float32, building the model with fp32 compute even though
# weights are bfloat16.
#
# Thread-safety: the dedicated lock is held across the entire patched interval
# (install + yield + restore).  The patched wrapper uses a thread-identity
# ContextVar so unrelated callers on other threads always delegate to the
# original function.

_CPU_SNAPSHOT_UNET_COMPUTE_POLICY_LOCK: RLock = RLock()

_CPU_SNAPSHOT_UNET_POLICY_ACTIVE_THREAD: ContextVar[int] = ContextVar(
    "_cpu_snapshot_unet_policy_active_thread", default=0
)

_CPU_SNAPSHOT_UNET_MANUAL_CAST_OVERRIDE: ContextVar[str] = ContextVar(
    "_cpu_snapshot_unet_manual_cast_override", default=""
)


@contextmanager
def cpu_snapshot_unet_compute_policy(
    *,
    effective_weight_dtype: Any,
    target_gpus: tuple[str, ...],
) -> Iterator[None]:
    import sys as _sys
    import torch as _torch
    import threading
    from gpu_catalog import gpu_supports_bf16

    # Primary GPU semantics: only the first target GPU determines BF16 capability,
    # consistent with resolve_unet_effective_dtype and _resolve_compute_policy.
    _primary_gpu = target_gpus[0] if target_gpus else ""
    _should_patch = (
        effective_weight_dtype is not None
        and effective_weight_dtype == _torch.bfloat16
        and _primary_gpu
        and gpu_supports_bf16(_primary_gpu)
    )

    if not _should_patch:
        yield
        return

    _tid = threading.get_ident()
    _current = _CPU_SNAPSHOT_UNET_POLICY_ACTIVE_THREAD.get()
    if _current != 0 and _current == _tid:
        raise RuntimeError(
            "cpu_snapshot_unet_compute_policy is not reentrant: "
            "a policy context is already active on this thread"
        )

    _mm = None
    _orig_fn = None
    _installed = False
    try:
        with _CPU_SNAPSHOT_UNET_COMPUTE_POLICY_LOCK:
            if _CPU_SNAPSHOT_UNET_POLICY_ACTIVE_THREAD.get() != 0:
                yield
                return

            _mm = _sys.modules.get("comfy.model_management")
            if _mm is None:
                yield
                return

            _orig_fn = getattr(_mm, "unet_manual_cast", None)
            if _orig_fn is None:
                yield
                return

            _CPU_SNAPSHOT_UNET_POLICY_ACTIVE_THREAD.set(_tid)
            _CPU_SNAPSHOT_UNET_MANUAL_CAST_OVERRIDE.set("none")

            def _policy_wrapper(
                weight_dtype: Any,
                inference_device: Any,
                supported_dtypes: list | None = None,
            ) -> Any:
                if _CPU_SNAPSHOT_UNET_POLICY_ACTIVE_THREAD.get() == threading.get_ident():
                    _mode = _CPU_SNAPSHOT_UNET_MANUAL_CAST_OVERRIDE.get()
                    if _mode == "none" and weight_dtype is _torch.bfloat16:
                        return None
                if _orig_fn is not None:
                    if supported_dtypes is not None:
                        return _orig_fn(weight_dtype, inference_device, supported_dtypes)
                    return _orig_fn(weight_dtype, inference_device)
                return None

            setattr(_mm, "unet_manual_cast", _policy_wrapper)
            _installed = True

            # Yield INSIDE the lock — lock covers install + yield + restore
            yield

    finally:
        if _installed and _mm is not None and _orig_fn is not None:
            # Restore under the same lock acquisition; re-read the live
            # module to handle edge cases where model_management was
            # reloaded between yield and finally.
            # ContextVars are reset in a nested try/finally so they are
            # cleared even if the module attribute restore raises.
            with _CPU_SNAPSHOT_UNET_COMPUTE_POLICY_LOCK:
                _CPU_SNAPSHOT_UNET_POLICY_ACTIVE_THREAD.set(0)
                _CPU_SNAPSHOT_UNET_MANUAL_CAST_OVERRIDE.set("")
                _installed = False
                # Restore the original function — if this raises, the
                # ContextVars above have already been reset so subsequent
                # operations are not permanently broken.
                restore_target = _sys.modules.get("comfy.model_management")
                if restore_target is not None:
                    setattr(restore_target, "unet_manual_cast", _orig_fn)


def resolve_unet_effective_dtype(
    weight_dtype_str: str = "default",
    *,
    target_gpus: tuple[str, ...] | None = None,
) -> tuple[Any, str]:
    """Resolve a weight_dtype string to the *effective* torch dtype.

    Returns ``(effective_dtype, resolved_label)`` where *effective_dtype* is
    the ``torch.dtype`` the configured GPU load path would use for this
    string, and *resolved_label* is a short diagnostic label.

    **target_gpus** (tuple of canonical Modal GPU names, optional):
      When provided (CPU snapshot construction), the effective dtype is
      determined from the *configured* target GPU(s) via a pure name-based
      lookup — no CUDA API calls.  The primary (first) GPU in the tuple
      is used.
      When ``None`` (normal runtime path), the function falls through to
      let ComfyUI's normal runtime policy apply (``"default"`` passes
      through as-is, returning ``(None, "default")``).

    Decision order:
      1. CLI flags override everything (``--fp32-unet``, ``--bf16-unet``, …).
      2. Explicit fp8/e4m3fn/e5m2 strings -> corresponding torch dtype.
      3. ``"default"`` with *target_gpus* -> target-GPU policy lookup.
      4. ``"default"`` without *target_gpus* -> ``(None, "default")``
         (let ComfyUI auto-detect at load time).

    Both the snapshot construction path (``_cpu_load_unet``) and the normal
    loader path (``V2LoaderBridge._load_unet``) use this function so they
    cannot drift.

    Returns
    -------
    effective_dtype
        The resolved ``torch.dtype``, or ``None`` for unrecognised strings
        / pass-through values.
    resolved_label
        Short string for diagnostic logging.
    """
    # Import torch lazily — may not be available at parse time in all contexts.
    import torch as _torch
    # comfy.cli_args is always present in the deployed container; the
    # fail-soft path below exists so unit tests (no comfy on sys.path) can
    # exercise the bridge.  Production behavior is unchanged: on ImportError
    # every CLI flag below is treated as unset (False), exactly as argparse
    # leaves it when none of --fp32-unet/--fp64-unet/--bf16-unet/--fp16-unet
    # are passed, so resolution falls through to the normal weight-dtype /
    # target-GPU branches.
    try:
        import comfy.cli_args as _ca
    except ImportError:  # pragma: no cover - unit-test-only environment
        import types as _types

        _ca = _types.SimpleNamespace(args=_types.SimpleNamespace())

    # 1. CLI flags (work in both normal and CPU-snapshot contexts)
    if getattr(_ca.args, "fp32_unet", False):
        return (_torch.float32, "float32")
    if getattr(_ca.args, "fp64_unet", False):
        return (_torch.float64, "float64")
    if getattr(_ca.args, "bf16_unet", False):
        return (_torch.bfloat16, "bfloat16")
    if getattr(_ca.args, "fp16_unet", False):
        return (_torch.float16, "float16")

    # 2. Explicit fp8 strings (float8 types may not exist in older PyTorch)
    _float8_e4m3fn = getattr(_torch, "float8_e4m3fn", None)
    _float8_e5m2 = getattr(_torch, "float8_e5m2", None)
    if weight_dtype_str in ("fp8_e4m3fn", "fp8_e4m3fn_fast"):
        if _float8_e4m3fn is not None:
            return (_float8_e4m3fn, weight_dtype_str)
        return (None, weight_dtype_str)
    if weight_dtype_str == "fp8_e5m2":
        if _float8_e5m2 is not None:
            return (_float8_e5m2, weight_dtype_str)
        return (None, weight_dtype_str)

    # 3. Recognised non-"default" string without a type override
    if weight_dtype_str != "default":
        return (None, weight_dtype_str)

    # 4. "default" with target_gpus — snapshot construction path.
    #    Use the configured target GPU(s), not the local CUDA state.
    if target_gpus is not None:
        from gpu_catalog import gpu_supports_bf16
        # Use the primary (first) target GPU for capability check
        _primary = target_gpus[0] if target_gpus else ""
        if _primary and gpu_supports_bf16(_primary):
            return (_torch.bfloat16, "bfloat16")
        return (_torch.float32, "float32")

    # 5. "default" without target_gpus — normal runtime path.
    #    Let ComfyUI auto-detect at load time by returning None.
    return (None, "default")

# Submission correlation counter
_SUBMISSION_COUNTER: int = 0
_SUBMISSION_COUNTER_LOCK = RLock()

def _next_submission_id() -> str:
    global _SUBMISSION_COUNTER
    with _SUBMISSION_COUNTER_LOCK:
        _SUBMISSION_COUNTER += 1
        return f"s{_SUBMISSION_COUNTER:04d}"


def _get_live_module(mod_name: str) -> Any | None:
    """Return an already-loaded module from sys.modules (never triggers import)."""
    import sys
    return sys.modules.get(mod_name)


# ── Wrapper factories ───────────────────────────────────────────────


def _native_detection_input(base_sd, base_meta, prefix_fn, strip_fn, quant_fn=None):
    """EXACT input parity with comfy.sd.load_diffusion_model_state_dict.

    Native sequence: convert_old_quants -> unet_prefix_from_state_dict
    -> state_dict_prefix_replace(filter_keys=True) applied ONLY when the
    stripped result is non-empty (the empty-strip guard is the R42A D2 fix:
    ``unet_prefix_from_state_dict`` falls back to "model." for bare-key
    diffusion files, and an unconditional filter_keys strip yields an EMPTY
    dict -> model_config_from_unet returns None -> native construct fallback).
    Returns ``(detect_sd, detect_meta, prefix)``.
    """
    detect_sd = dict(base_sd)
    detect_meta = base_meta
    if callable(quant_fn):
        try:
            detect_sd, detect_meta = quant_fn(detect_sd, "", metadata=detect_meta)
        except Exception:
            detect_sd, detect_meta = dict(base_sd), base_meta
    prefix = prefix_fn(detect_sd)
    temp = strip_fn(dict(detect_sd), {prefix: ""}, filter_keys=True)
    if len(temp) > 0:
        detect_sd = temp
        if callable(quant_fn):
            try:
                detect_sd, detect_meta = quant_fn(detect_sd, "", metadata=detect_meta)
            except Exception:
                pass
    return detect_sd, detect_meta, prefix


def _storage_identity_counts(named, views):
    """Measured bind identity: compare bound parameter/buffer data_ptrs
    against the Golden source tensors.  Returns ``(counts, ptr_map)`` where
    counts has tensor_count / same_storage_count / copied_storage_count /
    unexpected_device_count / unexpected_dtype_count."""
    same_storage = copied_storage = unexpected_device = unexpected_dtype = 0
    ptr_map: dict = {}
    tensor_count = 0
    for name, tensor in named.items():
        tensor_count += 1
        src = views.get(name)
        try:
            ptr_map[name] = (int(tensor.data_ptr()), str(tensor.device), str(tensor.dtype))
        except Exception:
            continue
        if src is None:
            continue
        try:
            if int(tensor.data_ptr()) == int(src.data_ptr()):
                same_storage += 1
            else:
                copied_storage += 1
        except Exception:
            copied_storage += 1
        if not str(tensor.device).startswith("cuda"):
            unexpected_device += 1
        if tensor.dtype != src.dtype:
            unexpected_dtype += 1
    counts = {
        "tensor_count": tensor_count,
        "same_storage_count": same_storage,
        "copied_storage_count": copied_storage,
        "unexpected_device_count": unexpected_device,
        "unexpected_dtype_count": unexpected_dtype,
    }
    return counts, ptr_map


def _make_golden_load_diffusion_model_wrapper(original: Callable[..., Any]) -> Callable[..., Any]:
    """Build the R42 demand-side UNET skeleton/zero-copy binder."""
    @functools.wraps(original)
    def wrapper(unet_path, model_options={}, disable_dynamic=False):
        try:
            from . import golden_runtime_bridge as _grb
            ctx = _grb.enabled_current()
            if ctx is None or not str(unet_path).lower().endswith(".safetensors"):
                return original(unet_path, model_options=model_options, disable_dynamic=disable_dynamic)
            t0 = time.perf_counter_ns()
            ctx.ledger_sink.emit("unet_construct_start", path_tail=str(unet_path)[-60:])
            ctx.note_role_source("unet", str(unet_path))
            from .golden.contracts import ModelRole
            registry = ctx.pipeline.registry
            if registry.get(ModelRole.UNET) is None:
                # ── R42 fix: graph loaders commonly run BEFORE the CLIP
                # forward boundary fires (which is what registers the Golden
                # UNET owner via the prepare worker).  Instead of bailing
                # immediately, poll for a bounded window until either the
                # owner registers or the forward boundary starts; only then
                # fall back.  Never blocks indefinitely.
                _uw_start = time.monotonic()
                _uw_deadline = _uw_start + 8.0
                while time.monotonic() < _uw_deadline:
                    if (
                        registry.get(ModelRole.UNET) is not None
                        or getattr(ctx, "_clip_forward_started", False)
                    ):
                        break
                    time.sleep(0.02)
                if registry.get(ModelRole.UNET) is None and not getattr(ctx, "_clip_forward_started", False):
                    ctx.add_degradation("golden_qd_fallback:unet")
                    ctx.ledger_sink.emit(
                        "golden_unet_demand_early",
                        reason="no_owner_and_forward_not_started_after_bounded_wait",
                        waited_ms=round((time.monotonic() - _uw_start) * 1000.0, 1),
                    )
                    return original(unet_path, model_options=model_options, disable_dynamic=disable_dynamic)
            decision, _owner = registry.join_or_adopt(
                ModelRole.UNET, min(float(getattr(ctx, "join_timeout_s", 120.0)), 60.0))
            if str(getattr(decision, "value", decision)) not in ("joined", "already_ready"):
                ctx.add_degradation("golden_qd_fallback:unet")
                return original(unet_path, model_options=model_options, disable_dynamic=disable_dynamic)
            sd = ctx.unet_payload(timeout_s=30.0)
            if not sd:
                ctx.add_degradation("golden_qd_fallback:unet")
                return original(unet_path, model_options=model_options, disable_dynamic=disable_dynamic)
            started = time.monotonic_ns()
            import torch
            from .golden.qd_engine import parse_safetensors_header
            layout = parse_safetensors_header(str(unet_path))
            entries = list(layout.tensor_map)
            if any(".scaled_fp8" in e.name for e in entries):
                raise RuntimeError("scaled_fp8")
            dtypes = {str(e.dtype) for e in entries}
            if len(dtypes) != 1:
                raise RuntimeError("non_uniform_dtype")
            dtype_map = _c6_safetensors_dtype_map()
            view_dtype = dtype_map.get(next(iter(dtypes)))
            if view_dtype is None:
                raise RuntimeError("unknown_dtype")
            meta_sd = {e.name: torch.empty(tuple(e.shape), dtype=view_dtype, device="meta") for e in entries}
            import comfy.model_detection as _md
            import comfy.utils as _cu
            import comfy.model_management as _mm
            import comfy.model_patcher as _mp
            prefix_fn = getattr(_md, "unet_prefix_from_state_dict", None)
            strip_fn = getattr(_cu, "state_dict_prefix_replace", None)
            config_fn = getattr(_md, "model_config_from_unet", None)
            quant_fn = getattr(_cu, "convert_old_quants", None)
            if not all(callable(x) for x in (prefix_fn, strip_fn, config_fn)):
                raise RuntimeError("missing_comfy_helper")
            header = _c6_parse_safetensors_header(str(unet_path))
            metadata = header.get("__metadata__") if header else None

            t_cfg = time.monotonic_ns()
            detect_sd, detect_meta, prefix = _native_detection_input(
                meta_sd, metadata, prefix_fn, strip_fn, quant_fn
            )
            model_config = config_fn(detect_sd, "", metadata=detect_meta)
            ctx.ledger_sink.emit(
                "unet_model_config_detect",
                source="header_meta",
                raw_key_count=len(meta_sd),
                detect_key_count=len(detect_sd),
                prefix=str(prefix),
                detected=bool(model_config),
                arch=type(model_config).__name__ if model_config is not None else "",
            )
            if model_config is None:
                # ── R42 fix: header-only meta_sd can defeat detection; retry
                # with the already-joined Golden payload (zero extra I/O).
                _retry_sd = ctx.unet_payload(timeout_s=30.0)
                if not _retry_sd:
                    raise RuntimeError("model_config_none")
                _detect2, _meta2, _prefix2 = _native_detection_input(_retry_sd, metadata)
                model_config = config_fn(_detect2, "", metadata=_meta2)
                if model_config is None:
                    raise RuntimeError("model_config_none")
                ctx.ledger_sink.emit(
                    "unet_model_config_retry",
                    source="golden_payload",
                    key_count=len(_detect2),
                    prefix=str(_prefix2),
                )
            ctx.ledger_sink.emit(
                "unet_construct_stage",
                stage="model_config_resolved",
                wall_ms=round((time.monotonic_ns() - t_cfg) / 1e6, 3),
                arch=type(model_config).__name__,
            )
            selected = model_options.get("dtype")
            if selected is None:
                selected = _mm.unet_dtype(supported_dtypes=list(model_config.supported_inference_dtypes))
            if selected != view_dtype:
                raise RuntimeError("inference_dtype_mismatch")
            manual_cast = _mm.unet_manual_cast(selected, model_options.get("load_device", _mm.get_torch_device()), model_config.supported_inference_dtypes)
            model_config.set_inference_dtype(selected, manual_cast)
            model = model_config.get_model(detect_sd, "")
            patcher = _mp.CoreModelPatcher(
                model,
                load_device=model_options.get("load_device", _mm.get_torch_device()),
                offload_device=model_options.get("offload_device", _mm.unet_offload_device()),
            )
            ctx.ledger_sink.emit(
                "unet_construct_stage",
                stage="skeleton_patcher_created",
                wall_ms=round((time.monotonic_ns() - t_cfg) / 1e6, 3),
            )
            views = {k[len(prefix):] if prefix and k.startswith(prefix) else k: v for k, v in sd.items()}
            t_bind = time.monotonic_ns()
            # R42A: pass a COPY — load_model_weights POPS every key out of the
            # dict it receives (unet_prefix="" matches everything), which
            # would otherwise empty `views` before the storage-identity
            # measurement below reads it.
            result = model.load_model_weights(dict(views), "", assign=True)
            missing = getattr(result, "missing_keys", None) if result is not None else None
            if missing:
                raise RuntimeError("missing_keys")
            # R42A: validate + measure at DIFFUSION level so names match the
            # bare Golden payload keys (``model.named_parameters()`` prefixes
            # every name with ``diffusion_model.`` and would make these checks
            # vacuously pass).
            _inner_model = getattr(model, "diffusion_model", model)
            named = dict(_inner_model.named_parameters())
            named.update(dict(_inner_model.named_buffers()))
            for name, tensor in named.items():
                if name in views and (tuple(tensor.shape) != tuple(views[name].shape) or tensor.dtype != views[name].dtype or not str(tensor.device).startswith("cuda")):
                    raise RuntimeError("bind_validation")
            # ── R42A: MEASURED storage identity (not asserted).  assign=True
            # must make each bound parameter share the Golden CUDA storage;
            # data_ptr equality is the physical proof.
            identity_counts, ptr_map = _storage_identity_counts(named, views)
            same_storage = identity_counts["same_storage_count"]
            copied_storage = identity_counts["copied_storage_count"]
            unexpected_device = identity_counts["unexpected_device_count"]
            unexpected_dtype = identity_counts["unexpected_dtype_count"]
            ctx._unet_bound_ptr_map = ptr_map
            # Store the DIFFUSION module: ptr_map keys are diffusion-level
            # names, and the window-close identity recheck must enumerate the
            # same namespace.
            ctx._unet_bound_model_ref = _inner_model
            ctx.telemetry["unet_storage_identity"] = dict(identity_counts)
            ctx.ledger_sink.emit("unet_storage_identity", **identity_counts)
            ctx.ledger_sink.emit(
                "unet_construct_stage",
                stage="bind_complete",
                wall_ms=round((time.monotonic_ns() - t_bind) / 1e6, 3),
            )
            leftovers = sum(1 for name in named if name not in views)
            if leftovers:
                try:
                    model.to(patcher.load_device)
                except Exception:
                    pass
            ctx.ledger_sink.emit("unet_demand_join", decision=str(getattr(decision, "value", decision)))
            ctx.ledger_sink.emit("unet_adopt_construct", wall_ms=round((time.monotonic_ns() - started) / 1_000_000, 3), assigned_count=len(views), leftover_count=leftovers, assign_mode="assign_true")
            from . import loader_selection
            loader_selection.record_observed("unet", "golden_qd4")
            ctx.clear_role_fallback_degradations("unet")
            ctx.record_io_uniqueness(
                "unet",
                golden_source_producer_count=1,
                golden_commit_count=1,
                demand_join_count=1,
                native_fallback_count=0,
                duplicate_source_count=0,
                duplicate_h2d_count=0,
                adoption_mode="skeleton_assign_bind",
                same_storage_count=same_storage,
                copied_storage_count=copied_storage,
                unexpected_device_count=unexpected_device,
                unexpected_dtype_count=unexpected_dtype,
            )
            ctx.ledger_sink.emit("unet_construct_end", wall_ms=round((time.perf_counter_ns() - t0) / 1e6, 3), outcome="adopted")
            ctx.ledger_sink.emit("unet_bind", assigned_count=len(views), leftover_count=leftovers, mode="assign_true")
            return patcher
        except Exception as exc:
            try:
                ctx.add_degradation("golden_qd_fallback:unet")
                ctx.record_real_fallback("unet", f"construct_fallback:{str(exc)[:80]}")
                from . import loader_selection as _ls_fb

                _ls_fb.record_observed("unet", "native_comfy", fallback_attempted=True, fallback_loader="native_comfy", fallback_reason=f"construct:{str(exc)[:160]}")
                ctx.ledger_sink.emit("golden_unet_construct_fallback", reason=str(exc)[:120])
            except Exception:
                pass
            return original(unet_path, model_options=model_options, disable_dynamic=disable_dynamic)
    setattr(wrapper, _SENTINEL_GOLDEN_DIFFUSION, True)
    return wrapper


def _make_torch_file_wrapper(original: Callable[..., Any]) -> Callable[..., Any]:
    """Wrap ``comfy.utils.load_torch_file`` to emit ``read_start/read_end``.

    Reentrancy-safe: nested calls from within the same thread do not
    duplicate outer events.
    """

    @functools.wraps(original)
    def wrapper(ckpt, safe_load=False, device=None, return_metadata=False):
        try:
            from . import golden_runtime_bridge as _grb
            _ctx = _grb.enabled_current()
            if _ctx is not None and str(ckpt).lower().endswith(".safetensors"):
                import os as _os

                def _role_matches(role: str) -> bool:
                    if str(ckpt) == str(getattr(_ctx, "role_paths", {}).get(role)):
                        return True
                    try:
                        import folder_paths as _fp

                        if role == "vae":
                            folders = ("vae",)
                        elif role == "clip":
                            folders = ("text_encoders", "clip")
                        else:
                            folders = ("diffusion_models", "checkpoints")
                        for folder in folders:
                            if _fp.get_full_path(folder, _os.path.basename(str(ckpt))) == str(ckpt):
                                return True
                    except Exception:
                        pass
                    return False

                if _role_matches("vae"):
                    _matched_role = "vae"
                elif _role_matches("clip"):
                    _matched_role = "clip"
                elif _role_matches("unet"):
                    _matched_role = "unet"
                else:
                    _matched_role = ""
                if _matched_role:
                    _role_event = {"clip": "clip_role_match", "vae": "vae_role_match", "unet": "unet_role_match"}.get(_matched_role, "role_match")
                    _ctx.ledger_sink.emit(_role_event, ckpt_tail=str(ckpt)[-60:])
                if os.environ.get("COMFYMODAL_GOLDEN_PIPELINE", "") == "1":
                    import os as _os_diag

                    print(
                        "[v2.golden_torch_file] ckpt="
                        f"{_os_diag.path.basename(str(ckpt))[:60]} matched_role={_matched_role or 'none'}",
                        flush=True,
                    )
                if _matched_role == "vae":
                    # VAELoader only needs names/shapes/dtypes to construct the
                    # native graph.  The one value-producing QD4 read is
                    # deferred until the first sampler step and joined by the
                    # VAEDecode seam; never block here on the phase gate.
                    try:
                        from .golden.contracts import ModelRole as _GoldenModelRole

                        _vae_owner = _ctx.pipeline.registry.get(_GoldenModelRole.VAE)
                    except Exception:
                        _vae_owner = None
                    t_vae = time.perf_counter_ns()
                    if _ctx._vae_committed.is_set() or (
                        _vae_owner is not None and getattr(_vae_owner, "payload", None) is not None
                    ):
                        _res = _ctx.vae_demand_load(str(ckpt))
                    else:
                        _res = _ctx.vae_descriptor_load(str(ckpt))
                    if _res is not None:
                        _sd, _metadata = _res
                        _mode = "golden_qd4" if _ctx._vae_committed.is_set() else "golden_descriptor"
                        _ctx.ledger_sink.emit("vae_loader_return", mode=_mode, wall_ms=round((time.perf_counter_ns() - t_vae) / 1e6, 3))
                        print(f"[v2.golden_vae] torch_file=served mode={_mode}", flush=True)
                        return (_sd, _metadata) if return_metadata else _sd
                elif _role_matches("clip"):
                    # ── R42 M-01 (MINIMAL_RESTORE flow): CLIPLoader reads at
                    # request time; the restore-preload seam is unreachable.
                    # Serve the CLIP state dict from the Golden QD4 engine —
                    # the single physical CLIP read of the request.
                    try:
                        t_clip = time.perf_counter_ns()
                        _csd, _cmeta, _cdiag = _ctx.clip_golden_load(str(ckpt))
                        _ctx.ledger_sink.emit("clip_manifest_ready", presubmit_wall_ms=round((time.perf_counter_ns() - t_clip) / 1e6, 3))
                        print(
                            "[v2.golden_clip] torch_file=served mode=golden_qd4",
                            flush=True,
                        )
                        return (_csd, _cmeta) if return_metadata else _csd
                    except Exception as _clip_exc:
                        try:
                            _ctx.record_real_fallback("clip", f"torch_file_qd_failure:{type(_clip_exc).__name__}")
                            from . import loader_selection as _ls_fb4

                            _ls_fb4.record_observed("clip", "native_comfy", fallback_attempted=True, fallback_loader="native_comfy", fallback_reason=str(_clip_exc)[:160])
                        except Exception:
                            pass
                        print(
                            f"[v2.golden_clip] torch_file=fallback "
                            f"reason={type(_clip_exc).__name__}:{str(_clip_exc)[:120]}",
                            flush=True,
                        )
        except Exception:
            pass
        before = _torch_file_depth.get()
        _torch_file_depth.set(before + 1)
        _slow_read_state: _SlowReadBeforeState | None = None
        _slow_ru_before: dict[str, Any] | None = None
        _slow_io_before: dict[str, int] | None = None
        _read_outer_ns: int = 0
        _pf_before: _PageFaultSnapshot | None = None
        if before == 0:
            lane = _ACTIVE_LANE_TRACE.get()
            if lane is not None:
                _read_outer_ns = time.monotonic_ns()
                # Capture page-fault snapshot before actual read (CLIP/UNET page-in)
                if _PAGEFAULT_TRACKING and lane._lane in ("CLIP", "UNET"):
                    _pf_before = _PageFaultSnapshot.now()
                lane.read_start()
                if lane._lane == "CLIP":
                    _slow_read_state = _capture_slow_read_before()
                    _slow_ru_before, _slow_io_before = _collect_rusage_and_io_snapshots()
                if lane._lane == "UNET":
                    lane._trace.emit(
                        "unet_load_torch_file_start",
                        phase=lane._phase,
                        metadata={"lane": lane._lane, "path_hash": stable_hash(str(ckpt))[:16]},
                    )
        try:
            # R42A: this is the ONLY native checkpoint source-read seam —
            # count it (logical) for the post-ready native-I/O window.
            try:
                from . import golden_runtime_bridge as _grb_count

                _count_ctx = _grb_count.enabled_current()
                if _count_ctx is not None:
                    _count_ctx.count_native_source_read(str(ckpt))
            except Exception:
                pass
            return original(ckpt, safe_load=safe_load, device=device, return_metadata=return_metadata)
        finally:
            after = _torch_file_depth.get()
            _torch_file_depth.set(after - 1)
            if before == 0:
                lane = _ACTIVE_LANE_TRACE.get()
                if lane is not None:
                    lane.read_end()
                    _read_dur_ms = round((time.monotonic_ns() - _read_outer_ns) / 1_000_000, 3) if _read_outer_ns else 0.0
                    lane._on_read_completed(read_duration_ms=_read_dur_ms)
                    if lane._lane == "CLIP" and _slow_read_state is not None:
                        _after_mono = time.monotonic_ns()
                        _after_tt = time.thread_time_ns() if hasattr(time, "thread_time_ns") else None
                        _after_pt = time.process_time_ns() if hasattr(time, "process_time_ns") else None
                        _after_tid = _capture_tid()
                        _elapsed = round((_after_mono - _slow_read_state.mono_ns) / 1_000_000, 3)
                        if _elapsed >= _SLOW_READ_THRESHOLD_MS:
                            _slow_ru_after, _slow_io_after = _collect_rusage_and_io_snapshots()
                            _request_trace = _ACTIVE_REQUEST_TRACE.get()
                            _emit_slow_read_line(
                                owner="CLIP",
                                loader_type="load_torch_file",
                                path_str=str(ckpt) if ckpt else "",
                                request_id=str(_request_trace.request_id) if _request_trace is not None else "",
                                restore_session_id=_LATEST_RESTORE_SESSION_ID,
                                restored_instance_id=_LATEST_RESTORED_INSTANCE_ID,
                                before=_slow_read_state,
                                after_mono_ns=_after_mono,
                                after_thread_time_ns=_after_tt,
                                after_process_time_ns=_after_pt,
                                after_tid=_after_tid,
                                before_rusage=_slow_ru_before,
                                after_rusage=_slow_ru_after,
                                before_io=_slow_io_before,
                                after_io=_slow_io_after,
                            )
                    if lane._lane == "UNET":
                        lane._trace.emit(
                            "unet_load_torch_file_end",
                            phase=lane._phase,
                            metadata={"lane": lane._lane, "path_hash": stable_hash(str(ckpt))[:16]},
                        )
                    # Emit page-fault deltas for CLIP/UNET page-in after first access
                    if _pf_before is not None and lane._lane in ("CLIP", "UNET"):
                        _pf_after = _PageFaultSnapshot.now()
                        _delta = _pagefault_delta(_pf_before, _pf_after)
                        _metric_name = "clip_snapshot_pagein_ms" if lane._lane == "CLIP" else "unet_snapshot_pagein_ms"
                        lane._trace.emit(
                            _metric_name.replace("_ms", ""),
                            phase=lane._phase,
                            metadata={
                                "lane": lane._lane,
                                "major_faults": _delta["major_faults"],
                                "minor_faults": _delta["minor_faults"],
                                "duration_ms": _read_dur_ms if _read_outer_ns else 0.0,
                            },
                        )
    wrapper._comfy_modal_read_wrapper = True  # sentinel for idempotence
    return wrapper


def _opt_vae_h2d_capture(models: list[Any]) -> dict[str, Any]:
    """Best-effort pre-commit VAE storage summary (measurement-only).

    Runs BEFORE the lane's GPU commit so parameter devices are still the
    CPU source.  Sums storage bytes over each patcher's parameter tensors
    and reports pinning + source device.  Guarded end-to-end; returns a
    plain JSON-safe dict.
    """
    _bytes = 0
    _count = 0
    _pinned = False
    _source_device = ""
    try:
        for _m in models or ():
            _patched = getattr(_m, "model", _m)
            _params = getattr(_patched, "parameters", None)
            if not callable(_params):
                continue
            for _p in _params():
                try:
                    _st = _p.untyped_storage()
                    _bytes += int(_st.nbytes())
                except Exception:
                    _bytes += int(_p.numel() * _p.element_size())
                if not _source_device:
                    _source_device = str(getattr(_p, "device", ""))
                if not _pinned:
                    _pinned = bool(getattr(_p, "is_pinned", lambda: False)())
                _count += 1
    except Exception:
        pass
    return {
        "bytes": int(_bytes),
        "parameter_count": int(_count),
        "pinned": bool(_pinned),
        "source_device": str(_source_device),
    }


def _gpu_fast_return_enabled() -> bool:
    """True when the proven-ready GPU-load fast return is enabled.

    E26: promoted to the production default.  The behavior remains strictly
    fail-closed (the wrapper only short-circuits when the exact UNET is in
    the load list AND every parameter/buffer is provably CUDA-resident AND
    no force flags AND no mutation lane), so production enablement is safe.
    ``COMFYMODAL_V2_GPU_FAST_RETURN`` may still force-disable (value 0) or
    force-enable (1/true/yes/on); the default when unset is now ON.
    """
    raw = os.environ.get("COMFYMODAL_V2_GPU_FAST_RETURN", "1")
    stripped = raw.strip().lower()
    if stripped in ("0", "false", "no", "off"):
        return False
    return True


def _all_models_proven_cuda_resident(models: list[Any]) -> bool:
    """True when every model in *models* has ALL parameters and buffers on a
    CUDA device.  Fail-closed: any exception or any non-CUDA tensor -> False.
    """
    try:
        for model in models:
            inner = getattr(model, "model", None)
            if inner is None:
                inner = model
            for tensor in list(getattr(inner, "parameters", lambda: ())() or ()):
                if str(getattr(tensor, "device", "cpu")).startswith("cuda"):
                    continue
                return False
            for tensor in list(getattr(inner, "buffers", lambda: ())() or ()):
                if str(getattr(tensor, "device", "cpu")).startswith("cuda"):
                    continue
                return False
        return True
    except Exception:
        return False


def _r42_golden_unet_adoption(models: Any) -> bool:
    """Verify the demand-side bind; native GPU loading always proceeds."""
    try:
        from . import golden_runtime_bridge as _grb
        ctx = _grb.enabled_current()
        if ctx is None or not (models or []):
            return False
        unet_patchers = [m for m in models if getattr(getattr(m, "model", None), "diffusion_model", None) is not None]
        if not unet_patchers:
            return False
        sd = ctx.unet_payload(timeout_s=0.05)
        if not sd:
            ctx.record_io_uniqueness("unet", verify="payload_absent")
            ctx.record_real_fallback("unet", "demand_verify_payload_absent")
            from . import loader_selection as _ls_fb2

            _ls_fb2.record_observed("unet", "native_comfy", fallback_attempted=True, fallback_loader="native_comfy", fallback_reason="payload_absent")
            return False
        checked = matches = mismatches = 0
        for patcher in unet_patchers:
            diffusion = patcher.model.diffusion_model
            named = dict(diffusion.named_parameters())
            named.update(dict(diffusion.named_buffers()))
            for name, tensor in named.items():
                checked += 1
                candidate = sd.get(name)
                if candidate is None:
                    candidate = next((v for k, v in sd.items() if k.endswith(name)), None)
                ok = candidate is not None and tuple(tensor.shape) == tuple(candidate.shape) and tensor.dtype == candidate.dtype and str(tensor.device).startswith("cuda")
                matches += int(ok)
                mismatches += int(not ok)
        result = "match" if matches and mismatches == 0 else "mismatch"
        all_resident = _all_models_proven_cuda_resident(models)
        ctx.ledger_sink.emit(
            "unet_demand_verify", result=result, checked=checked,
            all_models_cuda_resident=all_resident,
        )
        if result == "match":
            from . import loader_selection
            loader_selection.record_observed("unet", "golden_qd4")
            # R42A: post-ready native I/O is MEASURED by the bridge window
            # (begin at DEVICE_READY, end at sampling start) — no assertion
            # counters here.
            ctx.record_io_uniqueness("unet", demand_join_count=len(unet_patchers), verify="match")
            # Construct wrapper already validated every tensor and weights are
            # cuda-resident; skip the redundant native load_models_gpu pass —
            # but ONLY when every model in this batch is already resident, so
            # a co-batched CLIP/VAE migration can never be silently dropped.
            if all_resident:
                return True
            return False
        else:
            ctx.add_degradation("golden_unet_identity_mismatch")
            ctx.record_io_uniqueness("unet", verify="mismatch")
            ctx.record_real_fallback("unet", "identity_mismatch")
            from . import loader_selection as _ls_fb3

            _ls_fb3.record_observed("unet", "native_comfy", fallback_attempted=True, fallback_loader="native_comfy", fallback_reason="identity_mismatch")
            return False
    except Exception:
        try:
            ctx.record_io_uniqueness("unet", verify="mismatch")
        except Exception:
            pass
    return False


def _make_gpu_loader_wrapper(original: Callable[..., Any]) -> Callable[..., Any]:
    """Wrap ``comfy.model_management.load_models_gpu`` to emit commit events.

    Reentrancy-safe.  Emits ``gpu_lane_wait_start/end`` using the real
    ``_MUTATION_LANE`` (non-zero when contention exists) so Phase-2
    wait durations are truthful.  ``gpu_commit_start/end`` bracket the
    actual call with full metadata (restore IDs, model identity,
    caller classification, wall/thread CPU durations).
    """

    @functools.wraps(original)
    def wrapper(models, memory_required=0, force_patch_weights=False,
                minimum_memory_required=None, force_full_load=False):
        before = _gpu_depth.get()
        _gpu_depth.set(before + 1)
        # ── E25: proven-ready fast return for an already GPU-resident
        # registered UNET (opt-in, fail-closed) ──
        # The fastsafetensors/execution UNET lane already bound + validated
        # every parameter on the target device.  The sampler's subsequent
        # load_models_gpu re-runs ComfyUI's ModelPatcher.load bookkeeping
        # (unpatch_hooks, load-list walk, patch accounting) over an already
        # resident model — real serial work with no transfers.  When the
        # exact UNET is provably all-on-target and the request is not
        # forcing a full load, short-circuit to a telemetry-preserving
        # fast return.  FAIL-CLOSED: the gate requires (a) opt-in env,
        # (b) a request-scoped trace, (c) no mutation lane (graph thread),
        # (d) a registered UNET in the load list, (e) every parameter of
        # every model on a CUDA device, and (f) no force_full_load /
        # force_patch_weights.  Any doubt falls through to the original
        # path.  D15 coordination is preserved: the fast return is a pure
        # bookkeeping skip (no GPU work), but it may never bypass the UNET
        # GPU gate while the CLIP critical section is active — the gate below
        # checks ``clip_critical_active`` so the D15 invariant (UNET GPU
        # overlap with CLIP critical = 0) is never weakened.
        _e25_fast_return = False
        if (
            before == 0
            and _gpu_fast_return_enabled()
            and not force_full_load
            and not force_patch_weights
            and _ACTIVE_REQUEST_TRACE.get() is not None
            and _ACTIVE_LANE_TRACE.get() is None
            and _has_registered_unet_in_models(models)
            and _all_models_proven_cuda_resident(models)
            # D15 strict: the fast return is a pure bookkeeping skip with no
            # GPU work — it may never bypass the UNET GPU gate while CLIP
            # owns the critical GPU section.  Fail-closed on any error.
            and not _gpu_coordination.clip_critical_active(
                str(getattr(_ACTIVE_REQUEST_TRACE.get(), "request_id", "") or "")
            )
        ):
            _e25_fast_return = True
            _gpu_request_call_count_var.set(_gpu_request_call_count_var.get() + 1)
            _request_trace_fr = _ACTIVE_REQUEST_TRACE.get()
            try:
                _request_trace_fr.emit(
                    "graph_gpu_load_fast_return",
                    phase="execution",
                    metadata={
                        "model_count": len(models),
                        "caller_classification": "sampler_setup_proven_ready",
                        "reason": "proven_cuda_resident",
                        "request_id": str(getattr(_request_trace_fr, "request_id", "") or ""),
                    },
                )
            except Exception:
                pass
        _graph_start_ns = 0
        _graph_thread_start_ns = None
        _graph_process_start_ns = None
        _caller = "not_observed"
        _wrapper_status = "installed"
        _lane_start_ns = 0
        _lane_thread_start_ns = None
        _model_identity_hash = ""
        _pf_h2d_before: _PageFaultSnapshot | None = None
        _h2d_metric_name: str = ""
        # LANE 4 (measurement-only): pre-commit VAE storage summary.
        _vae_h2d_before: dict[str, Any] | None = None
        # Exclusive-ownership join outcome (graph path; None when not applicable).
        _ownership_join: dict[str, Any] | None = None
        # Activation diagnostics record (captured on outermost entry)
        _gpu_record: dict[str, Any] | None = None
        _unet_gpu_gate: Any = None
        # First request-scoped UNET activation variance (diagnostic-only).
        _variance_first_unet = False
        _variance_t0 = None
        _variance_t1 = None
        _variance_pretouch_record = None
        _variance_page_readiness_record = None
        _variance_registry_record = None
        if before == 0:
            count = _gpu_request_call_count_var.get()
            _gpu_request_call_count_var.set(count + 1)
            lane = _ACTIVE_LANE_TRACE.get()
            request_trace = _ACTIVE_REQUEST_TRACE.get()
            # ── E29: canonical ledger load_models_gpu span (outermost) ───
            # Every request-scoped load_models_gpu call becomes one ledger
            # span so the serial ledger owns the VAE/UNET model-management
            # wall (entry -> lane wait -> load -> exit) instead of hiding it
            # inside the anonymous sampling_end->VAE window.  Reentrant
            # calls keep their own span (only the outermost is bridged).
            _ledger_mm_span: Any = None
            try:
                from .critical_path_ledger import TraceSpanBridge
                _ledger_mm_bridge = TraceSpanBridge(
                    "model-mgmt:load_models_gpu", lane="MODEL-MGMT",
                    metadata={"caller": "gpu_loader_wrapper"},
                )
                _ledger_mm_bridge.start(mono_ns=time.monotonic_ns())
            except Exception:
                _ledger_mm_bridge = None
            _variance_first_unet = (
                request_trace is not None
                and lane is None
                and _has_registered_unet_in_models(models)
                and variance_diagnostics_enabled()
            )
            if _variance_first_unet:
                _variance_t0 = capture_metric_snapshot()
            _graph_start_ns = time.monotonic_ns()
            _graph_thread_start_ns = time.thread_time_ns() if hasattr(time, "thread_time_ns") else None
            _graph_process_start_ns = time.process_time_ns() if hasattr(time, "process_time_ns") else None
            # Prepare activation diagnostic record.
            # Page-fault baselines start as None (unmeasured) — they become
            # ints ONLY when getrusage actually succeeds.  This keeps the
            # emitted record honest (JSON null) instead of faking 0s when
            # getrusage is unavailable (e.g. under gVisor runsc).
            _start_minflt: int | None = None
            _start_majflt: int | None = None
            if observability_allows("detailed_activation"):
                try:
                    try:
                        import resource as _r_gpu
                        _start_ru = _r_gpu.getrusage(_r_gpu.RUSAGE_SELF)
                        _start_minflt = _start_ru.ru_minflt
                        _start_majflt = _start_ru.ru_majflt
                    except (ImportError, AttributeError):
                        pass
                except Exception:
                    pass
            _gpu_alloc_before = None
            _gpu_reserved_before = None
            if observability_allows("detailed_activation"):
                try:
                    import torch as _torch_gpu
                    if _torch_gpu.cuda.is_available():
                        _gpu_alloc_before = int(_torch_gpu.cuda.memory_allocated())
                        _gpu_reserved_before = int(_torch_gpu.cuda.memory_reserved())
                except Exception:
                    pass
            _gpu_record = {
                "call_index": _gpu_request_call_count_var.get(),
                "caller": "",
                "model_count": len(models),
                "model_types": [type(model).__module__ + "." + type(model).__qualname__ for model in models],
                "model_object_ids": [str(id(model)) for model in models],
                "contains_registered_unet": int(_has_registered_unet_in_models(models)),
                "gpu_allocated_before": _gpu_alloc_before,
                "gpu_reserved_before": _gpu_reserved_before,
                "start_monotonic_ns": _graph_start_ns,
                "_thread_start_ns": _graph_thread_start_ns,
                "_process_start_ns": _graph_process_start_ns,
                "_minor_faults_before": _start_minflt,
                "_major_faults_before": _start_majflt,
            }
            # Classify the caller BEFORE the entry boundary so the entry line
            # logs the ACTUAL classification, never the pre-classification
            # placeholder ("not_observed"/"pending").
            if lane is not None and lane._lane == "UNET":
                _caller = "background_unet_preparation"
            elif lane is not None and lane._lane == "CLIP":
                _caller = "restore_clip_preparation"
            elif lane is not None and lane._lane == "VAE":
                _caller = "restore_vae_preparation"
            elif lane is None and request_trace is not None:
                if observability_allows("detailed_activation"):
                    try:
                        import inspect as _inspect
                        _frames = " ".join(frame.function.lower() for frame in _inspect.stack(context=0)[:12])
                        if "sampler" in _frames:
                            _caller = "sampler_setup"
                        else:
                            _caller = "graph_model_loading"
                    except Exception:
                        _caller = "graph_model_loading"
                else:
                    _caller = "graph_model_loading"
                _model_identity_hash = stable_hash([type(model).__module__ + "." + type(model).__qualname__ for model in models])[:16]
                request_trace.emit("graph_gpu_load_start", phase="execution", metadata={
                    "model_identity_hash": _model_identity_hash,
                    "memory_required": memory_required,
                    "force_patch_weights": force_patch_weights,
                    "force_full_load": force_full_load,
                    "caller_classification": _caller,
                    "gpu_wrapper_status": _wrapper_status,
                    "gpu_request_invocation_count": _gpu_request_call_count_var.get(),
                    "restore_session_id": _LATEST_RESTORE_SESSION_ID,
                    "restored_instance_id": _LATEST_RESTORED_INSTANCE_ID,
                    "contains_registered_unet": _gpu_record["contains_registered_unet"],
                })
            if lane is None and request_trace is None:
                # Installed wrapper called outside any lane/request scope
                _caller = "not_observed"
                global _not_observed_gpu_calls
                _not_observed_gpu_calls += 1
            # ── Authoritative load_models_gpu boundary: entry ──
            # role/identity/device/memory evidence per model, no tensor contents.
            try:
                _gpu_roles = ",".join(
                    _resolve_model_role_for_boundary(m) for m in models
                )
                print(
                    f"[v2.gpu_load_boundary] event=load_models_gpu_start "
                    f"request_id={str(request_trace.request_id) if request_trace is not None else 'absent'} "
                    f"restored_instance_id={_LATEST_RESTORED_INSTANCE_ID or 'absent'} "
                    f"restore_session_id={_LATEST_RESTORE_SESSION_ID or 'absent'} "
                    f"roles={_gpu_roles} "
                    f"model_count={len(models)} "
                    f"contains_registered_unet={_gpu_record['contains_registered_unet']} "
                    f"caller_classification={_caller} "
                    f"gpu_allocated_before={_gpu_alloc_before if _gpu_alloc_before is not None else 'absent'} "
                    f"gpu_reserved_before={_gpu_reserved_before if _gpu_reserved_before is not None else 'absent'}",
                    flush=True,
                )
            except Exception:
                pass
            # Always-on UNET first-CUDA demand start:
            # Record the monotonic_ns when load_models_gpu is first called
            # for a registered UNET in this request, regardless of lane state.
            # Previously this was inside `elif lane is None` so lane-owned
            # calls (e.g. background restore) or any non-None lane during
            # request execution would skip demand tracking.
            # Must stay inside `if before == 0:` scope.
            if request_trace is not None and _has_registered_unet_in_models(models):
                set_unet_gpu_demand_start(request_trace.request_id, time.monotonic_ns())
                request_trace.emit("unet_gpu_demand_start", metadata={
                    "request_id": request_trace.request_id,
                    "caller_classification": _caller,
                })
            if lane is not None:
                lane._on_gpu_commit_about_to_start()
                _get_mutation_lane().acquire(lane._lane if lane else None)
                lane.gpu_lane_wait_start()
                lane.gpu_lane_wait_end()
                # Capture page-fault snapshot before H2D commit
                if _PAGEFAULT_TRACKING:
                    _pf_h2d_before = _PageFaultSnapshot.now()
                    _h2d_metric_name = "clip_h2d_ms" if lane._lane == "CLIP" else "unet_h2d_ms"
                # LANE 4 (measurement-only): pre-commit VAE storage summary
                # (source device/pinning must be captured before the move).
                if _OPT_DIAG and lane._lane == "VAE":
                    _vae_h2d_before = _opt_vae_h2d_capture(models)
                # Compute metadata for lane-owned commit events
                _lane_start_ns = time.monotonic_ns()
                _lane_thread_start_ns = time.thread_time_ns() if hasattr(time, "thread_time_ns") else None
                _model_identity_hash = stable_hash([type(model).__module__ + "." + type(model).__qualname__ for model in models])[:16]
                lane.gpu_commit_start(
                    request_id=str(request_trace.request_id) if request_trace is not None else "",
                    restore_session_id=_LATEST_RESTORE_SESSION_ID,
                    restored_instance_id=_LATEST_RESTORED_INSTANCE_ID,
                    model_identity_hash=_model_identity_hash,
                    memory_required=memory_required,
                    force_patch_weights=force_patch_weights,
                    force_full_load=force_full_load,
                    caller_classification=_caller,
                    gpu_wrapper_status=_wrapper_status,
                    gpu_request_invocation_count=_gpu_request_call_count_var.get(),
                )
        # ── Residency sampler: unet_gpu_load_before (around first UNET-containing call) ──
        _residency_sampler_fired = False
        if before == 0 and request_trace is not None and _has_registered_unet_in_models(models):
            _res_cb = _RESIDENCY_SAMPLER_CALLBACK.get()
            if _res_cb is not None:
                try:
                    _res_cb("unet_gpu_load_before", request_trace)
                except Exception:
                    pass
                _residency_sampler_fired = True
        # ``force_full_load`` only bypasses ComfyUI's low-VRAM calculation;
        # it does not clear a stale ModelPatcher loaded-byte/device state.
        # For the V2 clip_gpu_ready prefill call, normalize the exact armed
        # CLIP patcher while the existing mutation lane is held, immediately
        # before the real load path.  This keeps the subsequent call a normal
        # ComfyUI load (and therefore preserves the existing fire hook), while
        # preventing a zero-effect load from being mistaken for a GPU transfer.
        if (
            before == 0
            and force_full_load
            and lane is not None
            and getattr(lane, "_lane", "") == "prefill"
            and not _has_registered_unet_in_models(models)
        ):
            _prepare_armed_clip_for_force_load(
                models, request_trace or getattr(lane, "_trace", None),
            )
        # ── Exclusive UNET ownership: graph join-or-adopt (before ANY
        # inspection/mutation of a registered retained UNET). ──────────
        # Graph-side ``load_models_gpu`` for a request-scoped registered
        # UNET runs on the graph thread with NO mutation lane.  Under the
        # exclusive-owner gate, the graph joins the scheduled activation
        # future (or adopts) BEFORE the pretouch/page-readiness/registry
        # diagnostics below can inspect the model and before ``original()``
        # can patch/move/load it — so the worker and graph can never touch
        # the same UNET concurrently.  A ready outcome turns the subsequent
        # graph load into a cache validation; a cancelled/non-ready outcome
        # means the graph owns (adopts) the load.
        _ownership_join: dict[str, Any] | None = None
        if (
            before == 0
            and lane is None
            and request_trace is not None
            and _has_registered_unet_in_models(models)
            and exclusive_unet_owner_enabled()
        ):
            try:
                _ownership_join = graph_unet_join_or_adopt(
                    str(request_trace.request_id), trace=request_trace,
                )
            except Exception:
                _ownership_join = {"decision": "error"}
        # ── Diagnostic pre-touch: first request-scoped graph UNET activation ──
        # Real-reads every page of every retained CPU UNET storage range
        # (bounded by a per-page read chunk and a page budget) immediately
        # before the normal request-scoped activation.  Gated by
        # COMFYMODAL_V2_UNET_PRETOUCH (default off); diagnostic-only, never
        # uses CUDA sync, never alters production defaults, and is
        # exception-safe.  Bounded per-request guard (never modal_app cleanup).
        if (
            before == 0
            and request_trace is not None
            and lane is None
            and unet_pretouch_enabled()
            and _has_registered_unet_in_models(models)
        ):
            _pt_request_id = str(request_trace.request_id)
            if _unet_pretouch_begin(_pt_request_id):
                try:
                    # Prefer the worker-attached CPU pretouch record (real
                    # reads ran on the retained CPU snapshot pre-transfer).  If
                    # absent, run fresh ONLY if the registered UNET is still
                    # CPU-resident — never on a post-transfer CUDA model.
                    _pt_attached = _resolve_unet_cpu_pretouch(models)
                    if _pt_attached is not None:
                        _variance_pretouch_record = _pt_attached
                    else:
                        _pt_unet = _first_registered_unet_model(models)
                        if _pt_unet is not None and _model_is_cpu_resident(_pt_unet):
                            _variance_pretouch_record = pretouch_unet_storage(_pt_unet)
                            request_trace.emit(
                                "unet_activation_pretouch",
                                phase="execution",
                                metadata=_variance_pretouch_record,
                            )
                except Exception:
                    pass
        # ── Synchronous native page-readiness: first request-scoped graph ──
        # UNET activation only.  Conditions: outermost call (before == 0), a
        # request trace, NO active model lane (never a restore-time background
        # lane), and a registered retained UNET in the model list.  The mode
        # gate runs FIRST so that when the candidate is off (default) nothing
        # is claimed, traversed, or called.  The per-request guard guarantees
        # the readiness helper runs at most once per request for the same UNET
        # activation; it is released in the existing request cleanup
        # (modal_app request finally block).  Gated by
        # COMFYMODAL_V2_PAGE_READINESS_MODE=willneed (off by default);
        # synchronous, never schedules a future or duplicates the transfer.
        if (
            before == 0
            and request_trace is not None
            and lane is None
            and page_readiness_mode() == _PAGE_READINESS_MODE_WILLNEED
            and _has_registered_unet_in_models(models)
        ):
            _pr_request_id = str(request_trace.request_id)
            if _unet_page_readiness_begin(_pr_request_id):
                try:
                    _pr_unet = _first_registered_unet_model(models)
                    if _pr_unet is not None:
                        _variance_page_readiness_record = _run_unet_page_readiness(
                            _pr_unet, trace=request_trace, request_id=_pr_request_id,
                        )
                except Exception:
                    pass
        # ── Unique UNET registry accounting (diagnostics-on, pretouch off/on) ──
        # Always build/record the deduplicated CPU UNET storage registry when
        # variance diagnostics are on — independent of the pretouch gate — so
        # the aggregate carries union bytes/pages even when pretouch is off.
        # No reads are performed here; pretouch remains the explicit gated
        # real-read operation.
        if _variance_first_unet and _variance_registry_record is None:
            # Resolve the CPU registry WITHOUT rebuilding on a post-transfer
            # CUDA model: prefer the worker-attached CPU registry, else build
            # fresh only if the registered UNET is still CPU-resident.  A
            # post-transfer CUDA model with no attached registry is reported
            # as unavailable, never as 0/device:cuda.
            _variance_registry_record, _registry_source = _resolve_unet_cpu_registry(models)
            if _variance_registry_record is not None:
                _variance_registry_record["source"] = _registry_source
            else:
                _variance_registry_record = {"source": _registry_source,
                                             "unique_storage_count": 0,
                                             "total_bytes": 0,
                                             "expected_pages": 0}
        if _variance_first_unet:
            _variance_t1 = capture_metric_snapshot()
        # ── Synchronized CPU->GPU transfer (diagnostic-only sync) ──
        # When the variance gate is on, synchronize CUDA before and after the
        # actual load so the timed transfer reflects completion, not just async
        # submission.  Gated on _variance_first_unet (which requires the gate),
        # so no CUDA initialization is ever triggered when diagnostics are off.
        if _variance_first_unet:
            cuda_sync_if_enabled()
        _diag_ok = False
        _coord_lane = _ACTIVE_LANE_TRACE.get() if before != 0 else lane
        _coord_trace = (_ACTIVE_REQUEST_TRACE.get() if before != 0 else request_trace) or (
            getattr(_coord_lane, "_trace", None) if _coord_lane is not None else None
        )
        try:
            # ── E25: proven-ready fast return (no GPU work, no D15 gate) ──
            # Emitted only when the opt-in gate above set the flag; the
            # telemetry + call accounting already ran.  Returns the models
            # list unchanged (ComfyUI's load_models_gpu returns the models).
            if _e25_fast_return:
                return models
            # ── R42 M-02: Golden UNET payload adoption (native skipped) ──
            if before == 0 and not force_full_load and not force_patch_weights:
                try:
                    if _r42_golden_unet_adoption(models):
                        return models
                except Exception:
                    pass
            if (
                before == 0
                and _coord_trace is not None
                and _has_registered_unet_in_models(models)
                and _gpu_coordination.enabled()
                and (_coord_lane is None or getattr(_coord_lane, "_lane", "") == "UNET")
            ):
                _unet_gpu_gate = _gpu_coordination.begin_unet_gpu_phase(
                    str(getattr(_coord_trace, "request_id", "") or ""),
                    _coord_trace,
                    reason="clip_gpu_critical_active",
                )
            _retval = original(models, memory_required=memory_required,
                               force_patch_weights=force_patch_weights,
                               minimum_memory_required=minimum_memory_required,
                               force_full_load=force_full_load)
            _diag_ok = True
            if _variance_first_unet:
                cuda_sync_if_enabled()
            return _retval
        finally:
            if _unet_gpu_gate is not None:
                try:
                    _unet_gpu_end_ns = time.monotonic_ns()
                    _gpu_coordination.end_unet_gpu_phase(
                        _unet_gpu_gate, success=_diag_ok
                    )
                    try:
                        from .fast_cold_orchestration import record_unet_gpu_interval

                        record_unet_gpu_interval(
                            _unet_gpu_gate.started_ns / 1_000_000_000.0,
                            _unet_gpu_end_ns / 1_000_000_000.0,
                            "native_or_snapshot_activation",
                            trace=_coord_trace,
                        )
                    except Exception:
                        pass
                except Exception:
                    pass
            after = _gpu_depth.get()
            _gpu_depth.set(after - 1)
            if before == 0:
                lane = _ACTIVE_LANE_TRACE.get()
                request_trace = _ACTIVE_REQUEST_TRACE.get()
                if lane is not None:
                    _lane_end_ns = time.monotonic_ns()
                    _lane_thread_end_ns = time.thread_time_ns() if hasattr(time, "thread_time_ns") else None
                    # Emit H2D page-fault deltas for lane-owned GPU commits
                    if _pf_h2d_before is not None and _h2d_metric_name:
                        _pf_h2d_after = _PageFaultSnapshot.now()
                        _delta = _pagefault_delta(_pf_h2d_before, _pf_h2d_after)
                        lane._trace.emit(
                            _h2d_metric_name.replace("_ms", ""),
                            phase=lane._phase,
                            metadata={
                                "lane": lane._lane,
                                "major_faults": _delta["major_faults"],
                                "minor_faults": _delta["minor_faults"],
                                "duration_ms": round((_lane_end_ns - _lane_start_ns) / 1_000_000, 3),
                                "caller_classification": _caller,
                            },
                        )
                    # LANE 4 (measurement-only): VAE lane H2D transfer facts
                    if _vae_h2d_before is not None:
                        try:
                            emit_opt(lane._trace, "vae_h2d_transfer", phase=lane._phase, metadata={
                                "lane": lane._lane,
                                "bytes": int(_vae_h2d_before["bytes"]),
                                "total_mib": round(int(_vae_h2d_before["bytes"]) / (1 << 20), 3),
                                "parameter_count": int(_vae_h2d_before["parameter_count"]),
                                "pinned": bool(_vae_h2d_before["pinned"]),
                                "source_device": str(_vae_h2d_before["source_device"]),
                                "device_ms": round((_lane_end_ns - _lane_start_ns) / 1_000_000, 3),
                                "stream": opt_stream_info(),
                                "caller_classification": _caller,
                            })
                        except Exception:
                            pass
                    lane.gpu_commit_end(
                        host_wall_duration_ms=round((_lane_end_ns - _lane_start_ns) / 1_000_000, 3),
                        thread_cpu_duration_ms=round((_lane_thread_end_ns - _lane_thread_start_ns) / 1_000_000, 3) if _lane_thread_end_ns is not None and _lane_thread_start_ns is not None else None,
                        request_id=str(request_trace.request_id) if request_trace is not None else "",
                        restore_session_id=_LATEST_RESTORE_SESSION_ID,
                        restored_instance_id=_LATEST_RESTORED_INSTANCE_ID,
                        model_identity_hash=_model_identity_hash,
                        memory_required=memory_required,
                        force_patch_weights=force_patch_weights,
                        force_full_load=force_full_load,
                        caller_classification=_caller,
                        gpu_wrapper_status=_wrapper_status,
                        gpu_request_invocation_count=_gpu_request_call_count_var.get(),
                    )
                    _get_mutation_lane().release(lane._lane if lane else None)
                elif request_trace is not None:
                    _thread_end_ns = time.thread_time_ns() if hasattr(time, "thread_time_ns") else None
                    request_trace.emit("graph_gpu_load_end", phase="execution", metadata={
                        "host_wall_duration_ms": round((time.monotonic_ns() - _graph_start_ns) / 1_000_000, 3),
                        "thread_cpu_duration_ms": round((_thread_end_ns - _graph_thread_start_ns) / 1_000_000, 3) if _thread_end_ns is not None and _graph_thread_start_ns is not None else None,
                        "caller_classification": _caller,
                        "gpu_wrapper_status": _wrapper_status,
                        "gpu_request_invocation_count": _gpu_request_call_count_var.get(),
                        "restored_instance_id": _LATEST_RESTORED_INSTANCE_ID,
                        "restore_session_id": _LATEST_RESTORE_SESSION_ID,
                        "model_identity_hash": _model_identity_hash,
                        "memory_required": memory_required,
                        "force_patch_weights": force_patch_weights,
                        "force_full_load": force_full_load,
                        "exclusive_ownership_join": (
                            dict(_ownership_join) if _ownership_join is not None else None
                        ),
                    })
                # ── First request-scoped UNET activation aggregate variance ──
                # Diagnostic-only (COMFYMODAL_V2_VARIANCE_DIAGNOSTICS).  Splits
                # the activation into explicit stages using our own metric
                # snapshots, and reuses the existing model-patcher load
                # breakdown event (never guessed).  Emitted after the transfer
                # completes and only for a successful outermost first-UNET
                # request-scoped activation.
                if (
                    _variance_first_unet
                    and _diag_ok
                    and _variance_t0 is not None
                    and _variance_t1 is not None
                ):
                    try:
                        _variance_t2 = capture_metric_snapshot()
                        # Transfer bytes come from the unique registry union
                        # (available whenever diagnostics are on, even when the
                        # pretouch gate is off); pretouch is NOT the source.
                        _transfer_bytes = None
                        if isinstance(_variance_registry_record, Mapping):
                            _tb = _variance_registry_record.get("total_bytes")
                            if isinstance(_tb, int) and _tb > 0:
                                _transfer_bytes = _tb
                        # Truthful CPU page-traversal sub-stage: only populated
                        # when an explicit traversal ran (pretouch or
                        # page-readiness).  When neither ran, we do NOT claim
                        # the pre-load interval is page hydration — the
                        # sub-record carries wall_ms=None so the report reports
                        # it unavailable.
                        _hydration_ran = (
                            _variance_pretouch_record is not None
                            or _variance_page_readiness_record is not None
                        )
                        if _hydration_ran:
                            _traversal = timed_transfer_partition(
                                _variance_t0, _variance_t1, label="cpu_page_traversal",
                            )
                        else:
                            _traversal = {"stage": "cpu_page_traversal", "wall_ms": None}
                        # load_models_gpu launch + synchronized completion.
                        _xf = timed_transfer_partition(
                            _variance_t1, _variance_t2, label="cpu_to_gpu_transfer",
                            bytes_=_transfer_bytes,
                        )
                        _loader_wall_ms = None
                        if (_variance_t0 is not None and _variance_t2 is not None
                                and isinstance(_variance_t0.get("mono_ns"), int)
                                and isinstance(_variance_t2.get("mono_ns"), int)):
                            _loader_wall_ms = round(
                                max(0, _variance_t2["mono_ns"] - _variance_t0["mono_ns"]) / 1_000_000, 3
                            )
                        # Reconciliation sums only the measured outer stages.
                        # Patcher bookkeeping is NESTED inside the transfer and
                        # must never be counted as an exclusive substage.
                        _recon = reconciliation_fields(
                            _loader_wall_ms,
                            {"cpu_page_traversal": _traversal.get("wall_ms"),
                             "cpu_to_gpu_transfer": _xf.get("wall_ms")},
                        )
                        _patcher_ms = None
                        _patcher_counts: dict[str, Any] = {}
                        _load_models_gpu_wall_ms = None
                        for _ev in request_trace.events:
                            if _ev.name == "model_patcher_load_breakdown":
                                _patcher_ms = _ev.metadata.get("wall_ms")
                                for _k in ("patch_weight_count", "cast_count"):
                                    _v = _ev.metadata.get(_k)
                                    if _v is not None:
                                        _patcher_counts[_k] = _v
                            elif _ev.name == "load_models_gpu_duration":
                                _load_models_gpu_wall_ms = _ev.metadata.get("duration_ms")
                        _pub_ms, _pub_src = activation_publication_ms(request_trace)
                        request_trace.emit(
                            "first_unet_activation_variance",
                            phase="execution",
                            metadata={
                                "request_id": str(request_trace.request_id),
                                "gate": "COMFYMODAL_V2_VARIANCE_DIAGNOSTICS",
                                "cpu_page_traversal": _traversal,
                                "cpu_to_gpu_transfer": _xf,
                                "loader_reconciliation": _recon,
                                "load_models_gpu_wall_ms": _load_models_gpu_wall_ms,
                                "activation_future_publication_ms": _pub_ms,
                                "activation_future_publication_source": _pub_src,
                                "patcher_bookkeeping_ms": _patcher_ms,
                                "patcher_bookkeeping_counts": _patcher_counts,
                                "patcher_bookkeeping_nested": _patcher_ms is not None,
                                "unet_storage_registry": _variance_registry_record,
                                "pretouch": _variance_pretouch_record,
                                "page_readiness": _variance_page_readiness_record,
                            },
                        )
                    except Exception:
                        pass
                # ── Phase 1A candidate (clip_gpu_ready): fire the armed
                # single-use retained-UNET activation exactly once.  Runs
                # AFTER the qualifying successful CLIP load_models_gpu call
                # returned AND the mutation lane was released above; only
                # outermost prefill-lane calls with the exact armed CLIP
                # patcher and no registered UNET qualify.  Uses the prefill
                # lane trace/request id — never _ACTIVE_REQUEST_TRACE (absent
                # in coordinator threads).
                _maybe_fire_clip_gpu_ready_activation(
                    models=models,
                    lane_trace=lane,
                    load_ok=_diag_ok,
                    gpu_allocated_before=_gpu_alloc_before,
                )
                if _diag_ok:
                    emit_post_load_models_gpu_event(models)
                    # load_models_gpu duration measurement (complementary to the
                    # forward-probe-based unet_first_cuda_op emitted from the
                    # actual diffusion model forward).
                    if _caller in ("graph_model_loading", "sampler_setup"):
                        _op_duration_ms: float | None = None
                        if _lane_start_ns:
                            _op_duration_ms = round((time.monotonic_ns() - _lane_start_ns) / 1_000_000, 3)
                        elif _graph_start_ns:
                            _op_duration_ms = round((time.monotonic_ns() - _graph_start_ns) / 1_000_000, 3)
                        if _op_duration_ms is not None:
                            _rt = _ACTIVE_REQUEST_TRACE.get()
                            if _rt is not None:
                                _rt.emit(
                                    "load_models_gpu_duration",
                                    phase="execution",
                                    metadata={
                                        "caller_classification": _caller,
                                        "duration_ms": _op_duration_ms,
                                        "gpu_request_invocation_count": _gpu_request_call_count_var.get(),
                                        "model_identity_hash": _model_identity_hash,
                                        "memory_required": memory_required,
                                    },
                                )
                # ── Append GPU record to activation diagnostics state ──
                if _gpu_record is not None and _diag_ok and observability_allows("detailed_activation"):
                    try:
                        try:
                            import resource as _r_end
                            _has_res_end = True
                            _end_ru = _r_end.getrusage(_r_end.RUSAGE_SELF)
                        except ImportError:
                            _has_res_end = False
                            _end_ru = None
                        _end_wall_ns = time.monotonic_ns()
                        _end_thread_ns = time.thread_time_ns() if hasattr(time, "thread_time_ns") else 0
                        _end_process_ns = time.process_time_ns() if hasattr(time, "process_time_ns") else 0
                        # GPU alloc/reserved after
                        _gpu_alloc_after = None
                        _gpu_reserved_after = None
                        try:
                            import torch as _torch_after
                            if _torch_after.cuda.is_available():
                                _gpu_alloc_after = int(_torch_after.cuda.memory_allocated())
                                _gpu_reserved_after = int(_torch_after.cuda.memory_reserved())
                        except Exception:
                            pass
                        _gpu_record["caller"] = _caller
                        _gpu_record["end_monotonic_ns"] = _end_wall_ns
                        _gpu_record["gpu_allocated_after"] = _gpu_alloc_after
                        _gpu_record["gpu_reserved_after"] = _gpu_reserved_after
                        if _end_ru is not None:
                            _end_minflt = _end_ru.ru_minflt
                            _end_majflt = _end_ru.ru_majflt
                        else:
                            _end_minflt = None
                            _end_majflt = None
                        _gpu_record["wall_ms"] = round((_end_wall_ns - _gpu_record["start_monotonic_ns"]) / 1_000_000, 3)
                        _process_start = _gpu_record.get("_process_start_ns")
                        _thread_start = _gpu_record.get("_thread_start_ns")
                        _gpu_record["process_cpu_ms"] = round((_end_process_ns - _process_start) / 1_000_000, 3) if _process_start is not None else None
                        _gpu_record["thread_cpu_ms"] = round((_end_thread_ns - _thread_start) / 1_000_000, 3) if _thread_start is not None else None
                        # Honest fault deltas: None (JSON null) whenever either
                        # endpoint was unmeasured — never fake 0s.
                        _gpu_record["minor_faults"] = (
                            max(0, _end_minflt - _gpu_record.get("_minor_faults_before"))
                            if _end_minflt is not None and _gpu_record.get("_minor_faults_before") is not None
                            else None
                        )
                        _gpu_record["major_faults"] = (
                            max(0, _end_majflt - _gpu_record.get("_major_faults_before"))
                            if _end_majflt is not None and _gpu_record.get("_major_faults_before") is not None
                            else None
                        )
                        _gpu_record["gpu_allocated_delta_bytes"] = (
                            _gpu_alloc_after - _gpu_record["gpu_allocated_before"]
                            if _gpu_alloc_after is not None and _gpu_record.get("gpu_allocated_before") is not None
                            else None
                        )
                        for _k in ("_thread_start_ns", "_process_start_ns", "_minor_faults_before", "_major_faults_before"):
                            _gpu_record.pop(_k, None)
                        _diag_state = _ACTIVATION_DIAGNOSTIC_STATE.get()
                        if _diag_state is not None:
                            _diag_state["gpu_load_calls"].append(dict(_gpu_record))
                            record_activation_receipt(
                                "load_models_gpu",
                                status="completed",
                                role="UNET" if _gpu_record.get("contains_registered_unet") else "model",
                                started_ns=_gpu_record.get("start_monotonic_ns"),
                                completed_ns=_gpu_record.get("end_monotonic_ns"),
                                metadata={
                                    "caller": _caller,
                                    "model_count": _gpu_record.get("model_count"),
                                    "contains_registered_unet": _gpu_record.get("contains_registered_unet"),
                                },
                            )
                        if request_trace is not None:
                            request_trace.emit(
                                "load_models_gpu_diagnostic",
                                phase="execution",
                                metadata=dict(_gpu_record),
                            )
                        # ── Authoritative load_models_gpu boundary: exit ──
                        # Post-load device/cache/memory evidence so activation is
                        # proven by data, not only by fast return.
                        try:
                            _gpu_roles_exit = ",".join(
                                _resolve_model_role_for_boundary(m) for m in models
                            )
                            _gpu_mem_delta = _gpu_record.get("gpu_allocated_delta_bytes")
                            print(
                                f"[v2.gpu_load_boundary] event=load_models_gpu_end "
                                f"request_id={str(request_trace.request_id) if request_trace is not None else 'absent'} "
                                f"restored_instance_id={_LATEST_RESTORED_INSTANCE_ID or 'absent'} "
                                f"restore_session_id={_LATEST_RESTORE_SESSION_ID or 'absent'} "
                                f"roles={_gpu_roles_exit} "
                                f"model_count={len(models)} "
                                f"caller_classification={_caller} "
                                f"wall_ms={_gpu_record.get('wall_ms')} "
                                f"gpu_allocated_after={_gpu_alloc_after if _gpu_alloc_after is not None else 'absent'} "
                                f"gpu_allocated_delta_bytes={_gpu_mem_delta if _gpu_mem_delta is not None else 'absent'}",
                                flush=True,
                            )
                        except Exception:
                            pass
                    except Exception:
                        pass
                elif _gpu_record is not None and _diag_ok:
                    _end_wall_ns = time.monotonic_ns()
                    _gpu_record["caller"] = _caller
                    _gpu_record["end_monotonic_ns"] = _end_wall_ns
                    _diag_state = _ACTIVATION_DIAGNOSTIC_STATE.get()
                    if _diag_state is not None:
                        try:
                            record_activation_receipt(
                                "load_models_gpu",
                                status="completed",
                                role="UNET" if _gpu_record.get("contains_registered_unet") else "model",
                                started_ns=_gpu_record.get("start_monotonic_ns"),
                                completed_ns=_end_wall_ns,
                                metadata={
                                    "caller": _caller,
                                    "model_count": _gpu_record.get("model_count"),
                                    "contains_registered_unet": _gpu_record.get("contains_registered_unet"),
                                },
                            )
                        except Exception:
                            pass
                # ── Residency sampler: unet_gpu_load_after ──
                if _residency_sampler_fired:
                    _res_cb_after = _RESIDENCY_SAMPLER_CALLBACK.get()
                    if _res_cb_after is not None:
                        try:
                            _res_cb_after("unet_gpu_load_after", request_trace)
                        except Exception:
                            pass
            # ── E29: close the canonical ledger load_models_gpu span ─────
            try:
                from .critical_path_ledger import TraceSpanBridge
                TraceSpanBridge("model-mgmt:load_models_gpu", lane="MODEL-MGMT").end(
                    mono_ns=time.monotonic_ns()
                )
            except Exception:
                pass
    wrapper._comfy_modal_gpu_wrapper = True
    return wrapper


# ── Deep-diagnostic safetensors/torch.load decomposition wrappers ───
# Only active when:
#   1. _DIAGNOSTIC_FLAG is True
#   2. The calling thread's _DEEP_TARGET_PATH is non-empty AND matches
#      the file being accessed (avoid logging unrelated model loads)
#   3. The active lane trace is UNET
# These are globally installed but filtered by thread-local path, so
# unrelated file activity is never logged.


class _SafeOpenProxy:
    """Delegating proxy for safetensors.safe_open that wraps get_tensor
    for aggregate diagnostics without mutating the native C-extension object.
    _orig_gt(k) is called exactly once per requested tensor key.
    """
    def __init__(self, wrapped, orig_gt, count_agg, bytes_agg, series=None, series_cap=2048):
        object.__setattr__(self, "_wrapped", wrapped)
        object.__setattr__(self, "_orig_gt", orig_gt)
        object.__setattr__(self, "_count_agg", count_agg)
        object.__setattr__(self, "_bytes_agg", bytes_agg)
        object.__setattr__(self, "_series", series)
        object.__setattr__(self, "_series_cap", int(series_cap))
        object.__setattr__(self, "_series_truncated", False)
        object.__setattr__(self, "_series_first_start_ns", None)
        object.__setattr__(self, "_series_cum_bytes", 0)
        object.__setattr__(self, "_c6_micro_pending", None)
        object.__setattr__(self, "_c6_micro_records", [])
        object.__setattr__(self, "_c6_micro_disabled", False)
        object.__setattr__(self, "_c6_micro_sample_set", None)
        object.__setattr__(self, "_c6_ring_fallback", [])

    def __getattr__(self, name):
        if name == "get_tensor":
            return lambda k: self._proxy_get_tensor(k)
        return getattr(self._wrapped, name)

    def _proxy_get_tensor(self, k):
        lane2 = _ACTIVE_LANE_TRACE.get()
        _start_ns = 0
        if lane2 is not None and lane2._lane == "UNET" and (_DIAGNOSTIC_FLAG or _C6_PROBE_MODE == "probe"):
            _start_ns = time.monotonic_ns()
        # ── Batch C6 I-3 micro-overlap probe (probe mode only; guarded) ──
        # A sample point leaves a pending async H2D copy; the NEXT
        # materialization finalizes it.  The extra sync at sample points
        # perturbs I-1 wall timing at those ordinals — accepted.
        if _C6_PROBE_MODE == "probe" and not self._c6_micro_disabled:
            try:
                if self._c6_micro_pending is not None:
                    self._c6_micro_pending["t_next_start"] = time.monotonic_ns()
            except Exception:
                pass
        tensor = self._orig_gt(k)
        if lane2 is not None and lane2._lane == "UNET" and (_DIAGNOSTIC_FLAG or _C6_PROBE_MODE == "probe") and _start_ns:
            self._count_agg[0] += 1
            try:
                self._bytes_agg[0] += tensor.numel() * tensor.element_size()
            except Exception:
                pass
        if (
            _C6_PROBE_MODE == "probe"
            and lane2 is not None
            and lane2._lane == "UNET"
            and (_DIAGNOSTIC_FLAG or _C6_PROBE_MODE == "probe")
            and _start_ns
            and self._series is not None
        ):
            try:
                self._record_series_entry(k, tensor, _start_ns)
            except Exception:
                pass
        if _C6_PROBE_MODE == "probe":
            try:
                self._c6_micro_after_materialize(lane2, k, tensor)
            except Exception:
                self._c6_micro_disable_cleanup()
            try:
                self._c6_ring_collect(k, tensor)
            except Exception:
                pass
        return tensor

    def _c6_ring_collect(self, k, tensor):
        """Collect bounded ring-probe source references (probe mode).  Only
        the first read populates _C6_RING_SOURCES; large mmap-backed tensors
        are held briefly (refs only, no allocation) and released by the
        probe's finally."""
        try:
            _nbytes = int(tensor.numel()) * int(tensor.element_size())
        except Exception:
            return
        _entry: dict[str, Any] = {
            "ordinal": max(0, self._count_agg[0] - 1),
            "key": k,
            "nbytes": _nbytes,
            "data_ptr": None,
            "storage_offset": None,
            "is_view": None,
            "tensor": tensor,
        }
        try:
            _entry["data_ptr"] = int(tensor.data_ptr())
        except Exception:
            pass
        try:
            _entry["storage_offset"] = int(tensor.storage_offset())
        except Exception:
            pass
        try:
            _entry["is_view"] = bool(tensor._base is not None)
        except Exception:
            pass
        _holder = globals().get("_C6_RING_SOURCES")
        if _holder is None:
            global _C6_RING_SOURCES
            _C6_RING_SOURCES = []
            _holder = _C6_RING_SOURCES
        if _nbytes >= 60_000_000:
            if len(_holder) < 12:
                _holder.append(_entry)
        elif _nbytes >= 30_000_000:
            _fb = self._c6_ring_fallback
            _fb.append((_nbytes, _entry))
            _fb.sort(key=lambda _t: _t[0], reverse=True)
            del _fb[12:]

    def _c6_ring_finalize_collection(self):
        """Read-end fallback: when fewer than 8 large tensors were found,
        top up from the 30 MB+ candidates kept on the proxy."""
        _holder = globals().get("_C6_RING_SOURCES")
        if _holder is None:
            return
        if len(_holder) >= 8:
            return
        for _nbytes, _entry in self._c6_ring_fallback:
            if len(_holder) >= 12:
                break
            _holder.append(_entry)

    def _c6_micro_after_materialize(self, lane2, k, tensor):
        if self._c6_micro_disabled:
            return
        if not self._c6_micro_enabled(lane2):
            return
        if self._c6_micro_pending is not None:
            try:
                self._c6_micro_pending["t_next_end"] = time.monotonic_ns()
            except Exception:
                pass
            self._c6_micro_finalize(no_next=False)
            return
        _ordinal = max(0, self._count_agg[0] - 1)
        if _ordinal in self._c6_micro_sample_set:
            self._c6_micro_sample(lane2, k, tensor, _ordinal)

    def _c6_micro_enabled(self, lane2):
        if self._c6_micro_disabled:
            return False
        if self._c6_micro_sample_set is None:
            if _C6_PROBE_MODE != "probe" or lane2 is None or lane2._lane != "UNET":
                object.__setattr__(self, "_c6_micro_disabled", True)
                return False
            try:
                import torch as _torch_me
                if not _torch_me.cuda.is_available():
                    object.__setattr__(self, "_c6_micro_disabled", True)
                    return False
            except Exception:
                object.__setattr__(self, "_c6_micro_disabled", True)
                return False
            object.__setattr__(self, "_c6_micro_sample_set", set(_C6_MICRO_SAMPLE_ORDINALS))
        return True

    def _c6_micro_sample(self, lane2, k, tensor, ordinal):
        import torch as _torch_s
        _p: dict[str, Any] = {
            "ordinal": ordinal,
            "key": k,
            "bytes": 0,
            "data_ptr": None,
            "storage_offset": None,
            "is_view": None,
            "minflt_before": None,
            "minflt_after": None,
            "t_issue0": None,
            "t_issue1": None,
            "t_next_start": None,
            "t_next_end": None,
        }
        try:
            _p["bytes"] = int(tensor.numel()) * int(tensor.element_size())
        except Exception:
            pass
        try:
            _p["data_ptr"] = int(tensor.data_ptr())
        except Exception:
            pass
        try:
            _p["storage_offset"] = int(tensor.storage_offset())
        except Exception:
            pass
        try:
            _p["is_view"] = bool(tensor._base is not None)
        except Exception:
            pass
        try:
            import resource as _res_s
            _p["minflt_before"] = int(_res_s.getrusage(_res_s.RUSAGE_SELF).ru_minflt)
        except Exception:
            _p["minflt_before"] = None
        _dest = _torch_s.empty(list(tensor.shape), dtype=tensor.dtype, device="cuda")
        _ev_start = _torch_s.cuda.Event(enable_timing=True)
        _ev_start.record()
        _t0 = time.monotonic_ns()
        _dest.copy_(tensor, non_blocking=True)
        _t1 = time.monotonic_ns()
        _ev_end = _torch_s.cuda.Event(enable_timing=True)
        _ev_end.record()
        _p["dest"] = _dest
        _p["ev_start"] = _ev_start
        _p["ev_end"] = _ev_end
        _p["t_issue0"] = _t0
        _p["t_issue1"] = _t1
        try:
            import resource as _res_s2
            _p["minflt_after"] = int(_res_s2.getrusage(_res_s2.RUSAGE_SELF).ru_minflt)
        except Exception:
            _p["minflt_after"] = None
        object.__setattr__(self, "_c6_micro_pending", _p)

    def _c6_micro_finalize(self, no_next=False):
        _p = self._c6_micro_pending
        if _p is None:
            return
        try:
            import torch as _torch_f
            _torch_f.cuda.synchronize()
            _elapsed_ms = float(_p["ev_start"].elapsed_time(_p["ev_end"]))
            _ev_ns = _elapsed_ms * 1_000_000.0
            _t0 = _p["t_issue0"]
            _rec: dict[str, Any] = {
                "ordinal": _p["ordinal"],
                "key": _p["key"],
                "bytes": _p["bytes"],
                "data_ptr": _p["data_ptr"],
                "storage_offset": _p["storage_offset"],
                "is_view": _p["is_view"],
                "copy_issue_host_ms": round((_p["t_issue1"] - _t0) / 1_000_000, 4),
                "h2d_cuda_ms": round(_elapsed_ms, 4),
                "minflt_delta": max(0, int(_p.get("minflt_after") or 0) - int(_p.get("minflt_before") or 0)),
            }
            if no_next:
                _rec.update({
                    "next_mat_start_rel_ms": None,
                    "next_mat_end_rel_ms": None,
                    "next_mat_wall_ms": None,
                    "combined_wall_ms": None,
                    "overlap_direct": None,
                    "overlap_complete": None,
                    "no_next": True,
                })
            else:
                _rec.update({
                    "next_mat_start_rel_ms": round((_p["t_next_start"] - _t0) / 1_000_000, 4),
                    "next_mat_end_rel_ms": round((_p["t_next_end"] - _t0) / 1_000_000, 4),
                    "next_mat_wall_ms": round((_p["t_next_end"] - _p["t_next_start"]) / 1_000_000, 4),
                    "combined_wall_ms": round((_p["t_next_end"] - _t0) / 1_000_000, 4),
                    "overlap_direct": bool(_p["t_next_start"] < _t0 + _ev_ns),
                    "overlap_complete": bool(_p["t_next_end"] <= _t0 + _ev_ns + 1_000_000),
                    "no_next": False,
                })
            self._c6_micro_records.append(_rec)
        except Exception:
            pass
        finally:
            try:
                del _p["dest"]
            except Exception:
                pass
            try:
                import torch as _torch_gc
                _torch_gc.cuda.empty_cache()
            except Exception:
                pass
            object.__setattr__(self, "_c6_micro_pending", None)

    def _c6_micro_disable_cleanup(self):
        try:
            _p = self._c6_micro_pending
            if _p is not None:
                try:
                    del _p["dest"]
                except Exception:
                    pass
                object.__setattr__(self, "_c6_micro_pending", None)
        except Exception:
            pass
        object.__setattr__(self, "_c6_micro_disabled", True)

    def _record_series_entry(self, k, tensor, start_ns):
        _end_ns = time.monotonic_ns()
        if self._series_first_start_ns is None:
            object.__setattr__(self, "_series_first_start_ns", start_ns)
        _entry = {
            "ordinal": len(self._series),
            "key": k,
            "t_start_ms": round((start_ns - self._series_first_start_ns) / 1_000_000, 4),
            "t_end_ms": round((_end_ns - self._series_first_start_ns) / 1_000_000, 4),
            "wall_ms": round((_end_ns - start_ns) / 1_000_000, 4),
        }
        try:
            _entry["shape"] = list(tensor.shape)
        except Exception:
            pass
        try:
            _entry["dtype"] = str(tensor.dtype)
        except Exception:
            pass
        try:
            _entry["numel"] = int(tensor.numel())
        except Exception:
            pass
        try:
            _entry["nbytes"] = int(tensor.numel()) * int(tensor.element_size())
        except Exception:
            pass
        try:
            _entry["data_ptr"] = int(tensor.data_ptr())
        except Exception:
            pass
        try:
            _entry["storage_offset"] = int(tensor.storage_offset())
        except Exception:
            pass
        try:
            _entry["is_view"] = bool(tensor._base is not None)
        except Exception:
            pass
        try:
            _entry["storage_nbytes"] = int(tensor.untyped_storage().nbytes())
        except Exception:
            pass
        self._series_cum_bytes += int(_entry.get("nbytes", 0))
        _entry["cum_bytes"] = self._series_cum_bytes
        if len(self._series) < self._series_cap:
            self._series.append(_entry)
        else:
            object.__setattr__(self, "_series_truncated", True)

    def __enter__(self):
        try:
            self._wrapped.__enter__()
        except AttributeError:
            pass
        return self

    def __exit__(self, *exc):
        lane2 = _ACTIVE_LANE_TRACE.get()
        if lane2 is not None:
            lane2._trace.emit("unet_tensor_materialize_aggregated", phase="restore", metadata={
                "tensor_count": self._count_agg[0],
                "total_bytes": self._bytes_agg[0],
            })
            if _C6_PROBE_MODE == "probe" and self._series is not None and len(self._series) > 0:
                try:
                    self._emit_c6_probe_series(lane2)
                except Exception:
                    pass
            if _C6_PROBE_MODE == "probe":
                try:
                    self._c6_ring_finalize_collection()
                except Exception:
                    pass
            if _C6_PROBE_MODE == "probe":
                try:
                    if self._c6_micro_pending is not None:
                        self._c6_micro_finalize(no_next=True)
                    if self._c6_micro_records:
                        _classifier = _c6_classify_overlap(self._c6_micro_records)
                        try:
                            lane2._trace.emit("unet_i3_micro_overlap", phase="restore", metadata={
                                "samples": _c6_json_safe(list(self._c6_micro_records)),
                                "classifier": _c6_json_safe(_classifier),
                            })
                        except Exception as _exc:
                            print(
                                f"[v2.c6_probe] micro emit_error={type(_exc).__name__}",
                                flush=True,
                            )
                        print(
                            f"[v2.c6_probe] micro_overlap samples={len(self._c6_micro_records)} "
                            f"class={_classifier.get('class')} "
                            f"eff_mean={_classifier.get('mean_eff')} "
                            f"direct={_classifier.get('direct_fraction')} "
                            f"complete={_classifier.get('complete_fraction')}",
                            flush=True,
                        )
                except Exception:
                    pass
        return self._wrapped.__exit__(*exc) if hasattr(self._wrapped, "__exit__") else None

    def _emit_c6_probe_series(self, lane2):
        import sys as _sys_px
        _series = self._series
        _total_bytes = self._bytes_agg[0]
        _read_wall_ms = float(_series[-1].get("t_end_ms", 0.0))
        _comfy_utils_mmap = "unavailable"
        try:
            import comfy.utils as _cu_px
            _comfy_utils_mmap = str(getattr(_cu_px, "DISABLE_MMAP", "unavailable"))
        except Exception:
            pass
        lane2._trace.emit("unet_read_h2d_pipeline_probe", phase="restore", metadata={
            "mode": "probe",
            "kind": "tensor_materialize_series",
            "tensor_count": self._count_agg[0],
            "total_bytes": _total_bytes,
            "series_count": len(_series),
            "series_truncated": bool(self._series_truncated),
            "read_wall_ms": round(_read_wall_ms, 4),
            "comfy_utils_disable_mmap": _comfy_utils_mmap,
            "platform": _sys_px.platform,
            "series": list(_series),
        })
        _p25, _p50, _p75, _p100 = _c6_probe_series_percentiles(_series, _total_bytes)
        _largest10 = sorted(
            (
                (str(_e.get("key", ""))[:40], round(float(_e.get("wall_ms", 0.0)), 3))
                for _e in _series
            ),
            key=lambda _t: _t[1],
            reverse=True,
        )[:10]
        print(
            f"[v2.c6_probe] read tensors={self._count_agg[0]} bytes={_total_bytes} "
            f"wall={round(_read_wall_ms, 4)}ms p25={_p25} p50={_p50} p75={_p75} "
            f"p100={_p100} largest10={_largest10}",
            flush=True,
        )

    def keys(self):
        return self._wrapped.keys()


def _make_safetensors_open_wrapper(original: Callable[..., Any]) -> Callable[..., Any]:
    """Wrap ``safetensors.safe_open`` to emit open/parse/materialize stages.

    Uses a reentrancy guard and thread-local path filtering.  Emits:
    - ``unet_safetensors_open_start/end`` for the ``safe_open()`` call itself
    - ``unet_safetensors_parse_start/end`` for the ``f.keys()`` header parse
    - ``unet_tensor_materialize_start/end`` around ``f.get_tensor()`` calls
    When the safetensors library does not expose separable boundaries, emits
    ``unet_safetensors_load_combined_start/end`` with ``stage_split_available=false``.
    """

    @functools.wraps(original)
    def wrapper(file, framework="pt", device="cpu", **kwargs):
        global _C6_PROBE_FILE_PATH
        before = _deep_st_depth.get()
        _deep_st_depth.set(before + 1)
        lane = _ACTIVE_LANE_TRACE.get()
        target_path = _DEEP_TARGET_PATH.get()
        _outer = (before == 0)
        # Probe mode relaxes the path filter: the execution-phase UNET lane
        # worker never populates _DEEP_TARGET_PATH, so probe eligibility no
        # longer depends on it (deep-diag stays byte-identical).
        _eligible = (_outer and (_DIAGNOSTIC_FLAG or _C6_PROBE_MODE == "probe")
                     and lane is not None and lane._lane == "UNET"
                     and ((target_path and isinstance(file, str) and target_path in file)
                          or _C6_PROBE_MODE == "probe"))
        if _eligible and _C6_PROBE_MODE == "probe":
            try:
                _C6_PROBE_FILE_PATH = file if isinstance(file, str) else ""
            except Exception:
                pass
        _result = None
        if _eligible:
            lane._trace.emit("unet_safetensors_open_start", phase="restore",
                             metadata={"path": str(file)[-80:]})
        try:
            _result = original(file, framework=framework, device=device, **kwargs)
            if _eligible and _outer:
                lane._trace.emit("unet_safetensors_open_end", phase="restore")
                # Check if the safetensors object has separable keys()
                _stage_split = (_result is not None
                                and callable(getattr(_result, "keys", None))
                                and callable(getattr(_result, "get_tensor", None)))
                if _stage_split:
                    lane._trace.emit("unet_safetensors_parse_start", phase="restore")
                    try:
                        _keys = list(_result.keys())
                        lane._trace.emit("unet_safetensors_parse_end", phase="restore",
                                         metadata={"tensor_count": len(_keys),
                                                   "stage_split_available": True})
                    except Exception:
                        lane._trace.emit("unet_safetensors_parse_end", phase="restore",
                                         metadata={"stage_split_available": False})
                    # Return a delegating proxy instead of mutating the native
                    # safe_open object (C-extension — attributes are read-only).
                    _tensor_count_agg = [0]
                    _tensor_bytes_agg = [0]
                    _orig_get_tensor = _result.get_tensor
                    _tensor_series = [] if _C6_PROBE_MODE == "probe" else None

                    _result = _SafeOpenProxy(_result, _orig_get_tensor,
                                             _tensor_count_agg, _tensor_bytes_agg,
                                             series=_tensor_series)
                else:
                    lane._trace.emit("unet_safetensors_load_combined_start", phase="restore",
                                     metadata={"stage_split_available": False})
                    lane._trace.emit("unet_safetensors_load_combined_end", phase="restore")
            return _result
        finally:
            after = _deep_st_depth.get()
            _deep_st_depth.set(after - 1)
    wrapper._comfy_modal_deep_st_wrapper = True
    return wrapper


def _make_torch_load_wrapper(original: Callable[..., Any]) -> Callable[..., Any]:
    """Wrap ``torch.load`` to emit combined load event for non-safetensors files.

    Thread-local path filtering.  Emits ``unet_load_torch_file_start/end``.
    """

    @functools.wraps(original)
    def wrapper(f, map_location=None, weights_only=True, **kwargs):
        before = _deep_tl_depth.get()
        _deep_tl_depth.set(before + 1)
        lane = _ACTIVE_LANE_TRACE.get()
        target_path = _DEEP_TARGET_PATH.get()
        _outer = (before == 0)
        _file_str = str(getattr(f, "name", f)) if not isinstance(f, str) else str(f)
        _eligible = (_outer and _DIAGNOSTIC_FLAG and lane is not None
                     and lane._lane == "UNET" and target_path
                     and target_path in _file_str)
        if _eligible:
            lane._trace.emit("unet_load_torch_file_start", phase="restore",
                             metadata={"path": _file_str[-80:]})
        try:
            return original(f, map_location=map_location, weights_only=weights_only, **kwargs)
        finally:
            after = _deep_tl_depth.get()
            _deep_tl_depth.set(after - 1)
            if _eligible and _outer:
                lane._trace.emit("unet_load_torch_file_end", phase="restore")
    wrapper._comfy_modal_deep_tl_wrapper = True
    return wrapper


def _make_clip_load_wrapper(original):
    import functools as _ft
    @_ft.wraps(original)
    def wrapper(*args, **kwargs):
        before = _clip_depth.get()
        _clip_depth.set(before + 1)
        lane = _ACTIVE_LANE_TRACE.get()
        emit = (before == 0 and lane is not None and lane._lane == "CLIP")
        _outer_start_ns = time.monotonic_ns() if emit else 0
        _prior_children = _clip_cpu_prepare_children.get()
        _result = None
        if emit:
            _clip_cpu_prepare_children.set([])
            lane._trace.emit("clip_load_call_start", phase="restore", metadata={
                "lane": lane._lane,
            })
        try:
            _result = original(*args, **kwargs)
            return _result
        finally:
            after = _clip_depth.get()
            _clip_depth.set(after - 1)
            if emit:
                _outer_dur_ms = round((time.monotonic_ns() - _outer_start_ns) / 1_000_000, 3)
                _children = _clip_cpu_prepare_children.get() or []
                _children_total = round(sum(c[1] for c in _children), 3)
                # Signed residual — allow negative when children exceed total
                _residual = round(_outer_dur_ms - _children_total, 3)
                # Determine status from read count match
                _mismatch = (lane._actual_read_count != lane.expected_read_count
                             if lane.expected_read_count > 0 else False)
                _end_status = "read_count_mismatch" if _mismatch else "ok"
                if _children_total > _outer_dur_ms:
                    _end_status = "overlap_error"
                # ── Cache publication observation ────────────────
                if _result is not None:
                    _patcher = getattr(_result, "patcher", None)
                    if _patcher is not None:
                        _cpi = getattr(_patcher, "cached_patcher_init", None)
                        if _cpi is not None:
                            lane._trace.emit("clip_cache_publish", phase="restore", metadata={
                                "cache_type": "cached_patcher_init",
                                "clip_cpu_prepare_total_ms": _outer_dur_ms,
                            })
                _clip_cpu_prepare_children.set(_prior_children)
                # clip_file_read_total_ms from per-lane read-duration accumulator.
                _clip_read_raw = lane._clip_read_total_ms
                _clip_file_read = round(_clip_read_raw, 3) if _clip_read_raw else None
                _clip_post_read_cpu = (round(max(0.0, _outer_dur_ms - _clip_read_raw), 3)
                                       if _clip_read_raw else None)
                lane._trace.emit("clip_load_call_end", phase="restore", metadata={
                    "lane": lane._lane,
                    "clip_load_call_total_ms": _outer_dur_ms,
                    "clip_file_read_total_ms": _clip_file_read,
                    "clip_post_read_cpu_total_ms": _clip_post_read_cpu,
                    "status": _end_status,
                })
                # post_read_total is None when _on_read_completed never fired
                _post_read_total = _outer_dur_ms if lane._cpu_prepare_started else None
                lane._trace.emit("clip_cpu_prepare_end", phase="restore", metadata={
                    "lane": lane._lane,
                    "clip_cpu_prepare_total_ms": _post_read_total,
                    "children": [(name, dur) for name, dur in _children],
                    "clip_cpu_prepare_measured_children_ms": _children_total,
                    "clip_cpu_prepare_residual_ms": _residual,
                    "clip_file_read_total_ms": _clip_file_read,
                    "status": _end_status,
                })
                # Extract named children from trace events for the summary
                _evts = lane._trace.events
                _named_map: dict[str, float] = {}
                for _ev in _evts:
                    _en = _ev.name
                    _meta = getattr(_ev, "metadata", None) or {}
                    _dur = _meta.get("duration_ms")
                    if _dur is None:
                        continue
                    # Match clip_*_end events, handling double prefix
                    if _en.endswith("_end") and "clip_" in _en:
                        # Extract base name after clip_ prefix(es)
                        _base = _en.replace("clip_clip_", "clip_", 1)
                        if _base.startswith("clip_"):
                            _short = _base[len("clip_"):-len("_end")]
                        else:
                            _short = _base[:-len("_end")]
                        _named_map[_short] = (_named_map.get(_short, 0) or 0) + _dur
                    # Also match clip_clip_ double-prefix (already handled above)
                # Map to named fields
                _known_fields = {
                    "load_text_encoder_state_dicts": "load_text_encoder_state_dicts_ms",
                    "detect_te_model": "detect_te_model_ms",
                    "text_transformers_convert": "state_dict_conversion_ms",
                    "clip_text_transformers_convert": "state_dict_conversion_ms",
                    "constructor": "clip_constructor_ms",
                    "model_patcher_constructor": "model_patcher_ms",
                    "cond_stage_model_init": "cond_stage_model_init_ms",
                    "tokenizer_init": "tokenizer_init_ms",
                    "load_sd_weights": "load_sd_weights_ms",
                }
                _s = lambda k: _named_map.get(k)
                # double-prefix variant also maps to state_dict_conversion
                _sd_contrib = 0.0
                for _k in ("text_transformers_convert", "clip_text_transformers_convert", "convert_old_quants"):
                    _sd_contrib += _named_map.get(_k, 0) or 0
                if _sd_contrib:
                    _named_map["state_dict_conversion"] = _sd_contrib
                # ── Compute constructor residual ────────────────────
                _ctor_ms = _named_map.get("constructor")
                _csm_init = _named_map.get("cond_stage_model_init")
                _tok_init = _named_map.get("tokenizer_init")
                _lsd_w = _named_map.get("load_sd_weights")
                _mp_ms = _named_map.get("model_patcher_constructor")
                _ctor_residual: float | None = None
                if _ctor_ms is not None:
                    _known_ctor = [v for v in (_csm_init, _tok_init, _lsd_w, _mp_ms) if v is not None]
                    _ctor_residual = round(_ctor_ms - sum(_known_ctor), 3) if _known_ctor else None
                _emit_clip_cpu_children_summary(
                    post_read_total_ms=_post_read_total,
                    file_read_total_ms=_clip_file_read,
                    children=_children,
                    load_text_encoder_state_dicts_ms=_named_map.get("load_text_encoder_state_dicts"),
                    detect_te_model_ms=_named_map.get("detect_te_model"),
                    state_dict_conversion_ms=_named_map.get("state_dict_conversion"),
                    clip_constructor_ms=_named_map.get("constructor"),
                    cond_stage_model_init_ms=_named_map.get("cond_stage_model_init"),
                    tokenizer_init_ms=_named_map.get("tokenizer_init"),
                    load_sd_weights_ms=_named_map.get("load_sd_weights"),
                    model_patcher_ms=_named_map.get("model_patcher_constructor"),
                    constructor_residual_ms=_ctor_residual,
                    cache_publish_ms=_named_map.get("cache_publish"),
                    measured_children_ms=_children_total,
                    residual_ms=_residual,
                    status=_end_status,
                )
    wrapper._comfy_modal_clip_wrapper = True
    return wrapper


def _make_clip_subfn_wrapper(short_name, original, category):
    import functools as _ft
    @_ft.wraps(original)
    def wrapper(*args, **kwargs):
        lane = _ACTIVE_LANE_TRACE.get()
        emit = (lane is not None and lane._lane == "CLIP")
        _fn_start_ns = time.monotonic_ns() if emit else 0
        if emit:
            lane._trace.emit("clip_" + short_name + "_start", phase="restore", metadata={"category": category})
        _before_depth = _clip_subfn_depth.get()
        _clip_subfn_depth.set(_before_depth + 1)
        try:
            return original(*args, **kwargs)
        finally:
            _after_depth = _clip_subfn_depth.get()
            _clip_subfn_depth.set(_after_depth - 1)
            if emit:
                _dur_ms = round((time.monotonic_ns() - _fn_start_ns) / 1_000_000, 3)
                lane._trace.emit("clip_" + short_name + "_end", phase="restore", metadata={
                    "category": category, "duration_ms": _dur_ms})
                # Only direct children (depth=0 before call) contribute to measured sum
                if _before_depth == 0:
                    _children = _clip_cpu_prepare_children.get()
                    if _children is not None:
                        _children.append((short_name, _dur_ms))
    setattr(wrapper, _SENTINEL_CLIP_SUBFN, True)
    return wrapper


class _ClipTargetProxy:
    """Shallow proxy around a CLIP target that intercepts ``.clip`` and
    ``.tokenizer`` attribute access, wrapping the retrieved callables with
    timing instrumentation.  All other attribute access passes through to
    the original target unchanged, preserving behavior.

    Only created when a CLIP constructor wrapper is active and the lane
    is CLIP.  A non-functional proxy (``copy.copy`` unavailable) falls
    back to the original target without failing the load.
    """

    def __init__(self, original_target: Any, lane_trace: Any) -> None:
        object.__setattr__(self, "_original_target", original_target)
        # Accept ModelLaneTrace or RuntimeTrace; extract _trace for emit()
        object.__setattr__(self, "_trace",
                           getattr(lane_trace, "_trace", lane_trace))

    def __getattr__(self, name: str) -> Any:
        if name == "clip":
            return self._wrap_clip()
        elif name == "tokenizer":
            return self._wrap_tokenizer()
        return getattr(self._original_target, name)

    def _wrap_clip(self) -> Any:
        orig_clip = self._original_target.clip
        trace = self._trace

        @functools.wraps(orig_clip)
        def _timed_clip(*args: Any, **kwargs: Any) -> Any:
            trace.emit("clip_cond_stage_model_init_start", phase="restore")
            _start_ns = time.monotonic_ns()
            try:
                return orig_clip(*args, **kwargs)
            finally:
                _dur = round((time.monotonic_ns() - _start_ns) / 1_000_000, 3)
                trace.emit("clip_cond_stage_model_init_end", phase="restore",
                           metadata={"duration_ms": _dur})
        return _timed_clip

    def _wrap_tokenizer(self) -> Any:
        orig_tokenizer = self._original_target.tokenizer
        trace = self._trace

        @functools.wraps(orig_tokenizer)
        def _timed_tokenizer(*args: Any, **kwargs: Any) -> Any:
            trace.emit("clip_tokenizer_init_start", phase="restore")
            _start_ns = time.monotonic_ns()
            try:
                return orig_tokenizer(*args, **kwargs)
            finally:
                _dur = round((time.monotonic_ns() - _start_ns) / 1_000_000, 3)
                trace.emit("clip_tokenizer_init_end", phase="restore",
                           metadata={"duration_ms": _dur})
        return _timed_tokenizer


def _make_clip_load_sd_wrapper(original: Callable[..., Any]) -> Callable[..., Any]:
    """Wrap ``comfy.sd.CLIP.load_sd`` with timing instrumentation.

    Only emits ``clip_load_sd_weights_start/end`` events when a CLIP
    constructor wrapper is active (``_clip_constructor_depth > 0``) AND
    the active lane is CLIP.  Outside the constructor, the wrapper
    transparently forwards with zero overhead.

    Sentinel-guarded for idempotent global install.
    """
    import functools as _ft

    @_ft.wraps(original)
    def wrapper(self: Any, sd: Any, full_model: bool = False) -> Any:
        lane = _ACTIVE_LANE_TRACE.get()
        emit = (lane is not None and lane._lane == "CLIP"
                and _clip_constructor_depth.get() > 0)
        _start_ns = time.monotonic_ns() if emit else 0
        if emit:
            lane._trace.emit("clip_load_sd_weights_start", phase="restore")
        try:
            return original(self, sd, full_model=full_model)
        finally:
            if emit:
                _dur = round((time.monotonic_ns() - _start_ns) / 1_000_000, 3)
                lane._trace.emit("clip_load_sd_weights_end", phase="restore",
                                 metadata={"duration_ms": _dur})
    setattr(wrapper, _SENTINEL_CLIP_LOAD_SD, True)
    return wrapper


def _make_clip_constructor_wrapper(original):
    """Wrap ``comfy.sd.CLIP.__init__`` to emit ``clip_constructor_start/end``
    and proxy ``target.clip`` / ``target.tokenizer`` + ``self.load_sd`` for
    truthful live child attribution (``clip_cond_stage_model_init``,
    ``clip_tokenizer_init``, ``clip_load_sd_weights``).

    Only active when ``_ACTIVE_LANE_TRACE`` is set AND the current lane
    is ``CLIP``.  Reentrancy-safe via ``_clip_constructor_depth``.
    Emitted spans are NOT recorded into ``_clip_cpu_prepare_children`` —
    they are nested inside ``load_text_encoder_state_dicts`` which is the
    direct measured owner.
    """
    import functools as _ft

    @_ft.wraps(original)
    def wrapper(self, *args: Any, **kwargs: Any) -> None:
        before = _clip_constructor_depth.get()
        _clip_constructor_depth.set(before + 1)
        lane = _ACTIVE_LANE_TRACE.get()
        emit = (before == 0 and lane is not None and lane._lane == "CLIP")
        _fn_start_ns = time.monotonic_ns() if emit else 0

        if emit:
            # ── Proxy target.clip / target.tokenizer ──────────────
            _original_target = args[0] if args else kwargs.get("target")
            if _original_target is not None:
                try:
                    import copy as _copy
                    _proxy = _ClipTargetProxy(_original_target, lane)
                    if args:
                        _new_args = list(args)
                        _new_args[0] = _proxy
                        args = tuple(_new_args)
                    else:
                        kwargs = dict(kwargs)
                        kwargs["target"] = _proxy
                except Exception:
                    pass  # Fall back to original target without failing
            lane._trace.emit("clip_constructor_start", phase="restore")
        try:
            return original(self, *args, **kwargs)
        finally:
            after = _clip_constructor_depth.get()
            _clip_constructor_depth.set(after - 1)
            if emit:
                _dur_ms = round((time.monotonic_ns() - _fn_start_ns) / 1_000_000, 3)
                lane._trace.emit("clip_constructor_end", phase="restore", metadata={
                    "duration_ms": _dur_ms,
                })
                # NOT recorded into _clip_cpu_prepare_children — nested inside
                # load_text_encoder_state_dicts which is the direct measured owner.
    setattr(wrapper, _SENTINEL_CLIP_CONSTRUCTOR, True)
    return wrapper


# ── Shared convert_old_quants wrapper ───────────────────────────────
# Lane-aware wrapper installed once for comfy.utils.convert_old_quants.
# Emits either clip_convert_old_quants_* or unet_convert_old_quants_*
# depending on the active lane.  Children are recorded into the
# appropriate per-lane list for residual/non-overlap computation.

_shared_convert_old_quants_installed: bool = False


def _make_convert_old_quants_wrapper(original):
    import functools as _ft

    @_ft.wraps(original)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        lane = _ACTIVE_LANE_TRACE.get()
        if lane is None:
            return original(*args, **kwargs)
        _fn_start_ns = time.monotonic_ns()
        if lane._lane == "CLIP":
            lane._trace.emit("clip_convert_old_quants_start", phase="restore", metadata={"category": "utils"})
        elif lane._lane == "UNET":
            lane._trace.emit("unet_convert_old_quants_start", phase="restore", metadata={"category": "utils"})
        try:
            return original(*args, **kwargs)
        finally:
            _dur_ms = round((time.monotonic_ns() - _fn_start_ns) / 1_000_000, 3)
            if lane._lane == "CLIP":
                lane._trace.emit("clip_convert_old_quants_end", phase="restore", metadata={
                    "category": "utils", "duration_ms": _dur_ms})
                # Only direct children (depth=0) contribute to measured sum
                if _clip_subfn_depth.get() == 0:
                    _children = _clip_cpu_prepare_children.get()
                    if _children is not None:
                        _children.append(("convert_old_quants", _dur_ms))
            elif lane._lane == "UNET":
                lane._trace.emit("unet_convert_old_quants_end", phase="restore", metadata={
                    "category": "utils", "duration_ms": _dur_ms})
                # Only direct children (nesting depth 0) contribute to measured sum
                if _unet_subfn_nesting_depth.get() == 0:
                    _children = _child_durations.get()
                    if _children is not None:
                        _children.append(("convert_old_quants", _dur_ms))
    setattr(wrapper, _SENTINEL_SHARED_COQ, True)
    return wrapper


def _install_shared_convert_old_quants_wrapper() -> str:
    """Install lane-aware wrapper on comfy.utils.convert_old_quants once."""
    global _shared_convert_old_quants_installed
    if _shared_convert_old_quants_installed:
        return "already_installed"
    mod = _get_live_module("comfy.utils")
    if mod is None:
        return "unavailable"
    original = getattr(mod, "convert_old_quants", None)
    if not callable(original):
        return "unavailable"
    if getattr(original, _SENTINEL_SHARED_COQ, False):
        _shared_convert_old_quants_installed = True
        return "already_installed"
    with _wrappers_lock:
        if _shared_convert_old_quants_installed:
            return "already_installed"
        if getattr(mod.convert_old_quants, _SENTINEL_SHARED_COQ, False):
            _shared_convert_old_quants_installed = True
            return "already_installed"
        mod.convert_old_quants = _make_convert_old_quants_wrapper(mod.convert_old_quants)
        _shared_convert_old_quants_installed = True
    return "installed"


# ── V2 native fast-disk UNET loader (COMFYMODAL_V2_NATIVE_FAST_DISK_UNET) ─
# Opt-in, default OFF: when inactive the UNET load path is exactly legacy.
# When active, the existing live wrappers (model_config.get_model,
# nn.Module.to, the ModelPatcher constructor, and the per-instance
# load_model_weights wrapper) cooperate to defer exactly ONE eligible first
# UNET ``model.to(cuda)`` call — the call native
# ``comfy.sd.load_diffusion_model_state_dict`` performs between ModelPatcher
# construction and ``load_model_weights`` (``model.to(offload_device)`` with
# offload == load == CUDA under HIGH_VRAM).  The deferred REAL original
# ``model.to`` is replayed AFTER ``load_model_weights(assign=True)`` has
# BOUND the disk state-dict tensors directly onto the constructed parameters
# (no intermediate CPU copy), so the model makes a single pass to CUDA.
#
# Fast ordering (all guards green at load time):
#   native model construction -> native plain ModelPatcher ->
#   original load_model_weights(assign=True) [bind] ->
#   exactly one REAL original model.to(target) -> continue native path.
# Any failed guard replays the deferred original ``model.to(target)`` BEFORE
# invoking the original ``load_model_weights`` with its ORIGINAL assign
# value, preserving the legacy order and exceptions exactly.  The deferral
# record is removed on every success/failure path; no CLIP/VAE/other model
# or subsequent ``.to`` call is ever affected.  ModelPatcher fields and
# bookkeeping are never altered.

_NATIVE_FAST_DISK_UNET: bool = env_flag("COMFYMODAL_V2_NATIVE_FAST_DISK_UNET")

_FAST_DISK_UNET_LOCK: RLock = RLock()
_FAST_DISK_UNET_DEFERRALS: dict[int, dict[str, Any]] = {}
_FAST_DISK_UNET_DEFERRALS_MAX = 16

# Event names for the fast-disk loader — unambiguous, distinct from the
# existing unet_model_to_* / unet_load_model_weights_* ownership.
_EVENT_FAST_DISK_DEFER = "unet_fast_disk_defer"
_EVENT_FAST_DISK_SKIP = "unet_fast_disk_skip"
_EVENT_FAST_DISK_BIND_START = "unet_fast_disk_bind_start"
_EVENT_FAST_DISK_BIND_END = "unet_fast_disk_bind_end"
_EVENT_FAST_DISK_TO_START = "unet_fast_disk_to_start"
_EVENT_FAST_DISK_TO_END = "unet_fast_disk_to_end"
_EVENT_FAST_DISK_COMPLETE = "unet_fast_disk_complete"


def _fast_disk_trace(lane_trace: Any) -> Any:
    try:
        return getattr(lane_trace, "_trace", None)
    except Exception:
        return None


def _fast_disk_device_key(dev: Any) -> tuple[str, int] | None:
    """Normalize a device to ``(type, index)`` (cuda == cuda:0; a bare cuda
    index defaults to 0 so it can never mismatch cuda:0 falsely)."""
    try:
        import torch as _torch_dk
        if dev is None:
            return None
        d = dev if isinstance(dev, _torch_dk.device) else _torch_dk.device(str(dev))
        _index = d.index
        if _index is None:
            _index = 0
        return (d.type, _index)
    except Exception:
        return None


def _fast_disk_high_vram() -> bool:
    """True when ComfyUI's live VRAM state is HIGH_VRAM.  Reads the live
    module via ``sys.modules`` (never a fresh import) so an injected/test
    module is always honored.  Never raises."""
    try:
        import sys as _sys_fd
        _mm_fd = _sys_fd.modules.get("comfy.model_management")
        if _mm_fd is None:
            return False
        _vs = getattr(_mm_fd, "vram_state", None)
        _high = getattr(_mm_fd, "VRAMState", None)
        if _vs is not None and _high is not None:
            return bool(_vs == _high.HIGH_VRAM)
        _fn = getattr(_mm_fd, "unet_offload_device", None)
        if callable(_fn):
            try:
                _dev = _fn()
                import torch as _torch_ov
                if isinstance(_dev, _torch_ov.device):
                    return _dev.type != "cpu"
            except Exception:
                pass
    except Exception:
        pass
    return False


def _fast_disk_torch_future_enabled() -> bool:
    """True when torch swap/overwrite module-params-on-conversion is enabled."""
    try:
        import torch.__future__ as _tf
        for _name in (
            "get_swap_module_params_on_conversion",
            "get_overwrite_module_params_on_conversion",
        ):
            _fn = getattr(_tf, _name, None)
            if callable(_fn):
                try:
                    if bool(_fn()):
                        return True
                except Exception:
                    pass
    except Exception:
        pass
    return False


def _fast_disk_model_is_cpu_resident(model: Any) -> bool:
    """True when no parameter/buffer of *model* is on CUDA yet."""
    if model is None:
        return False
    try:
        for _t in model.parameters():
            _dev = str(getattr(getattr(_t, "device", None), "type", "") or "").lower()
            if _dev == "cuda":
                return False
        for _b in model.buffers():
            _dev = str(getattr(getattr(_b, "device", None), "type", "") or "").lower()
            if _dev == "cuda":
                return False
        return True
    except Exception:
        return False


def _fast_disk_model_config_evidence(model_config: Any) -> dict[str, Any]:
    """Snapshot the model-config guards that must be false for the fast path."""
    evidence: dict[str, Any] = {
        "quant_config_present": False,
        "custom_operations_present": False,
        "fp8_optimization": False,
        "force_channels_last": False,
    }
    try:
        evidence["quant_config_present"] = (
            getattr(model_config, "quant_config", None) is not None
        )
    except Exception:
        pass
    try:
        evidence["custom_operations_present"] = (
            getattr(model_config, "custom_operations", None) is not None
        )
    except Exception:
        pass
    try:
        _opts = getattr(model_config, "optimizations", None)
        if isinstance(_opts, Mapping):
            evidence["fp8_optimization"] = bool(_opts.get("fp8", False))
    except Exception:
        pass
    try:
        import sys as _sys_cl
        _mm_cl = _sys_cl.modules.get("comfy.model_management")
        if _mm_cl is not None:
            _fn = getattr(_mm_cl, "force_channels_last", None)
            if callable(_fn):
                evidence["force_channels_last"] = bool(_fn())
    except Exception:
        pass
    return evidence


def _fast_disk_record_model(record: dict[str, Any]) -> Any:
    """Resolve the live model from a deferral record (weakref)."""
    try:
        _ref = record.get("model_ref")
        if _ref is None:
            return record.get("model")
        _m = _ref()
        return _m
    except Exception:
        return None


def _fast_disk_record_for(model: Any) -> dict[str, Any] | None:
    """Live-record lookup keyed by ``id(model)`` with identity verification."""
    if model is None:
        return None
    with _FAST_DISK_UNET_LOCK:
        record = _FAST_DISK_UNET_DEFERRALS.get(id(model))
    if record is None:
        return None
    _live = _fast_disk_record_model(record)
    if _live is None or _live is not model:
        return None
    return record


def _fast_disk_drop_record(model: Any) -> None:
    if model is None:
        return
    with _FAST_DISK_UNET_LOCK:
        _FAST_DISK_UNET_DEFERRALS.pop(id(model), None)


def _fast_disk_new_record(
    model: Any, model_config: Any, lane_trace: Any,
) -> dict[str, Any]:
    """Open a fast-disk deferral window (bounded, weakref-keyed)."""
    import weakref as _weakref
    record: dict[str, Any] = {
        "model_ref": _weakref.ref(model),
        "model_object_id": str(id(model)),
        "status": "constructed",
        "lane_trace": lane_trace,
        "patcher": None,
        "model_config_evidence": _fast_disk_model_config_evidence(model_config),
        "to_args": None,
        "to_kwargs": None,
        "original_to": None,
        "target": None,
        "timings": {
            "get_model_wall_ms": None,
            "ctor_wall_ms": None,
            "bind_wall_ms": None,
            "to_wall_ms": None,
            "to_device_ms": None,
            "to_device_ms_label": "unavailable",
        },
    }
    with _FAST_DISK_UNET_LOCK:
        _FAST_DISK_UNET_DEFERRALS[id(model)] = record
        if len(_FAST_DISK_UNET_DEFERRALS) > _FAST_DISK_UNET_DEFERRALS_MAX:
            _excess = len(_FAST_DISK_UNET_DEFERRALS) - _FAST_DISK_UNET_DEFERRALS_MAX
            for _stale in list(_FAST_DISK_UNET_DEFERRALS.keys())[:_excess]:
                _FAST_DISK_UNET_DEFERRALS.pop(_stale, None)
    return record


def _fast_disk_open_window(
    model: Any, model_config: Any, lane_trace: Any, *, get_model_wall_ms: float | None,
) -> None:
    """Open the window after model construction (UNET lane, flag on).

    No-op for non-Base models / already-CUDA models so CLIP/VAE/other
    loads are never touched.
    """
    if model is None:
        return
    if not callable(getattr(model, "load_model_weights", None)):
        return
    if not _fast_disk_model_is_cpu_resident(model):
        return
    record = _fast_disk_record_for(model)
    if record is None:
        record = _fast_disk_new_record(model, model_config, lane_trace)
    record["timings"]["get_model_wall_ms"] = get_model_wall_ms


def _fast_disk_record_patcher(patcher: Any, *, duration_ms: float | None = None) -> None:
    """Record the exact patcher when a fast-disk window is open for its model."""
    model = getattr(patcher, "model", None)
    if model is None:
        return
    if _fast_disk_record_for(model) is None:
        return
    is_dynamic = False
    try:
        _fn = getattr(patcher, "is_dynamic", None)
        is_dynamic = bool(_fn()) if callable(_fn) else False
    except Exception:
        pass
    patcher_info: dict[str, Any] = {
        "object_id": str(id(patcher)),
        "type_module": type(patcher).__module__,
        "type_name": type(patcher).__name__,
        "is_dynamic": is_dynamic,
        "load_device": getattr(patcher, "load_device", None),
        "offload_device": getattr(patcher, "offload_device", None),
    }
    with _FAST_DISK_UNET_LOCK:
        _rec = _FAST_DISK_UNET_DEFERRALS.get(id(model))
        if _rec is None:
            return
        _rec["patcher"] = patcher_info
        if duration_ms is not None:
            _rec["timings"]["ctor_wall_ms"] = duration_ms


def _fast_disk_resolve_to_target(
    args: tuple[Any, ...], kwargs: dict[str, Any],
) -> Any | None:
    """Resolve the device target of a ``Module.to`` call (None when not a
    device move)."""
    device_arg = None
    if args:
        device_arg = args[0]
    elif "device" in kwargs:
        device_arg = kwargs["device"]
    if device_arg is None:
        return None
    try:
        import torch as _torch_tg
        if isinstance(device_arg, _torch_tg.device):
            return device_arg
        if isinstance(device_arg, str):
            return _torch_tg.device(device_arg)
        if isinstance(device_arg, int):
            return _torch_tg.device("cuda", device_arg)
    except Exception:
        return None
    return None


def _fast_disk_guard_to(
    record: dict[str, Any], target: Any,
) -> tuple[bool, str, dict[str, Any]]:
    """Every load-time guard for deferring the first UNET model.to() call.

    Returns ``(ok, reason, evidence)``.  Fails closed on any unmet guard;
    the caller then runs the real ``to()`` through the legacy path.
    """
    evidence: dict[str, Any] = {}
    if target is None:
        return False, "target_unresolved", evidence
    _target_type = str(getattr(target, "type", "") or "").lower()
    if _target_type != "cuda":
        return False, f"target_not_cuda:{_target_type or 'none'}", evidence
    evidence["target"] = str(target)
    if not _fast_disk_high_vram():
        return False, "not_high_vram", evidence
    evidence["vram"] = "HIGH_VRAM"
    with _FAST_DISK_UNET_LOCK:
        patcher = dict(record.get("patcher") or {})
    evidence["patcher"] = {
        "class": f"{patcher.get('type_module', '')}.{patcher.get('type_name', '')}",
        "is_dynamic": bool(patcher.get("is_dynamic", False)),
    }
    if not patcher:
        return False, "patcher_unrecorded", evidence
    if patcher.get("is_dynamic"):
        return False, "dynamic_patcher", evidence
    if (
        patcher.get("type_name") != "ModelPatcher"
        or patcher.get("type_module") != "comfy.model_patcher"
    ):
        return False, "patcher_not_plain_model_patcher", evidence
    _tgt_key = _fast_disk_device_key(target)
    _load_key = _fast_disk_device_key(patcher.get("load_device"))
    _off_key = _fast_disk_device_key(patcher.get("offload_device"))
    # Exact device guard: the plain patcher's load_device, offload_device,
    # and the deferred target must ALL be equal AND all CUDA/non-CPU.  An
    # OR/partial agreement is insufficient — any mismatch fails closed.
    if (
        _tgt_key is None
        or _load_key is None
        or _off_key is None
        or _tgt_key != _load_key
        or _load_key != _off_key
    ):
        return False, "deferred_target_mismatch", evidence
    if _tgt_key[0] != "cuda":
        return False, "deferred_target_not_cuda", evidence
    evidence["load_device"] = str(patcher.get("load_device"))
    evidence["offload_device"] = str(patcher.get("offload_device"))
    evidence["target_device"] = str(target)
    _mc = dict(record.get("model_config_evidence") or {})
    evidence["model_config_evidence"] = _mc
    if _mc.get("quant_config_present"):
        return False, "quant_config_present", evidence
    if _mc.get("custom_operations_present"):
        return False, "custom_operations_present", evidence
    if _mc.get("fp8_optimization"):
        return False, "fp8_optimization", evidence
    if _mc.get("force_channels_last"):
        return False, "force_channels_last", evidence
    if _fast_disk_torch_future_enabled():
        return False, "torch_swap_module_params_future", evidence
    if not _fast_disk_model_is_cpu_resident(_fast_disk_record_model(record)):
        return False, "model_not_cpu_resident", evidence
    evidence["torch_future"] = "disabled"
    return True, "ok", evidence


def _fast_disk_guard_bind(
    record: dict[str, Any], args: tuple[Any, ...], kwargs: dict[str, Any],
) -> tuple[bool, str, dict[str, Any]]:
    """Bind-time guards over the state-dict values.

    All prefix-matching state-dict entries must be exact plain
    ``torch.Tensor`` values with a uniform source dtype equal to the
    constructed diffusion-model parameter dtype, and the recorded patcher
    must still be the exact plain non-dynamic ModelPatcher.  Returns
    ``(ok, reason, evidence)``.
    """
    evidence: dict[str, Any] = {}
    model = _fast_disk_record_model(record)
    if model is None:
        return False, "model_missing", evidence
    with _FAST_DISK_UNET_LOCK:
        patcher = dict(record.get("patcher") or {})
    if not patcher or patcher.get("is_dynamic"):
        return False, "dynamic_patcher", evidence
    sd = args[0] if args else kwargs.get("sd")
    unet_prefix = args[1] if len(args) > 1 else kwargs.get("unet_prefix", "")
    if not isinstance(sd, Mapping):
        return False, "sd_not_mapping", evidence
    try:
        import torch as _torch_fd
    except Exception:
        return False, "torch_unavailable", evidence
    _first_param_dtype = None
    for _p in model.parameters():
        _first_param_dtype = getattr(_p, "dtype", None)
        break
    if _first_param_dtype is None:
        return False, "no_model_parameters", evidence
    evidence["param_dtype"] = str(_first_param_dtype)
    _prefix = str(unet_prefix or "")
    _dtypes: set = set()
    _tensor_count = 0
    _elem_count = 0
    for _k, _v in sd.items():
        if not str(_k).startswith(_prefix):
            continue
        if type(_v) is not _torch_fd.Tensor:
            return False, "non_plain_tensor_sd", evidence
        _dev_type = str(getattr(getattr(_v, "device", None), "type", "") or "").lower()
        if _dev_type != "cpu":
            return False, "sd_tensor_not_cpu", evidence
        _dtypes.add(_v.dtype)
        _tensor_count += 1
        try:
            _elem_count += int(_v.numel())
        except Exception:
            pass
        if len(_dtypes) > 1:
            return False, "sd_dtype_not_uniform", evidence
    if _tensor_count == 0:
        return False, "no_prefix_sd_tensors", evidence
    _only_dtype = next(iter(_dtypes))
    if _only_dtype != _first_param_dtype:
        return False, f"sd_dtype_mismatch:{_only_dtype}!={_first_param_dtype}", evidence
    evidence["sd_tensor_count"] = _tensor_count
    evidence["sd_dtype"] = str(_only_dtype)
    evidence["sd_elem_count"] = _elem_count
    return True, "ok", evidence


def _fast_disk_parameter_accounting(model: Any) -> dict[str, Any]:
    """Cheap parameter metadata accounting — never hashes 12.31 GB."""
    accounting: dict[str, Any] = {
        "param_count": 0,
        "parameter_bytes": 0,
        "dtype_distribution": {},
        "device_distribution": {},
        "cpu_param_count": 0,
        "cpu_buffer_count": 0,
    }
    if model is None:
        return accounting
    try:
        for _p in model.parameters():
            accounting["param_count"] += 1
            try:
                accounting["parameter_bytes"] += int(_p.numel()) * int(_p.element_size())
            except Exception:
                pass
            _dt = str(getattr(_p, "dtype", "")) or "unknown"
            accounting["dtype_distribution"][_dt] = (
                accounting["dtype_distribution"].get(_dt, 0) + 1
            )
            _dev = str(getattr(getattr(_p, "device", None), "type", "") or "").lower() or "unknown"
            accounting["device_distribution"][_dev] = (
                accounting["device_distribution"].get(_dev, 0) + 1
            )
            if _dev == "cpu":
                accounting["cpu_param_count"] += 1
    except Exception:
        pass
    try:
        for _b in model.buffers():
            _dev = str(getattr(getattr(_b, "device", None), "type", "") or "").lower() or "unknown"
            if _dev == "cpu":
                accounting["cpu_buffer_count"] += 1
    except Exception:
        pass
    return accounting


def _fast_disk_print_proof(
    record: dict[str, Any], *, decision: str, reason: str, stage: str,
    model: Any = None,
) -> None:
    try:
        # *model* may be passed explicitly when the record was already
        # dropped (complete event) — the live model still exists, so the
        # accounting is always valid after cleanup.
        _live = model if model is not None else _fast_disk_record_model(record)
        _accounting = _fast_disk_parameter_accounting(_live)
        with _FAST_DISK_UNET_LOCK:
            _patcher = dict(record.get("patcher") or {})
        _patcher_class = (
            f"{_patcher.get('type_module', '')}.{_patcher.get('type_name', '')}"
            if _patcher else "none"
        )
        _t = record.get("timings") or {}
        print(
            f"[v2.native_fast_disk_unet] decision={decision} reason={reason or 'ok'} "
            f"stage={stage} "
            f"patcher_class={_patcher_class} patcher_dynamic={int(bool(_patcher.get('is_dynamic', False)))} "
            f"param_count={_accounting['param_count']} "
            f"parameter_bytes={_accounting['parameter_bytes']} "
            f"dtype_distribution={_accounting['dtype_distribution']} "
            f"device_distribution={_accounting['device_distribution']} "
            f"cpu_params={_accounting['cpu_param_count']} "
            f"cpu_buffers={_accounting['cpu_buffer_count']} "
            f"get_model_ms={_t.get('get_model_wall_ms')} "
            f"ctor_ms={_t.get('ctor_wall_ms')} "
            f"bind_ms={_t.get('bind_wall_ms')} "
            f"to_wall_ms={_t.get('to_wall_ms')} "
            f"to_device_ms={_t.get('to_device_ms')} "
            f"to_device_ms_label={_t.get('to_device_ms_label', 'unavailable')}",
            flush=True,
        )
    except Exception:
        pass


_FAST_DISK_EVENT_BY_DECISION: dict[str, str] = {
    "defer": _EVENT_FAST_DISK_DEFER,
    "skip": _EVENT_FAST_DISK_SKIP,
    "complete": _EVENT_FAST_DISK_COMPLETE,
}


def _fast_disk_emit_event(
    record: dict[str, Any], lane_trace: Any, *,
    decision: str, reason: str, stage: str,
    extra_meta: dict[str, Any] | None = None,
    model: Any = None,
) -> None:
    """Emit one fast-disk decision event (defer/skip/complete) + proof line.

    The ``complete`` decision carries the full accounting/proof fields and
    accepts the live *model* explicitly so it stays valid even after the
    deferral record has been dropped.
    """
    trace = _fast_disk_trace(lane_trace)
    _event = _FAST_DISK_EVENT_BY_DECISION.get(decision)
    _target = record.get("target")
    _t = record.get("timings") or {}
    _meta: dict[str, Any] = {
        "decision": decision,
        "reason": reason or "ok",
        "stage": stage,
        "target": str(_target) if _target is not None else "",
        "get_model_ms": _t.get("get_model_wall_ms"),
        "ctor_ms": _t.get("ctor_wall_ms"),
    }
    if decision == "complete":
        _accounting = _fast_disk_parameter_accounting(
            model if model is not None else _fast_disk_record_model(record)
        )
        with _FAST_DISK_UNET_LOCK:
            _patcher = dict(record.get("patcher") or {})
        _meta.update({
            "patcher_class": (
                f"{_patcher.get('type_module', '')}.{_patcher.get('type_name', '')}"
                if _patcher else "none"
            ),
            "patcher_dynamic": bool(_patcher.get("is_dynamic", False)),
            "native_assign": False,
            "bind_assign": True,
            "bind_ms": _t.get("bind_wall_ms"),
            "to_wall_ms": _t.get("to_wall_ms"),
            "to_device_ms": _t.get("to_device_ms"),
            "to_device_ms_label": _t.get("to_device_ms_label", "unavailable"),
            # ── H2D decomposition (additive; absent when instrumentation
            # failed or the measurement was unavailable) ──
            "h2d_cuda_elapsed_ms": _t.get("h2d_cuda_elapsed_ms"),
            "h2d_enqueue_host_ms": _t.get("h2d_enqueue_host_ms"),
            "h2d_sync_wait_host_ms": _t.get("h2d_sync_wait_host_ms"),
            "h2d_copy_count": _t.get("h2d_copy_count"),
            "h2d_total_bytes": _t.get("h2d_total_bytes"),
            "h2d_largest_copy_bytes": _t.get("h2d_largest_copy_bytes"),
            "h2d_stream_id": _t.get("h2d_stream_id"),
            "h2d_stream_cuda_stream": _t.get("h2d_stream_cuda_stream"),
            "h2d_sync_method": _t.get("h2d_sync_method"),
            **_accounting,
        })
        # ── H2D classification (guarded; additive) ──
        # Absent when the telemetry module / classify_h2d is unavailable.
        # Never overwrites an existing key.
        try:
            from comfymodal_runtime import host_hardware_telemetry as _hht_cls
            _timings = record.get("timings") or {}
            _cls = _hht_cls.classify_h2d(_timings)
        except Exception:
            _cls = None
        if _cls is not None and "h2d_classification" not in _meta:
            _meta["h2d_classification"] = _cls
    if extra_meta:
        _meta.update(dict(extra_meta))
    if trace is not None and _event is not None:
        trace.emit(_event, phase="restore", metadata=_meta)
    _fast_disk_print_proof(
        record, decision=decision, reason=reason, stage=stage, model=model,
    )


def _fast_disk_waves_eligible(target, to_kwargs, staging_eligible) -> tuple[bool, str]:
    """Wave-split probe eligibility.  Pinned staging takes precedence, then
    dtype/memory-format conversion requests and non-CUDA targets reject.
    Returns ``(ok, reason)``; never raises."""
    if staging_eligible:
        return (False, "pinned_staging_active")
    if "dtype" in to_kwargs or "memory_format" in to_kwargs:
        return (False, "dtype_conversion_requested")
    if target is None or str(getattr(target, "type", "")) != "cuda":
        return (False, "target_not_cuda")
    try:
        import torch as _torch_wv
        if (
            _torch_wv.cuda.is_available()
            and getattr(_torch_wv.cuda, "Event", None) is not None
        ):
            return (True, "ok")
    except Exception:
        pass
    return (False, "cuda_unavailable")


def _fast_disk_build_wave_items(model) -> list[tuple[Any, str, str, Any, int]]:
    """Collect CPU-resident parameters then buffers per module in
    Module._apply order (modules() DFS).  Any failure returns ``[]``."""
    try:
        import torch as _torch_wv
        _Tensor = _torch_wv.Tensor
    except Exception:
        return []
    _items: list[tuple[Any, str, str, Any, int]] = []
    try:
        for _module in model.modules():
            for _name, _param in _module._parameters.items():
                try:
                    if isinstance(_param, _Tensor) and _param.data is not None \
                            and str(_param.device).startswith("cpu"):
                        _items.append((_module, _name, "param", _param,
                                       int(_param.numel()) * int(_param.element_size())))
                except Exception:
                    continue
            for _name, _buffer in _module._buffers.items():
                try:
                    if isinstance(_buffer, _Tensor) and _buffer.data is not None \
                            and str(_buffer.device).startswith("cpu"):
                        _items.append((_module, _name, "buffer", _buffer,
                                       int(_buffer.numel()) * int(_buffer.element_size())))
                except Exception:
                    continue
    except Exception:
        return []
    return _items


def _fast_disk_partition_waves(items, wave_count) -> list[dict[str, Any]]:
    """Greedy byte-boundary wave partition.  Boundaries sit at
    ``total_bytes*k/wave_count``; a wave closes once cumulative bytes reach
    the next boundary.  At most ``wave_count`` waves; the last absorbs the
    remainder.  Each wave carries ordinal/first_ordinal/last_ordinal/
    tensor_count/bytes/items."""
    try:
        _total = sum(int(_it[4]) for _it in items)
    except Exception:
        _total = 0
    if not items or _total <= 0:
        return []
    _waves: list[dict[str, Any]] = []
    _buf: list[Any] = []
    _buf_bytes = 0
    _cum = 0
    _first = 0
    _next_k = 1
    _wc = max(1, int(wave_count))
    for _idx, _it in enumerate(items):
        _b = int(_it[4])
        _buf.append(_it)
        _buf_bytes += _b
        _cum += _b
        if _next_k < _wc and _cum >= (_total * _next_k) / _wc:
            _waves.append({
                "ordinal": len(_waves),
                "first_ordinal": _first,
                "last_ordinal": _idx,
                "tensor_count": len(_buf),
                "bytes": _buf_bytes,
                "items": _buf,
            })
            _first = _idx + 1
            _buf = []
            _buf_bytes = 0
            _next_k += 1
    if _buf:
        _waves.append({
            "ordinal": len(_waves),
            "first_ordinal": _first,
            "last_ordinal": len(items) - 1,
            "tensor_count": len(_buf),
            "bytes": _buf_bytes,
            "items": _buf,
        })
    return _waves


def _fast_disk_replay_waves(model, waves, target, to_kwargs, non_blocking_default=False) -> None:
    """Replay the per-item ``tensor.to(target, non_blocking=...)`` semantics
    of Module._apply for the given waves.  Never synchronizes.  Exceptions
    propagate so the probe caller can fall back to the original ``to()``."""
    import torch as _torch_wv
    _nb = bool(to_kwargs.get("non_blocking", non_blocking_default))
    for _wave in waves:
        for _item in _wave.get("items", []):
            _module, _name, _kind, _tensor, _bytes = _item
            with _torch_wv.no_grad():
                _applied = _tensor.to(target, non_blocking=_nb)
            if _applied is _tensor:
                continue
            if _kind == "param":
                setattr(_module, _name, _torch_wv.nn.Parameter(
                    _applied, requires_grad=_tensor.requires_grad))
            else:
                setattr(_module, _name, _applied)


def _fast_disk_replay_to_waves_probe(model, record, to_args, to_kwargs, target, trace, lane_trace, staging_eligible=False):
    """Measurement-only phase I-2 wave-split H2D replay probe.  Returns
    ``(used, waves, ev_pairs)``.  Never raises: any failure prints a
    fallback line and returns ``(False, None, None)`` so the caller runs the
    exact original ``to()``.  Per-wave CUDA events are recorded but never
    synchronized here — they are realized by the single existing
    synchronize in the replay ``finally``.  If a failure happens after some
    parameters were already moved, the fallback original ``to()`` re-runs
    over the whole module; already-moved parameters are no-ops (``.to()``
    returns self), so the final state is identical — the same pattern the
    pinned-staging fallback already relies on."""
    if model is None:
        return (False, None, None)
    try:
        import torch as _torch_wv
        _ok, _reason = _fast_disk_waves_eligible(target, to_kwargs, staging_eligible)
        if not _ok:
            print(f"[v2.c6_probe] waves fallback={_reason}", flush=True)
            return (False, None, None)
        _items = _fast_disk_build_wave_items(model)
        if not _items:
            return (False, None, None)
        _waves = _fast_disk_partition_waves(_items, _C6_PROBE_WAVE_COUNT)
        if not _waves:
            return (False, None, None)
        _ev_pairs: list[tuple[Any, Any]] = []
        for _wave in _waves:
            _ev_start = _torch_wv.cuda.Event(enable_timing=True)
            _ev_start.record()
            _t0 = time.perf_counter()
            _fast_disk_replay_waves(model, [_wave], target, to_kwargs)
            _t1 = time.perf_counter()
            _ev_end = _torch_wv.cuda.Event(enable_timing=True)
            _ev_end.record()
            _wave["enqueue_host_ms"] = round((_t1 - _t0) * 1000, 3)
            _ev_pairs.append((_ev_start, _ev_end))
        return (True, _waves, _ev_pairs)
    except Exception as _exc:
        print(f"[v2.c6_probe] waves fallback=exception:{type(_exc).__name__}", flush=True)
        return (False, None, None)


def _fast_disk_replay_to(record: dict[str, Any], lane_trace: Any) -> Any:
    """Replay the deferred REAL original ``model.to(target)`` exactly once.

    Measures the Python wall (enqueue) time and, when CUDA supports events,
    an explicitly synchronized/device measurement for the real transfer.
    Emits ``unet_fast_disk_to_start/end`` with the labels.  Returns the
    original ``to()`` result (normally the module itself).
    """
    model = _fast_disk_record_model(record)
    original_to = record.get("original_to")
    to_args = record.get("to_args") or ()
    to_kwargs = record.get("to_kwargs") or {}
    target = record.get("target")
    if model is None or original_to is None:
        return model
    trace = _fast_disk_trace(lane_trace)
    # ── Experiment 1 (unet_transfer, B arm): bounded pinned-staging ────
    # Default OFF (COMFYMODAL_V2_UNET_PINNED_STAGING unset): the code path
    # below is byte-for-byte the original A path.  When enabled, the B arm
    # is eligible ONLY when the target is a cuda device, ``to_kwargs``
    # requests no dtype/memory-format conversion (the model is already
    # BF16 in RAM — raw-byte copies would be wrong under dtype conversion),
    # and CUDA is available.  Any eligibility failure falls back silently
    # to the exact original A path with a logged line.
    _staging: bool = False
    _chunk_mb: int = 512
    _staging_eligible: bool = False
    _staging_reason: str = ""
    try:
        _staging = bool(unet_pinned_staging_enabled())
    except Exception:
        _staging = False
    if _staging:
        try:
            _chunk_mb = max(1, int(unet_staging_chunk_mb() or 512))
        except Exception:
            _chunk_mb = 512
        _target_type = str(getattr(target, "type", "") or "")
        _no_dtype_conv = (
            "dtype" not in to_kwargs and "memory_format" not in to_kwargs
        )
        _cuda_avail = False
        try:
            import torch as _torch_stg
            _cuda_avail = bool(_torch_stg.cuda.is_available())
        except Exception:
            _cuda_avail = False
        if _target_type != "cuda":
            _staging_reason = "target_not_cuda"
        elif not _no_dtype_conv:
            _staging_reason = "dtype_conversion_requested"
        elif not _cuda_avail:
            _staging_reason = "cuda_unavailable"
        else:
            _staging_eligible = True
        if not _staging_eligible:
            print(
                f"{experiment_line(resolve_experiment('unet_transfer'))} "
                f"effective=baseline fallback={_staging_reason}",
                flush=True,
            )
    # ── Execution-phase H2D delay (experiment gate) ───────────────────
    # Hold the deferred H2D replay until (lane_start + delay) so the CLIP
    # forward gets a contention-free head start.  The budget is measured
    # from the execution-unet lane worker start (deterministic, in-thread)
    # and never applies when no execution lane ran (lane marker None —
    # graph-time path, byte-for-byte unchanged).  Zero/negative delay is
    # the proven immediate-start baseline.  The sleep sits OUTSIDE the
    # measured to_wall_ms window (before _start_ns below).
    _h2d_waited_ms: float = 0.0
    if _EXECUTION_UNET_H2D_DELAY_MS > 0:
        _lane_start = _EXECUTION_UNET_LANE_START_MONO
        if _lane_start is not None and _CLIP_FORWARD_STARTED.is_set():
            _deadline_ns = _lane_start + int(
                _EXECUTION_UNET_H2D_DELAY_MS * 1_000_000
            )
            _remaining_s = (_deadline_ns - time.monotonic_ns()) / 1_000_000_000
            if _remaining_s > 0:
                _h2d_wait_start_ns = time.monotonic_ns()
                if trace is not None:
                    trace.emit("unet_h2d_delay_start", phase="restore", metadata={
                        "delay_ms": _EXECUTION_UNET_H2D_DELAY_MS,
                        "remaining_ms": round(_remaining_s * 1000, 3),
                    })
                time.sleep(_remaining_s)
                _h2d_waited_ms = round(
                    (time.monotonic_ns() - _h2d_wait_start_ns) / 1_000_000, 3
                )
                if trace is not None:
                    trace.emit("unet_h2d_delay_end", phase="restore", metadata={
                        "delay_ms": _EXECUTION_UNET_H2D_DELAY_MS,
                        "waited_ms": _h2d_waited_ms,
                    })
    # ── LANE 1 (measurement-only): UNET fast-disk H2D transfer probe ──
    # OptTransferProbe aggregates per-parameter tensor stats, host-side
    # effect deltas, stream identity, and a CUDA-event interval that is
    # realized via the existing ``finally`` synchronize below (reused —
    # never an extra sync).  Pure instrumentation; no runtime behavior
    # change.  All no-ops when COMFYMODAL_V2_OPTIMIZATION_DIAGNOSTICS is
    # unset.
    _opt_h2d_probe = None
    if _OPT_DIAG:
        try:
            # Experiment 1: reflect the pinned-staging B arm when active
            # (copy_api matches the staging metrics label, non_blocking True).
            _opt_h2d_probe = OptTransferProbe(
                trace or lane_trace,
                phase="restore",
                metadata={
                    "target": str(target) if target is not None else "",
                    "non_blocking": True if _staging_eligible else False,
                    "copy_api": (
                        "pinned_staging_chunked_copy_"
                        if _staging_eligible
                        else "module.to (per-parameter async copy chain)"
                    ),
                    "source_kind": "pageable_cpu",
                },
            )
            _opt_h2d_probe.begin(model)
        except Exception:
            _opt_h2d_probe = None
    # Experiment 1 B-arm outcome trackers (used by the finally below; the
    # plain A path keeps both at their defaults).
    _staging_used: bool = False
    _staging_metrics: dict[str, Any] | None = None
    # ── Host telemetry: pre-H2D resource snapshot + decomposition refs ──
    # The snapshot and reference capture are measurement-only and sit
    # OUTSIDE the measured to_wall_ms window (before _start_ns) so waterfall
    # reconciliation stays byte-identical.  Every piece is guarded; failure
    # leaves the decomposition fields absent and never affects the copy.
    try:
        from comfymodal_runtime import host_hardware_telemetry as _hht
        _hht.capture_resource_snapshot("pre_h2d", trace)
    except Exception:
        pass
    _h2d_pre_cpu_refs: list[Any] | None = None
    _enqueue_t0: float | None = None
    try:
        import torch as _torch_pre
        if (
            _torch_pre.cuda.is_available()
            and target is not None
            and str(getattr(target, "type", "") or "") == "cuda"
        ):
            _h2d_pre_cpu_refs = [
                _t
                for _t in (list(model.parameters()) + list(model.buffers()))
                if str(getattr(_t, "device", "")).startswith("cpu")
            ]
            if not _h2d_pre_cpu_refs:
                _h2d_pre_cpu_refs = None
    except Exception:
        _h2d_pre_cpu_refs = None
    _probe_used: bool = False
    _probe_waves: list[dict[str, Any]] | None = None
    _probe_ev_pairs: list[tuple[Any, Any]] | None = None
    _start_ns = time.monotonic_ns()
    _torch_rp = None
    _ev_start = None
    _ev_end = None
    try:
        import torch as _torch_rp_import
        _torch_rp = _torch_rp_import
        _cuda = getattr(_torch_rp, "cuda", None)
        if (
            _cuda is not None
            and callable(getattr(_cuda, "is_available", None))
            and _cuda.is_available()
            and target is not None
            and str(getattr(target, "type", "") or "") == "cuda"
            and getattr(_cuda, "Event", None) is not None
        ):
            _ev_start = _cuda.Event(enable_timing=True)
            _ev_end = _cuda.Event(enable_timing=True)
            _ev_start.record()
    except Exception:
        _torch_rp = None
        _ev_start = _ev_end = None
    _device_ms: float | None = None
    if trace is not None:
        trace.emit(_EVENT_FAST_DISK_TO_START, phase="restore", metadata={
            "target": str(target) if target is not None else "",
            "measurement": (
                "wall_and_synchronized_device"
                if (_ev_start is not None and _ev_end is not None)
                else "wall_only"
            ),
        })
    # H2D decomposition: host wall clock of the copy-loop body only (the
    # ``original_to``/staging call).  sync_wait_host_ms is derived purely as
    # to_wall_ms − enqueue_host_ms in the finally below.
    _enqueue_t0 = time.perf_counter()
    try:
        if _staging_eligible:
            _staging_metrics = None
            try:
                from .unet_pinned_staging import transfer_module_via_pinned_staging
                _staging_metrics = transfer_module_via_pinned_staging(
                    model, target_device=target, chunk_mb=_chunk_mb,
                    trace=trace, phase="restore",
                )
            except Exception as _stg_exc:
                _staging_metrics = None
                print(
                    f"{experiment_line(resolve_experiment('unet_transfer'))} "
                    f"effective=baseline fallback=staging_exception:{type(_stg_exc).__name__}",
                    flush=True,
                )
            if _staging_metrics is not None and _staging_metrics.get("fallback") is None:
                _staging_used = True
                # Parameters are already on CUDA: the real to() is a no-op
                # but preserves its side effects byte-for-byte.
                return original_to(model, *to_args, **to_kwargs)
            _staging_reason = (
                str(_staging_metrics.get("fallback", ""))
                if _staging_metrics is not None
                else "staging_unavailable"
            )
            print(
                f"{experiment_line(resolve_experiment('unet_transfer'))} "
                f"effective=baseline fallback={_staging_reason}",
                flush=True,
            )
        if _C6_PROBE_MODE == "probe":
            _probe_used, _probe_waves, _probe_ev_pairs = _fast_disk_replay_to_waves_probe(
                model, record, to_args, to_kwargs, target, trace, lane_trace,
                _staging_eligible)
            if _probe_used:
                return model
        return original_to(model, *to_args, **to_kwargs)
    finally:
        _wall_ms = round((time.monotonic_ns() - _start_ns) / 1_000_000, 3)
        if _ev_start is not None and _ev_end is not None and _torch_rp is not None:
            try:
                _ev_end.record()
                _torch_rp.cuda.synchronize()
                if not _staging_used:
                    _device_ms = round(float(_ev_start.elapsed_time(_ev_end)), 3)
            except Exception:
                _device_ms = None
        if _staging_used and _staging_metrics is not None:
            # B arm: the truthful device measurement comes from the staging
            # metrics' CUDA events (the to() no-op measures ~0).
            _device_ms = _staging_metrics.get("cuda_event_ms")
            record["timings"]["to_device_ms_label"] = "synchronized_device"
        else:
            record["timings"]["to_device_ms_label"] = (
                "synchronized_device" if _device_ms is not None else "unavailable"
            )
        # ── LANE 1 probe realization (reuses the synchronize above) ──
        if _opt_h2d_probe is not None:
            try:
                _opt_h2d_probe.end(model)
                _opt_h2d_probe.emit("unet_h2d_transfer")
                global _OPT_UNET_H2D_MONO, _OPT_UNET_H2D_DEVICE_MS
                _OPT_UNET_H2D_MONO = (_start_ns, time.monotonic_ns())
                _OPT_UNET_H2D_DEVICE_MS = _device_ms
            except Exception:
                _opt_h2d_probe = None
        record["timings"]["to_wall_ms"] = _wall_ms
        record["timings"]["to_device_ms"] = _device_ms
        # ── H2D decomposition (measurement-only; additive, never raises) ──
        # New h2d_* keys ride on the existing unet_fast_disk_complete event
        # via record["timings"].  to_wall_ms/to_device_ms are never touched
        # here — the CUDA elapsed below is the SAME _device_ms already
        # computed above after the existing synchronize (reused, never a new
        # sync).  Every field is guarded; failure leaves the field absent.
        try:
            if _enqueue_t0 is not None:
                _h2d_enqueue_host_ms = round(
                    (time.perf_counter() - _enqueue_t0) * 1000, 3
                )
                record["timings"]["h2d_enqueue_host_ms"] = _h2d_enqueue_host_ms
            if _device_ms is not None:
                record["timings"]["h2d_cuda_elapsed_ms"] = _device_ms
            _w = record["timings"].get("to_wall_ms")
            _e = record["timings"].get("h2d_enqueue_host_ms")
            if _w is not None and _e is not None:
                record["timings"]["h2d_sync_wait_host_ms"] = round(
                    max(float(_w) - float(_e), 0.0), 3
                )
            if _h2d_pre_cpu_refs:
                _cnt = 0
                _total = 0
                _largest = 0
                for _t in _h2d_pre_cpu_refs:
                    try:
                        if str(getattr(_t, "device", "")).startswith("cuda"):
                            _n = int(_t.numel()) * int(_t.element_size())
                            _cnt += 1
                            _total += _n
                            if _n > _largest:
                                _largest = _n
                    except Exception:
                        continue
                record["timings"]["h2d_copy_count"] = _cnt
                record["timings"]["h2d_total_bytes"] = _total
                record["timings"]["h2d_largest_copy_bytes"] = _largest
            try:
                import torch as _torch_decomp
                _cur_stream = _torch_decomp.cuda.current_stream()
                record["timings"]["h2d_stream_id"] = str(_cur_stream)
                _cs_id = getattr(_cur_stream, "cuda_stream", None)
                if _cs_id is not None:
                    try:
                        record["timings"]["h2d_stream_cuda_stream"] = int(_cs_id)
                    except Exception:
                        pass
            except Exception:
                pass
            record["timings"]["h2d_sync_method"] = "torch.cuda.synchronize (full device)"
        except Exception:
            pass
        if _staging_used:
            try:
                # Unified experiment metadata, once per request on the B arm.
                emit_experiment_selection(
                    trace or lane_trace, resolve_experiment("unet_transfer")
                )
            except Exception:
                pass
        if trace is not None:
            _end_meta = {
                "target": str(target) if target is not None else "",
                "wall_ms": _wall_ms,
                "device_ms": _device_ms,
                "device_ms_label": record["timings"]["to_device_ms_label"],
                "measurement": (
                    "wall_and_synchronized_device"
                    if _device_ms is not None
                    else "wall_only"
                ),
            }
            if _staging_used and _staging_metrics is not None:
                _end_meta.update({
                    "experiment": "unet_transfer",
                    "arm": "pinned_staging",
                    "copy_api": _staging_metrics.get(
                        "copy_api", "pinned_staging_chunked_copy_"
                    ),
                    "non_blocking": True,
                    "stream": _staging_metrics.get("stream", ""),
                    "stream_priority": _staging_metrics.get("stream_priority"),
                    "source_pinned_fraction": _staging_metrics.get(
                        "source_pinned_fraction", 0.0
                    ),
                    "staging_alloc_bytes": _staging_metrics.get("staging_alloc_bytes"),
                    "peak_staging_bytes": _staging_metrics.get("peak_staging_bytes"),
                    "chunk_mb": _staging_metrics.get("chunk_mb"),
                    "chunk_count": _staging_metrics.get("chunk_count"),
                    "copied_params": _staging_metrics.get("copied_params"),
                    "copied_buffers": _staging_metrics.get("copied_buffers"),
                    "gbps": _staging_metrics.get("gbps"),
                })
            trace.emit(_EVENT_FAST_DISK_TO_END, phase="restore", metadata=_end_meta)
        # ── I-2 wave-split H2D probe realization (guarded; additive) ────
        # Per-wave CUDA events were recorded by the probe without a sync of
        # their own; the single existing synchronize above realizes them.
        if _probe_used and _probe_ev_pairs and _probe_waves:
            try:
                for _i, (_ev_s, _ev_e) in enumerate(_probe_ev_pairs):
                    try:
                        _ms = round(float(_ev_s.elapsed_time(_ev_e)), 3)
                        _probe_waves[_i]["device_ms"] = _ms
                    except Exception:
                        pass
                _waves_meta = []
                _cum_wave_bytes = 0
                for _w in _probe_waves:
                    _cum_wave_bytes += int(_w.get("bytes", 0))
                    _waves_meta.append({
                        "ordinal": _w["ordinal"],
                        "first_ordinal": _w["first_ordinal"],
                        "last_ordinal": _w["last_ordinal"],
                        "tensor_count": _w["tensor_count"],
                        "bytes": _w["bytes"],
                        "enqueue_host_ms": _w.get("enqueue_host_ms"),
                        "device_ms": _w.get("device_ms"),
                        "cum_bytes": _cum_wave_bytes,
                    })
                _total_tensors = sum(int(_w["tensor_count"]) for _w in _probe_waves)
                _total_bytes = sum(int(_w["bytes"]) for _w in _probe_waves)
                _sum_wave_device_ms = sum(
                    float(_w.get("device_ms", 0.0) or 0.0) for _w in _probe_waves)
                _sum_enqueue_host_ms = sum(
                    float(_w.get("enqueue_host_ms", 0.0) or 0.0) for _w in _probe_waves)
                _host_gap_ms = (
                    round(max(float(_wall_ms) - _sum_enqueue_host_ms, 0.0), 3)
                    if _sum_enqueue_host_ms > 0.0
                    else None
                )
                if trace is not None:
                    trace.emit("unet_read_h2d_wave_probe", phase="restore", metadata={
                        "mode": "probe",
                        "kind": "h2d_wave_series",
                        "wave_count": len(_probe_waves),
                        "total_tensors": _total_tensors,
                        "total_bytes": _total_bytes,
                        "total_wall_ms": _wall_ms,
                        "total_device_ms": _device_ms,
                        "waves": _waves_meta,
                        "device_ms_sum": round(_sum_wave_device_ms, 3),
                        "host_gap_ms": _host_gap_ms,
                    })
                _dev_list = [
                    round(float(_w.get("device_ms", 0.0) or 0.0), 3)
                    for _w in _probe_waves
                ]
                _dev_str = ",".join(str(_v) for _v in _dev_list[:3])
                if len(_dev_list) > 4:
                    _dev_str += ",.."
                print(
                    f"[v2.c6_probe] h2d waves={len(_probe_waves)} "
                    f"tensors={_total_tensors} bytes={_total_bytes} "
                    f"wall_ms={_wall_ms} device_ms={_device_ms} "
                    f"sum_waves_device_ms={round(_sum_wave_device_ms, 3)} "
                    f"waves_device_ms=[{_dev_str}]",
                    flush=True,
                )
            except Exception:
                pass
        # ── Host telemetry: post-H2D resource snapshot (guarded; runs after
        # the existing final synchronize; never raises) ──
        try:
            from comfymodal_runtime import host_hardware_telemetry as _hht
            _hht.capture_resource_snapshot("post_h2d", trace)
        except Exception:
            pass
        # ── Host telemetry: slow-H2D forensic trigger (guarded) ──
        # OFF the healthy path: only fires when the H2D wall time is at/above
        # the slow threshold (COMFYMODAL_V2_SLOW_H2D_THRESHOLD_MS, default
        # 4000 ms) or COMFYMODAL_V2_HOST_DIAGNOSTICS=1 forces it.  Silent
        # no-op when the module / function is absent; never raises.
        try:
            from comfymodal_runtime import host_hardware_telemetry as _hht_f
            _timings = record.get("timings") or {}
            _wall = float(_timings.get("to_wall_ms") or _timings.get("to_device_ms") or 0.0)
            if _hht_f.should_trigger_slow_probe(_wall):
                _hht_f.emit_slow_h2d_forensics(_timings, trace)
        except Exception:
            pass


def _fast_disk_maybe_defer_to(
    model: Any, args: tuple[Any, ...], kwargs: dict[str, Any],
    lane_trace: Any, original_to: Callable[..., Any],
) -> str:
    """Attempt to defer exactly one eligible first UNET model.to() call.

    Returns ``"deferred"`` (the real original to() is replayed later by the
    load_model_weights wrapper), ``"skip"`` (a guard failed or the window
    closed — the caller runs the real to() through the legacy path), or
    ``"no_window"`` (no fast-disk window — legacy path, no fast-disk
    events).
    """
    record = _fast_disk_record_for(model)
    if record is None:
        return "no_window"
    with _FAST_DISK_UNET_LOCK:
        status = record.get("status")
    if status == "deferred":
        # Safety net (not the native flow): a second to() before the bind.
        # Replay the deferred real to() and close the window; the current
        # to() then runs through the legacy path.
        _fast_disk_emit_event(record, lane_trace, decision="skip",
                              reason="second_to_before_bind", stage="to",
                              extra_meta={"status": "deferred"})
        try:
            _fast_disk_replay_to(record, lane_trace)
        finally:
            _fast_disk_drop_record(model)
        return "skip"
    if status != "constructed":
        return "no_window"
    target = _fast_disk_resolve_to_target(args, kwargs)
    _ok, _reason, _evidence = _fast_disk_guard_to(record, target)
    if not _ok:
        _fast_disk_emit_event(record, lane_trace, decision="skip",
                              reason=_reason, stage="to", extra_meta=_evidence)
        _fast_disk_drop_record(model)
        return "skip"
    with _FAST_DISK_UNET_LOCK:
        record["to_args"] = args
        record["to_kwargs"] = dict(kwargs)
        record["original_to"] = original_to
        record["target"] = target
        record["status"] = "deferred"
    _fast_disk_emit_event(record, lane_trace, decision="defer", reason="ok",
                          stage="to", extra_meta=_evidence)
    return "deferred"


def _fast_disk_handle_bind(
    model: Any, load_weights: Callable[..., Any], args: tuple[Any, ...],
    kwargs: dict[str, Any], lane_trace: Any,
) -> Any:
    """Run the bind-then-replay fast path when a deferred to() exists.

    Returns the load result when the fast path handled the call, or None
    when no deferral window exists (the legacy path runs unchanged).

    Fast ordering (all guards green):
      original load_model_weights(assign=True)  -> bind
      exactly one REAL original model.to(target) -> replay
    Any failed guard replays the deferred real model.to(target) BEFORE
    invoking the original load_model_weights with its ORIGINAL assign
    value, preserving the legacy order and exceptions exactly.  The
    deferral record is always removed on every path.
    """
    record = _fast_disk_record_for(model)
    if record is None:
        return None
    with _FAST_DISK_UNET_LOCK:
        status = record.get("status")
    if status != "deferred":
        # No deferred to(): nothing to replay.  Close any stale window and
        # let the legacy path run unchanged.
        _fast_disk_drop_record(model)
        return None
    trace = _fast_disk_trace(lane_trace)
    original_assign = kwargs.get("assign", False)

    def _legacy_replay_then_load(reason: str, evidence: dict[str, Any]) -> Any:
        """Guard failure: legacy ordering — deferred real to() first, then
        the original load_model_weights with its ORIGINAL assign value."""
        _fast_disk_emit_event(record, lane_trace, decision="skip",
                              reason=reason, stage="bind", extra_meta=evidence)
        try:
            _fast_disk_replay_to(record, lane_trace)
        finally:
            _fast_disk_drop_record(model)
        return load_weights(*args, **kwargs)

    _ok, _reason, _evidence = _fast_disk_guard_bind(record, args, kwargs)
    if not _ok:
        return _legacy_replay_then_load(_reason, _evidence)
    if original_assign is not False:
        return _legacy_replay_then_load(
            f"native_assign_not_false:{original_assign!r}",
            {"native_assign": repr(original_assign)},
        )

    # ── Fast path: bind with assign=True, then replay the real to() ──
    if trace is not None:
        trace.emit(_EVENT_FAST_DISK_BIND_START, phase="restore", metadata={
            "decision": "bind",
            "native_assign": False,
            "bind_assign": True,
        })
    _bind_start_ns = time.monotonic_ns()
    try:
        _bind_kwargs = dict(kwargs)
        _bind_kwargs["assign"] = True
        result = load_weights(*args, **_bind_kwargs)
    except BaseException:
        # The bind failed.  Restore the legacy ordering (replay the deferred
        # real to()) so the model state is as close as possible to the native
        # failure point, then re-raise the ORIGINAL exception.  Cleanup runs
        # on every path.
        try:
            try:
                _fast_disk_replay_to(record, lane_trace)
            except BaseException:
                pass
        finally:
            _fast_disk_drop_record(model)
        raise
    record["timings"]["bind_wall_ms"] = round(
        (time.monotonic_ns() - _bind_start_ns) / 1_000_000, 3
    )
    if trace is not None:
        trace.emit(_EVENT_FAST_DISK_BIND_END, phase="restore", metadata={
            "decision": "bind",
            "bind_wall_ms": record["timings"]["bind_wall_ms"],
        })
    # Exactly one REAL original model.to(target).
    try:
        _fast_disk_replay_to(record, lane_trace)
    finally:
        _fast_disk_drop_record(model)
    # The complete event/proof runs AFTER the record cleanup, so it receives
    # the live model explicitly — the accounting stays valid.
    _fast_disk_emit_event(record, lane_trace, decision="complete", reason="ok",
                          stage="load_model_weights", model=model)
    return result


# ── UNET model construction wrappers ────────────────────────────────
# Wrap ModelPatcher/CoreModelPatcher constructors and model.to() so
# model-construction children are captured in measured_direct_children_ms.


def _make_model_patcher_constructor_wrapper(original):
    """Wrap ``model_patcher.ModelPatcher().__init__`` (or subclass) with lane guard.

    Extends the existing UNET-only instrumentation to also emit named
    ``clip_model_patcher_constructor_start/end`` events when the active
    lane is CLIP.  CLIP-lane spans are NOT recorded into
    ``_clip_cpu_prepare_children`` — they are nested inside
    ``load_text_encoder_state_dicts`` which is the direct measured owner.
    UNET-lane spans are recorded into ``_child_durations`` as before.

    Literal timing ownership: the constructor duration ends immediately
    after the native ``__init__`` returns.  The existing
    ``ensure_sampling_timing_wrapper`` and ``register_unet_forward_probe``
    helpers execute AFTER that span (never inside it), so their cost is
    never attributed to the literal ModelPatcher constructor.  Under
    ``COMFYMODAL_V2_NATIVE_FAST_DISK_UNET`` the exact patcher is also
    recorded for the fast-disk deferral window (UNET lane only).
    """
    import functools as _ft

    @_ft.wraps(original)
    def wrapper(self, *args: Any, **kwargs: Any) -> None:
        lane = _ACTIVE_LANE_TRACE.get()
        emit_unet = (lane is not None and lane._lane == "UNET")
        emit_clip = (lane is not None and lane._lane == "CLIP")
        _fn_start_ns = time.monotonic_ns() if (emit_unet or emit_clip) else 0
        if emit_unet:
            lane._trace.emit("unet_model_patcher_constructor_start", phase="restore")
        elif emit_clip:
            lane._trace.emit("clip_model_patcher_constructor_start", phase="restore")
        _success = False
        result = None
        _ctor_dur_ms: float | None = None
        try:
            result = original(self, *args, **kwargs)
            _success = True
        finally:
            # ── Literal constructor timing ownership ──────────────────
            # The duration ends immediately after the native __init__
            # returns.  Helper installation below (ensure_sampling_timing_
            # wrapper / register_unet_forward_probe) runs AFTER this span.
            if emit_unet:
                _ctor_dur_ms = round((time.monotonic_ns() - _fn_start_ns) / 1_000_000, 3)
                lane._trace.emit("unet_model_patcher_constructor_end", phase="restore", metadata={
                    "duration_ms": _ctor_dur_ms})
                _children = _child_durations.get()
                if _children is not None:
                    _children.append(("model_patcher_constructor", _ctor_dur_ms))
            elif emit_clip:
                _ctor_dur_ms = round((time.monotonic_ns() - _fn_start_ns) / 1_000_000, 3)
                lane._trace.emit("clip_model_patcher_constructor_end", phase="restore", metadata={
                    "duration_ms": _ctor_dur_ms})
                # NOT recorded into _clip_cpu_prepare_children — nested inside
                # load_text_encoder_state_dicts which is the direct measured owner.
        if _success:
            # ── V2 native fast-disk UNET: record the exact patcher ──
            if _NATIVE_FAST_DISK_UNET and emit_unet:
                _fast_disk_record_patcher(self, duration_ms=_ctor_dur_ms)
            # Helpers execute AFTER the measured constructor span (never
            # inside it).  The SAMPLER_SAMPLE helper emits a concise
            # exception-type line and returns False on failure — never
            # silently swallows installation failure.
            if hasattr(self, "model_options"):
                from comfymodal_runtime.runtime_executor import ensure_sampling_timing_wrapper
                ensure_sampling_timing_wrapper(self)
            # Register every ModelPatcher for UNET first-CUDA timing.
            # Idempotent: duplicate registrations for the same diffusion_model
            # are silently ignored by register_unet_forward_probe.
            try:
                from comfymodal_runtime.unet_forward_probe import register_unet_forward_probe as _reg_unet
                _reg_unet(self, source="model_patcher_constructor")
            except Exception:
                pass
        return result
    setattr(wrapper, _SENTINEL_MODEL_PATCHER, True)
    return wrapper


def _make_model_to_wrapper(original):
    """Wrap ``model.to(...)`` with UNET-lane guard for direct ownership measurement.

    Under ``COMFYMODAL_V2_NATIVE_FAST_DISK_UNET`` (default off) the wrapper
    additionally defers exactly ONE eligible first UNET ``model.to(cuda)``
    call — the one native ``load_diffusion_model_state_dict`` performs
    between ModelPatcher construction and ``load_model_weights``.  The
    deferred REAL original ``model.to`` is replayed by the per-instance
    ``load_model_weights`` wrapper AFTER the bind.  When no fast-disk
    window is open (or the flag is off) the wrapper behaves exactly as
    before.
    """
    import functools as _ft

    @_ft.wraps(original)
    def wrapper(self, *args: Any, **kwargs: Any) -> Any:
        lane = _ACTIVE_LANE_TRACE.get()
        emit = (lane is not None and lane._lane == "UNET")
        # ── V2 native fast-disk UNET: try to defer exactly one to() ──
        if emit and _NATIVE_FAST_DISK_UNET:
            _decision = _fast_disk_maybe_defer_to(self, args, kwargs, lane, original)
            if _decision == "deferred":
                # The deferred real original to() is replayed after the bind
                # (load_model_weights wrapper).  Module.to returns self.
                return self
        _fn_start_ns = time.monotonic_ns() if emit else 0
        if emit:
            lane._trace.emit("unet_model_to_start", phase="restore")
        try:
            return original(self, *args, **kwargs)
        finally:
            if emit:
                _dur_ms = round((time.monotonic_ns() - _fn_start_ns) / 1_000_000, 3)
                lane._trace.emit("unet_model_to_end", phase="restore", metadata={
                    "duration_ms": _dur_ms})
                _children = _child_durations.get()
                if _children is not None:
                    _children.append(("model_to", _dur_ms))
    setattr(wrapper, _SENTINEL_MODEL_TO, True)
    return wrapper


# ── ModelPatcher.load aggregate-timing wrappers (narrow timers) ──────
# Four narrow wrappers installed alongside existing core/model_patcher
# wrappers.  Only active during an active request trace AND outer
# ModelPatcher.load scope.  Produce one summary event on outer exit:
#   model_patcher_load_breakdown
# with wall_ms, thread_cpu_ms, process_cpu_ms for total, plus traversal,
# patch_weight (count/wall/process), cast (count/wall/process), and
# residual wall/process.


def _make_model_patcher_load_breakdown_wrapper(original):
    """Wrap ModelPatcher.load / ModelPatcherDynamic.load with breakdown timing.

    Only emits ``model_patcher_load_breakdown`` when ``_ACTIVE_REQUEST_TRACE``
    is set and this is the outermost invocation.  Sets up a thread-local
    ``_model_patcher_breakdown`` dict consumed by the inner _load_list,
    patch_weight_to_device, and cast_to_device wrappers.
    """
    import functools as _ft

    @_ft.wraps(original)
    def wrapper(self, *args, **kwargs):
        before = _model_patcher_load_depth.get()
        _model_patcher_load_depth.set(before + 1)
        request_trace = _ACTIVE_REQUEST_TRACE.get()
        emit = (before == 0 and request_trace is not None)
        _breakdown = None
        if emit:
            _breakdown = {
                "outer_start_ns": time.monotonic_ns(),
                "outer_thread_start_ns": time.thread_time_ns() if hasattr(time, "thread_time_ns") else None,
                "outer_process_start_ns": time.process_time_ns() if hasattr(time, "process_time_ns") else None,
                "load_list_wall_ns": 0,
                "load_list_process_start_ns": None,
                "load_list_process_end_ns": None,
                "patch_weight_count": 0,
                "patch_weight_wall_ns": 0,
                "patch_weight_process_ns": 0,
                "cast_count": 0,
                "cast_wall_ns": 0,
                "cast_process_ns": 0,
            }
            _model_patcher_breakdown.set(_breakdown)
        try:
            return original(self, *args, **kwargs)
        finally:
            after = _model_patcher_load_depth.get()
            _model_patcher_load_depth.set(after - 1)
            if emit and _breakdown is not None:
                _outer_end_ns = time.monotonic_ns()
                _outer_thread_end_ns = time.thread_time_ns() if hasattr(time, "thread_time_ns") else None
                _outer_process_end_ns = time.process_time_ns() if hasattr(time, "process_time_ns") else None
                _wall_ms = round((_outer_end_ns - _breakdown["outer_start_ns"]) / 1_000_000, 3)
                _thread_ms = round((_outer_thread_end_ns - _breakdown["outer_thread_start_ns"]) / 1_000_000, 3) if _breakdown.get("outer_thread_start_ns") is not None and _outer_thread_end_ns is not None else None
                _process_ms = round((_outer_process_end_ns - _breakdown["outer_process_start_ns"]) / 1_000_000, 3) if _breakdown.get("outer_process_start_ns") is not None and _outer_process_end_ns is not None else None
                # Traversal (_load_list)
                _traversal_wall = round(_breakdown["load_list_wall_ns"] / 1_000_000, 3) if _breakdown["load_list_wall_ns"] else 0.0
                _traversal_process: float | None = None
                if _breakdown["load_list_process_start_ns"] is not None and _breakdown["load_list_process_end_ns"] is not None:
                    _traversal_process = round((_breakdown["load_list_process_end_ns"] - _breakdown["load_list_process_start_ns"]) / 1_000_000, 3)
                # Patch-weight aggregate
                _pw_wall = round(_breakdown["patch_weight_wall_ns"] / 1_000_000, 3) if _breakdown["patch_weight_wall_ns"] else 0.0
                _pw_process: float | None = None
                if _breakdown["patch_weight_process_ns"]:
                    _pw_process = round(_breakdown["patch_weight_process_ns"] / 1_000_000, 3)
                # Cast aggregate
                _cast_wall = round(_breakdown["cast_wall_ns"] / 1_000_000, 3) if _breakdown["cast_wall_ns"] else 0.0
                _cast_process: float | None = None
                if _breakdown["cast_process_ns"]:
                    _cast_process = round(_breakdown["cast_process_ns"] / 1_000_000, 3)
                # Residual
                _residual_wall = round(max(0.0, _wall_ms - _traversal_wall - _pw_wall), 3)
                _residual_process: float | None = None
                if _process_ms is not None and _traversal_process is not None and _pw_process is not None:
                    _residual_process = round(max(0.0, _process_ms - _traversal_process - _pw_process), 3)
                request_trace.emit("model_patcher_load_breakdown", phase="execution", metadata={
                    "request_id": str(request_trace.request_id),
                    "wall_ms": _wall_ms,
                    "thread_cpu_ms": _thread_ms,
                    "process_cpu_ms": _process_ms,
                    "traversal_wall_ms": _traversal_wall,
                    "traversal_process_cpu_ms": _traversal_process,
                    "patch_weight_count": _breakdown["patch_weight_count"],
                    "patch_weight_wall_ms": _pw_wall,
                    "patch_weight_process_cpu_ms": _pw_process,
                    "cast_count": _breakdown["cast_count"],
                    "cast_wall_ms": _cast_wall,
                    "cast_process_cpu_ms": _cast_process,
                    "residual_wall_ms": _residual_wall,
                    "residual_process_cpu_ms": _residual_process,
                })
                _model_patcher_breakdown.set(None)

    setattr(wrapper, _SENTINEL_MODEL_PATCHER_LOAD, True)
    return wrapper


def _make_model_patcher_load_list_breakdown_wrapper(original):
    """Wrap ``ModelPatcher._load_list`` with wall/process timing.

    Only accumulates when ``_model_patcher_breakdown`` is set (inside outer
    ModelPatcher.load under request trace).
    """
    import functools as _ft

    @_ft.wraps(original)
    def wrapper(self, *args, **kwargs):
        _bd = _model_patcher_breakdown.get()
        if _bd is not None:
            _bd["load_list_process_start_ns"] = time.process_time_ns() if hasattr(time, "process_time_ns") else None
            _load_list_start_ns = time.monotonic_ns()
        try:
            return original(self, *args, **kwargs)
        finally:
            if _bd is not None:
                _bd["load_list_wall_ns"] = time.monotonic_ns() - _load_list_start_ns
                _bd["load_list_process_end_ns"] = time.process_time_ns() if hasattr(time, "process_time_ns") else None

    setattr(wrapper, _SENTINEL_MODEL_PATCHER_LOAD_LIST, True)
    return wrapper


def _make_model_patcher_patch_weight_breakdown_wrapper(original):
    """Wrap ``ModelPatcher.patch_weight_to_device`` with count/wall/process aggregation.

    Accumulates into ``_model_patcher_breakdown`` when set (inside outer
    ModelPatcher.load under request trace).
    """
    import functools as _ft

    @_ft.wraps(original)
    def wrapper(self, key, device_to=None, inplace_update=False, return_weight=False, force_cast=False):
        _bd = _model_patcher_breakdown.get()
        if _bd is not None:
            _pw_start = time.monotonic_ns()
            _pw_process_start = time.process_time_ns() if hasattr(time, "process_time_ns") else None
        try:
            return original(self, key, device_to=device_to, inplace_update=inplace_update, return_weight=return_weight, force_cast=force_cast)
        finally:
            if _bd is not None:
                _bd["patch_weight_count"] += 1
                _bd["patch_weight_wall_ns"] += time.monotonic_ns() - _pw_start
                if _pw_process_start is not None:
                    _bd["patch_weight_process_ns"] += time.process_time_ns() - _pw_process_start

    setattr(wrapper, _SENTINEL_MODEL_PATCHER_PATCH_WEIGHT, True)
    return wrapper


def _make_cast_to_device_breakdown_wrapper(original):
    """Wrap ``comfy.model_management.cast_to_device`` with count/wall/process aggregation.

    Only accumulates when ``_model_patcher_breakdown`` is set (inside outer
    ModelPatcher.load under request trace).  Installed on the live
    ``comfy.model_management`` module.
    """
    import functools as _ft

    @_ft.wraps(original)
    def wrapper(tensor, device, dtype, copy=False):
        _bd = _model_patcher_breakdown.get()
        if _bd is not None:
            _cast_start = time.monotonic_ns()
            _cast_process_start = time.process_time_ns() if hasattr(time, "process_time_ns") else None
        try:
            return original(tensor, device, dtype, copy=copy)
        finally:
            if _bd is not None:
                _bd["cast_count"] += 1
                _bd["cast_wall_ns"] += time.monotonic_ns() - _cast_start
                if _cast_process_start is not None:
                    _bd["cast_process_ns"] += time.process_time_ns() - _cast_process_start

    setattr(wrapper, _SENTINEL_CAST_TO_DEVICE, True)
    return wrapper


# ── Model patcher wrapper installer ─────────────────────────────────

_model_patcher_wrappers_installed: bool = False


def _install_model_patcher_wrappers(trace: RuntimeTrace | None = None) -> dict[str, str]:
    """Install constructor and model.to wrappers on live comfy.model_patcher module.

    Targets ModelPatcher and CoreModelPatcher constructors plus model.to().
    Idempotent via per-sentinel flags.
    """
    global _model_patcher_wrappers_installed
    if _model_patcher_wrappers_installed:
        return {}
    result: dict[str, str] = {}
    mp_mod = _get_live_module("comfy.model_patcher")
    if mp_mod is None:
        return {"model_patcher_wrappers": "unavailable"}

    # Wrap ModelPatcher.__init__
    _ModelPatcher_cls = getattr(mp_mod, "ModelPatcher", None)
    if _ModelPatcher_cls is not None:
        _orig_init = getattr(_ModelPatcher_cls, "__init__", None)
        if callable(_orig_init) and not getattr(_orig_init, _SENTINEL_MODEL_PATCHER, False):
            setattr(_ModelPatcher_cls, "__init__", _make_model_patcher_constructor_wrapper(_orig_init))
            result["ModelPatcher.__init__"] = "installed"
        else:
            result["ModelPatcher.__init__"] = "already_installed" if _orig_init else "unavailable"
    else:
        result["ModelPatcher.__init__"] = "unavailable"

    # Wrap CoreModelPatcher.__init__
    _CoreMP_cls = getattr(mp_mod, "CoreModelPatcher", None)
    if _CoreMP_cls is not None:
        _orig_init = getattr(_CoreMP_cls, "__init__", None)
        if callable(_orig_init) and not getattr(_orig_init, _SENTINEL_MODEL_PATCHER, False):
            setattr(_CoreMP_cls, "__init__", _make_model_patcher_constructor_wrapper(_orig_init))
            result["CoreModelPatcher.__init__"] = "installed"
        else:
            result["CoreModelPatcher.__init__"] = "already_installed" if _orig_init else "unavailable"

    # Wrap model.to() — installed on torch.nn.Module so it catches any model.to() call.
    _torch_mod = _get_live_module("torch")
    if _torch_mod is not None:
        _nn_mod = getattr(_torch_mod, "nn", None)
        if _nn_mod is not None:
            _Module_cls = getattr(_nn_mod, "Module", None)
            if _Module_cls is not None:
                _orig_to = getattr(_Module_cls, "to", None)
                if callable(_orig_to) and not getattr(_orig_to, _SENTINEL_MODEL_TO, False):
                    setattr(_Module_cls, "to", _make_model_to_wrapper(_orig_to))
                    result["nn.Module.to"] = "installed"
                else:
                    result["nn.Module.to"] = "already_installed" if _orig_to else "unavailable"

    # Wrap ModelPatcher.load (aggregate-timing breakdown)
    if _ModelPatcher_cls is not None:
        _orig_load = getattr(_ModelPatcher_cls, "load", None)
        if callable(_orig_load) and not getattr(_orig_load, _SENTINEL_MODEL_PATCHER_LOAD, False):
            setattr(_ModelPatcher_cls, "load", _make_model_patcher_load_breakdown_wrapper(_orig_load))
            result["ModelPatcher.load"] = "installed"
        else:
            result["ModelPatcher.load"] = "already_installed" if _orig_load else "unavailable"

    # Wrap ModelPatcherDynamic.load
    _MPDynamic_cls = getattr(mp_mod, "ModelPatcherDynamic", None)
    if _MPDynamic_cls is not None:
        _orig_dyn_load = getattr(_MPDynamic_cls, "load", None)
        if callable(_orig_dyn_load) and not getattr(_orig_dyn_load, _SENTINEL_MODEL_PATCHER_LOAD, False):
            setattr(_MPDynamic_cls, "load", _make_model_patcher_load_breakdown_wrapper(_orig_dyn_load))
            result["ModelPatcherDynamic.load"] = "installed"
        else:
            result["ModelPatcherDynamic.load"] = "already_installed" if _orig_dyn_load else "unavailable"

    # Wrap ModelPatcher._load_list (traversal aggregate)
    if _ModelPatcher_cls is not None:
        _orig_load_list = getattr(_ModelPatcher_cls, "_load_list", None)
        if callable(_orig_load_list) and not getattr(_orig_load_list, _SENTINEL_MODEL_PATCHER_LOAD_LIST, False):
            setattr(_ModelPatcher_cls, "_load_list", _make_model_patcher_load_list_breakdown_wrapper(_orig_load_list))
            result["ModelPatcher._load_list"] = "installed"
        else:
            result["ModelPatcher._load_list"] = "already_installed" if _orig_load_list else "unavailable"

    # Wrap ModelPatcher.patch_weight_to_device (aggregate)
    if _ModelPatcher_cls is not None:
        _orig_pw = getattr(_ModelPatcher_cls, "patch_weight_to_device", None)
        if callable(_orig_pw) and not getattr(_orig_pw, _SENTINEL_MODEL_PATCHER_PATCH_WEIGHT, False):
            setattr(_ModelPatcher_cls, "patch_weight_to_device", _make_model_patcher_patch_weight_breakdown_wrapper(_orig_pw))
            result["ModelPatcher.patch_weight_to_device"] = "installed"
        else:
            result["ModelPatcher.patch_weight_to_device"] = "already_installed" if _orig_pw else "unavailable"

    if trace:
        for comp, status in result.items():
            trace.emit("model_patcher_wrapper_install", phase="restore",
                       metadata={"component": comp, "status": status})
    _model_patcher_wrappers_installed = True
    return result


# ── ModelPatcher load wrappers (idempotent, conditional on symbol presence) ──

# ModelPatcher sentinels — exact names per user contract
_SENTINEL_MODEL_PATCHER_LOAD_DIAG = "_comfy_modal_model_patcher_load_diag"
_SENTINEL_MODEL_PATCHER_LOAD_LIST_DIAG = "_comfy_modal_model_patcher_load_list_diag"
_SENTINEL_PATCH_WEIGHT_DIAG = "_comfy_modal_patch_weight_diag"
_SENTINEL_CAST_TO_DEVICE_DIAG = "_comfy_modal_cast_to_device_diag"
_SENTINEL_MP_LOAD = _SENTINEL_MODEL_PATCHER_LOAD_DIAG
_SENTINEL_MPD_LOAD = _SENTINEL_MODEL_PATCHER_LOAD_DIAG
_SENTINEL_LOAD_LIST = _SENTINEL_MODEL_PATCHER_LOAD_LIST_DIAG
_SENTINEL_PTW_DEVICE = _SENTINEL_PATCH_WEIGHT_DIAG
_SENTINEL_CTD = _SENTINEL_CAST_TO_DEVICE_DIAG

# ModelPatcher scope tracking — one aggregate record per outer load
_MODEL_PATCHER_LOAD_DEPTH: ContextVar[int] = ContextVar(
    "comfymodal_model_patcher_load_depth", default=0
)
_MODEL_PATCHER_BREAKDOWN: ContextVar[dict[str, Any] | None] = ContextVar(
    "comfymodal_model_patcher_breakdown", default=None
)

_mp_load_wrapper_installed: bool = False
_mpd_load_wrapper_installed: bool = False
_load_list_wrapper_installed: bool = False
_ptw_device_wrapper_installed: bool = False
_ctd_wrapper_installed: bool = False

_MP_WRAPPER_LOCK = RLock()


def _make_model_patcher_load_wrapper(original: Callable[..., Any]) -> Callable[..., Any]:
    """Wrap ``ModelPatcher.load`` with outermost aggregate timing.

    Records ``mp_load_start/end`` on the active request trace at outermost
    reentrancy only.  No tensor/model/path storage.  No CUDA synchronize.
    """
    import functools as _ft

    @_ft.wraps(original)
    def wrapper(self, device_to=None, lowvram_model_memory=0, force_patch_weights=False, full_load=False):
        before = getattr(wrapper, "_mp_load_depth", 0)
        setattr(wrapper, "_mp_load_depth", before + 1)
        request_trace = _ACTIVE_REQUEST_TRACE.get()
        _outer = before == 0 and request_trace is not None
        _start_ns = time.monotonic_ns() if _outer else 0
        if _outer:
            request_trace.emit("mp_load_start", phase="execution", metadata={
                "model_type": type(self).__qualname__,
            })
        try:
            return original(self, device_to=device_to, lowvram_model_memory=lowvram_model_memory,
                            force_patch_weights=force_patch_weights, full_load=full_load)
        finally:
            after = getattr(wrapper, "_mp_load_depth", 1)
            setattr(wrapper, "_mp_load_depth", after - 1)
            if _outer:
                _dur = round((time.monotonic_ns() - _start_ns) / 1_000_000, 3)
                request_trace.emit("mp_load_end", phase="execution", metadata={
                    "model_type": type(self).__qualname__,
                    "duration_ms": _dur,
                })
    setattr(wrapper, "_mp_load_depth", 0)
    setattr(wrapper, _SENTINEL_MP_LOAD, True)
    return wrapper


